 return cur;\n                },\n                { value: map[keys[0]], id: keys[0] }\n            );\n\n            setActiveSection(id);\n        };\n\n        const options = {\n            root: null,\n            rootMargin: '0px',\n            threshold: [0.5, 0.99],\n            /*\n                A 0.5 threshold takes care of observing changes in big sections, while the 0.99 takes care of small sections.\n                Using 0.99 instead of 1 should help in case intersectionRatio doesn't fully reach 1, which has been observed to happen\n            */\n        };\n\n        const observer = new IntersectionObserver(handleIntersect, options);\n        setObserver(observer);\n        return () => {\n            observer.disconnect();\n        };\n    }, [setActiveSection]);\n\n    return observer;\n};\n\nexport default useActiveSection;\n","import { forwardRef, HTMLAttributes, ReactNode, Ref } from 'react';\nimport { classnames } from '../../helpers';\n\ninterface Props extends HTMLAttributes<HTMLDivElement> {\n    className?: string;\n    children?: ReactNode;\n    hasToolbar?: boolean;\n    hasRowMode?: boolean;\n}\nconst PrivateMainArea = forwardRef(\n    ({ className, hasToolbar = false, children, hasRowMode = false, ...rest }: Props, ref: Ref<HTMLDivElement>) => {\n        return (\n            <main\n                className={classnames([\n                    hasToolbar ? 'main-area--with-toolbar' : 'main-area',\n                    hasRowMode ? 'main-area--row-mode' : '',\n                    'flex-item-fluid-auto relative',\n                    className,\n                ])}\n                ref={ref}\n                {...rest}\n            >\n                {children}\n            </main>\n        );\n    }\n);\n\nexport default PrivateMainArea;\n","import { HTMLAttributes } from 'react';\n\nexport type SubTitleProps = HTMLAttributes<HTMLHeadingElement>;\n\nconst SubTitle = ({ children, ...rest }: SubTitleProps) => <h2 {...rest}>{children}</h2>