Shared } from './interface';\nimport useActiveSection from './useActiveSection';\nimport PrivateMainArea from './PrivateMainArea';\nimport SubSettingsSection from './SubSettingsSection';\nimport { getIsSubsectionAvailable } from './helper';\n\ninterface Props extends SettingsPropsShared {\n    children: ReactNode;\n    setActiveSection?: (section: string) => void;\n}\n\nconst PrivateMainSettingsArea = ({ setActiveSection, location, children, config }: Props) => {\n    const mainAreaRef = useRef<HTMLDivElement>(null);\n    const useIntersectionSection = useRef(false);\n\n    const { text: title, description, subsections } = config;\n\n    useAppTitle(title);\n\n    useEffect(() => {\n        if (mainAreaRef.current) {\n            mainAreaRef.current.scrollTop = 0;\n        }\n    }, [location.pathname]);\n\n    useEffect(() => {\n        const { hash } = location;\n\n        if (!hash) {\n            useIntersectionSection.current = true;\n            return;\n        }\n\n        if (!mainAreaRef.current) {\n            return;\n        }\n        const mainArea = mainAreaRef.current;\n        const el = mainArea.querySelector(hash);\n        if (!el) {\n            return;\n        }\n\n        useIntersectionSection.current = false;\n        setActiveSection?.(hash.slice(1));\n\n        const abortScroll = createScrollIntoView(el, mainArea, true);\n        let removeListeners: () => void;\n\n        const abort = () => {\n            useIntersectionSection.current = true;\n            abortScroll();\n            removeListeners?.();\n        };\n\n        const options = {\n            passive: true,\n            capture: true,\n        };\n\n        // Abort on any user interaction such as scrolling, touching, or keyboard interaction\n        window.addEventListener('wheel', abort, options);\n        window.addEventListener('keydown', abort, options);\n        window.addEventListener('mousedown', abort, options);\n        window.addEventListener('touchstart', abort, options);\n        // Automatically abort after some time where it's assumed to have successfully scrolled into place.\n        const timeoutId = window.setTimeout(abort, 15000);\n\n        removeListeners = () => {\n            window.removeEventListener('wheel', abort, options);\n            window.removeEventListener('keydown', abort, options);\n            window.removeEventListener('mousedown', abort, options);\n            window.removeEventListener('touchstart', abort, options);\n            window.clearTimeout(timeoutId);\n        };\n\n        return () => {\n            abort();\n        };\n        // Listen to location instead of location.hash since it's possible to click the same #section multiple times and end up with a new entry in history\n    }, [location]);\n\n    // Don't always use the observer section observed value since it can not go to sections that are at the bottom or too small.\n    // In those cases it can be overridden by clicking on a specific section\n    const sectionObserver = useActiveSection(\n        useIntersectionSection.current && setActiveSection ? setActiveSection : noop\n    );\n\n    const wrappedSections = Children.toArray(children).map((child, i) => {\n        if (!isValidElement<{ observer: IntersectionObserver; className: string }>(child)) {\n            return null;\n        }\n        const config = subsections?.[i];\n        if (!config) {\n            throw new Error('Missing subsection');\n        }\n        //\n        if (!getIsSubsectionAvailable(config)) {\n            return null;\n        }\n        return (\n            <SubSettingsSection\n                key={config.id}\n                id={config.id}\n                title={config.text}\n                observer={sectionObserver}\n                className=\"container-section-sticky-section\"\n            >\n                {child}\n            </SubSettingsSection>\n        );\n    });\n\n    return (\n        <PrivateMainArea ref={mainAreaRef}>\n            <div className=\"container-section-sticky\">\n                <SettingsPageTitle className={classnames(['mt1-5', !description && 'mb1-5'])}>\n                    {title}\n                </SettingsPageTitle>\n                {description && <SettingsParagraph className=\"mb1-5\">{description}</SettingsParagraph>}\n                <ErrorBoundary>{wrappedSections}</ErrorBoundary>\n            </div>\n        </PrivateMainArea>\n    );\n};\n\nexport default PrivateMainSettingsArea;\n","import { c } from 'ttag';\nimport { Icon, Alert } from '../../components';\n\nconst MozillaInfoPanel = () => {\n    return (\n        <Alert className=\"mb1\" learnMore=\"https://support.mozilla.org/en-US/kb/protonvpn\" type=\"warning\">\n            <Icon name=\"exclamation-circle\" />\n            {c('Info').t`Your subscription is managed by Mozilla. Please contact Mozilla support.`}\n        </Alert>\n    );\n};\n\nexport default MozillaInfoPanel;\n","import { useEffect, useState } from 'react';\nimport { useLocation } from 'react-router-dom';\nimport { c } from 'ttag';\n\nimport { checkSubscription } from '@proton/shared/lib/api/payments';\nimport { DEFAULT_CURRENCY, DEFAULT_CYCLE } from '@proton/shared/lib/constants';\nimport { getIsB2BPlan, getPlanIDs } from '@proton/shared/lib/helpers/subscription';\nimport { Audience, Currency, PlanIDs, Subscription, SubscriptionCheckResponse } from '@proton/shared/lib/interfaces';\nimport { hasPlanIDs } from '@proton/shared/lib/helpers/planIDs';\n\nimport { Button, Icon, Loader } from '../../components';\nimport { useApi, useConfig, useLoading, usePlans, useSubscription } from '../../hooks';\n\nimport { getDefaultSelectedProductPlans } from './subscription/SubscriptionModal';\nimport MozillaInfoPanel from '../account/MozillaInfoPanel';\nimport { SUBSCRIPTION_STEPS } from './subscription/constants';\nimport PlanSelection from './subscription/PlanSelection';\nimport { useSubscriptionModal } from './subscription/SubscriptionModalProvider';\n\nconst FREE_SUBSCRIPTION = {} as Subscription;\n\nconst getSearchParams = (search: string) => {\n    const params = new URLSearchParams(search);\n    return {\n        audience: params.has('business') ? Audience.B2B : undefined,\n    };\n};\n\nconst PlansSection = () => {\n    const [loading, withLoading] = useLoading();\n    const [subscription = FREE_SUBSCRIPTION, loadingSubscription] = useSubscription();\n    const [plans = [], loadingPlans] = usePlans();\n    const { APP_NAME } = useConfig();\n    const api = useApi();\n    const location = useLocation();\n    const currentPlanIDs = getPlanIDs(subscription);\n    const searchParams = getSearchParams(location.search);\n    const [audience, setAudience] = useState(searchParams.audience || Audience.B2C);\n    const [selectedProductPlans, setSelectedProductPlans] = useState(() => {\n        return getDefaultSelectedProductPlans(APP_NAME, getPlanIDs(subscription));\n    });\n    const [open] = useSubscriptionModal();\n\n    const [currency, setCurrency] = useState<Currency>(DEFAULT_CURRENCY);\n    const [cycle, setCycle] = useState(DEFAULT_CYCLE);\n    const { CouponCode } = subscription;\n\n    const handleModal = async (newPlanIDs: PlanIDs) => {\n        if (!hasPlanIDs(newPlanIDs)) {\n            throw new Error('Downgrade not supported');\n        }\n\n        const couponCode = CouponCode || undefined; // From current subscription; CouponCode can be null\n        const { Coupon } = await api<SubscriptionCheckResponse>(\n            checkSubscription({\n                Plans: newPlanIDs,\n                Currency: currency,\n                Cycle: cycle,\n                CouponCode: couponCode,\n            })\n        );\n\n        open({\n            planIDs: newPlanIDs,\n            coupon: Coupon?.Code,\n            step: SUBSCRIPTION_STEPS.CUSTOMIZATION,\n            cycle,\n            currency,\n            defaultAudience: Object.keys(newPlanIDs).some((planID) => getIsB2BPlan(planID as any))\n                ? Audience.B2B\n                : Audience.B2C,\n        });\n    };\n\n    useEffect(() => {\n        if (loadingPlans || loadingSubscription) {\n            return;\n        }\n        const [{ Currency } = { Currency: undefined }] = plans;\n        setCurrency(subscription.Currency || Currency);\n        setCycle(subscription.Cycle || DEFAULT_CYCLE);\n        setSelectedProductPlans(getDefaultSelectedProductPlans(APP_NAME, getPlanIDs(subscription)));\n    }, [loadingSubscription, loadingPlans]);\n\n    // @ts-ignore\n    if (subscription.isManagedByMozilla) {\n        return <MozillaInfoPanel />;\n    }\n\n    if (loadingSubscription || loadingPlans) {\n        return <Loader />;\n    }\n\n    return (\n        <>\n            <PlanSelection\n                mode=\"settings\"\n                audience={audience}\n                onChangeAudience={setAudience}\n                loading={loading}\n                plans={plans}\n                currency={currency}\n                cycle={cycle}\n                onChangeCycle={setCycle}\n                planIDs={currentPlanIDs}\n                hasFreePlan={false}\n                hasPlanSelectionComparison={false}\n                subscription={subscription}\n                onChangePlanIDs={(planIDs) => {\n                    void withLoading(handleModal(planIDs));\n                }}\n                onChangeCurrency={setCurrency}\n                selectedProductPlans={selectedProductPlans}\n                onChangeSelectedProductPlans={setSelectedProductPlans}\n            />\n            <Button\n                color=\"norm\"\n                shape=\"ghost\"\n                className=\"flex center flex-align-items-center mb1\"\n                onClick={() => {\n                    open({ step: SUBSCRIPTION_STEPS.PLAN_SELECTION, defaultAudience: audience });\n                }}\n            >\n                {c('Action').t`View plans details`}\n                <Icon name=\"arrow-right\" className=\"ml0-5 on-rtl-mirror\" />\n            </Button>\n        </>\n    );\n};\n\nexport default PlansSection;\n","import { useCallback } from 'react';\nimport { CalendarsModel } from '@proton/shared/lib/models/calendarsModel';\nimport { CalendarWithMembers } from '@proton/shared/lib/interfaces/calendar';\nimport useApi from './useApi';\nimport useCache from './useCache';\nimport useCachedModelResult, { getPromiseValue } from './useCachedModelResult';\n\nexport const useGetCalendars = (): (() => Promise<CalendarWithMembers[] | undefined>) => {\n    const api = useApi();\n    const cache = useCache();\n    const miss = useCallback(() => CalendarsModel.get(api), [api]);\n    return useCallback(() => {\n        return getPromiseValue(cache, CalendarsModel.key, miss);\n    }, [cache, miss]);\n};\n\nexport const useCalendars = (): [CalendarWithMembers[] | undefined, boolean, any] => {\n    const cache = useCache();\n    const miss = useGetCalendars();\n    return useCachedModelResult(cache, CalendarsModel.key, miss);\n};\n\nexport default useCalendars;\n","import { c, msgid } from 'ttag';\nimport { Address, Organization, UserModel } from '@proton/shared/lib/interfaces';\nimport humanSize from '@proton/shared/lib/helpers/humanSize';\nimport percentage from '@proton/shared/lib/helpers/percentage';\nimport isTruthy from '@proton/shared/lib/helpers/isTruthy';\nimport { Calendar } from '@proton/shared/lib/interfaces/calendar';\n\nimport { StripedList, StripedItem, Meter, IconName, Icon } from '../../../components';\n\ninterface Item {\n    icon: IconName;\n    text: string;\n}\n\ninterface Props {\n    organization?: Organization;\n    user: UserModel;\n    addresses?: Address[];\n    calendars?: Calendar[];\n}\n\nconst UsagePanel = ({ addresses, calendars, organization, user }: Props) => {\n    const { UsedMembers = 0 } = organization || {};\n\n    if (UsedMembers <= 1) {\n        return null;\n    }\n\n    const humanUsedSpace = humanSize(user.UsedSpace);\n    const humanMaxSpace = humanSize(user.MaxSpace);\n    const UsedAddresses = addresses?.length;\n    const UsedCalendars = calendars?.length;\n    const maxVpn = 10;\n\n    const items: (Item | false)[] = [\n        UsedAddresses !== undefined && {\n            icon: 'envelope',\n            text: c('Subscription attribute').ngettext(\n                msgid`${UsedAddresses} address`,\n                `${UsedAddresses} addresses`,\n                UsedAddresses\n            ),\n        },\n        UsedCalendars !== undefined && {\n            icon: 'calendar-checkmark',\n            text: c('Subscription attribute').ngettext(\n                msgid`${UsedCalendars} calendar`,\n                `${UsedCalendars} calendars`,\n                UsedCalendars\n            ),\n        },\n        {\n            icon: 'brand-proton-vpn',\n            text: user.hasPaidVpn\n                ? c('Subscription attribute').ngettext(\n                      msgid`${maxVpn} high-speed VPN connection`,\n                      `${maxVpn} high-speed VPN connections`,\n                      maxVpn\n                  )\n                : c('Subscription attribute').t`1 VPN connection`,\n        },\n    ];\n\n    return (\n        <div className=\"border rounded px2 py1-5 pt0-5 your-account-usage-container\">\n            <h3>\n                <strong>{c('new_plans: Title').t`Your account's usage`}</strong>\n            </h3>\n            <StripedList>\n                <StripedItem left={<Icon className=\"color-success\" name=\"storage\" size={20} />}>\n                    <span id=\"usedSpaceLabel\" className=\"block\">{c('new_plans: Label')\n                        .t`${humanUsedSpace} of ${humanMaxSpace}`}</span>\n                    <Meter\n                        className=\"mt1 mb1\"\n                        aria-hidden=\"true\"\n                        value={Math.ceil(percentage(user.MaxSpace, user.UsedSpace))}\n                    />\n                </StripedItem>\n                {items.filter(isTruthy).map((item) => {\n                    return (\n                        <StripedItem\n                            key={item.icon}\n                            left={<Icon className=\"color-success\" name={item.icon} size={20} />}\n                        >\n                            {item.text}\n                        </StripedItem>\n                    );\n                })}\n            </StripedList>\n        </div>\n    );\n};\n\nexport default UsagePanel;\n","import { c, msgid } from 'ttag';\nimport {\n    PLANS,\n    PLAN_NAMES,\n    APPS,\n    DEFAULT_CURRENCY,\n    CYCLE,\n    BRAND_NAME,\n    VPN_CONNECTIONS,\n    MAX_CALENDARS_FREE,\n    MAX_CALENDARS_PAID,\n} from '@proton/shared/lib/constants';\nimport { getHasB2BPlan, getPrimaryPlan, hasVPN, isTrial } from '@proton/shared/lib/helpers/subscription';\nimport {\n    Subscription,\n    Organization,\n    Address,\n    UserModel,\n    VPNServers,\n    VPNCountries,\n} from '@proton/shared/lib/interfaces';\nimport { FREE_PLAN } from '@proton/shared/lib/subscription/freePlans';\nimport percentage from '@proton/shared/lib/helpers/percentage';\nimport isTruthy from '@proton/shared/lib/helpers/isTruthy';\nimport humanSize from '@proton/shared/lib/helpers/humanSize';\nimport { MAX_CALENDARS_PER_USER } from '@proton/shared/lib/calendar/constants';\nimport { getFreeServers, getPlusServers } from '@proton/shared/lib/vpn/features';\n\nimport { useConfig } from '../../../hooks';\nimport { Price, StripedList, StripedItem, Meter, Button, IconName, Icon } from '../../../components';\nimport { OpenSubscriptionModalCallback } from './SubscriptionModalProvider';\nimport { SUBSCRIPTION_STEPS } from './constants';\nimport {\n    getB2BHighSpeedVPNConnectionsText,\n    getFreeVPNConnectionTotal,\n    getHighSpeedVPNConnectionsText,\n    getVPNConnectionsText,\n} from '../features/vpn';\n\ninterface Item {\n    icon: IconName;\n    text: string;\n}\n\ninterface Props {\n    user: UserModel;\n    subscription?: Subscription;\n    organization?: Organization;\n    vpnServers?: VPNServers;\n    vpnCountries?: VPNCountries;\n    addresses?: Address[];\n    openSubscriptionModal: OpenSubscriptionModalCallback;\n}\n\nconst SubscriptionPanel = ({\n    vpnServers,\n    vpnCountries,\n    subscription,\n    organization,\n    user,\n    addresses,\n    openSubscriptionModal,\n}: Props) => {\n    const { APP_NAME } = useConfig();\n\n    const isVpnApp = APP_NAME === APPS.PROTONVPN_SETTINGS;\n\n    const primaryPlan = getPrimaryPlan(subscription, APP_NAME);\n    const planTitle = primaryPlan?.Title || PLAN_NAMES[FREE_PLAN.Name as PLANS];\n\n    const cycle = subscription?.Cycle ?? CYCLE.MONTHLY;\n    const amount = (subscription?.Amount ?? 0) / cycle;\n\n    const hasAddresses = Array.isArray(addresses) && addresses.length > 0;\n\n    const {\n        UsedDomains = 0,\n        MaxDomains = 0,\n        UsedSpace = user.UsedSpace,\n        MaxSpace = user.MaxSpace,\n        UsedAddresses: OrganizationUsedAddresses,\n        MaxAddresses: OrganizationMaxAddresses,\n        UsedMembers = 1,\n        MaxMembers = 1,\n    } = organization || {};\n\n    const humanUsedSpace = humanSize(UsedSpace);\n    const humanMaxSpace = humanSize(MaxSpace);\n    const UsedAddresses = hasAddresses ? OrganizationUsedAddresses || 1 : 0;\n    const MaxAddresses = OrganizationMaxAddresses || 1;\n\n    const handleCustomizeSubscription = () =>\n        openSubscriptionModal({\n            step: SUBSCRIPTION_STEPS.CUSTOMIZATION,\n            disablePlanSelection: true,\n        });\n    const handleExplorePlans = () =>\n        openSubscriptionModal({\n            step: SUBSCRIPTION_STEPS.PLAN_SELECTION,\n        });\n    const handleEditPayment = () =>\n        openSubscriptionModal({\n            step: SUBSCRIPTION_STEPS.CHECKOUT,\n            disablePlanSelection: true,\n        });\n\n    if (!user.canPay) {\n        return null;\n    }\n\n    // Hide this panel for trial case\n    if (subscription && isTrial(subscription)) {\n        return null;\n    }\n\n    const getVpnAppFree = () => {\n        return (\n            <StripedList>\n                {(\n                    [\n                        {\n                            icon: 'brand-proton-vpn',\n                            text: getVPNConnectionsText(1),\n                        } as const,\n                        {\n                            icon: 'earth',\n                            text: getFreeServers(vpnServers?.free_vpn, vpnCountries?.free_vpn.count),\n                        } as const,\n                    ] as Item[]\n                ).map((item) => {\n                    return (\n                        <StripedItem\n                            key={item.icon}\n                            left={<Icon className=\"color-success\" name={item.icon} size={20} />}\n                        >\n                            {item.text}\n                        </StripedItem>\n                    );\n                })}\n            </StripedList>\n        );\n    };\n\n    const getVpnPlus = () => {\n        const maxVpn = 10;\n        const items: Item[] = [\n            {\n                icon: 'brand-proton-vpn',\n                text: c('Subscription attribute').ngettext(\n                    msgid`High-speed VPN on ${maxVpn} device`,\n                    `High-speed VPN on ${maxVpn} devices`,\n                    maxVpn\n                ),\n            },\n            {\n                icon: 'shield',\n                text: c('Subscription attribute').t`Built-in ad blocker (NetShield)`,\n            },\n            {\n                icon: 'play',\n                text: c('Subscription attribute').t`Access to streaming services globally`,\n            },\n            {\n                icon: 'earth',\n                text: getPlusServers(vpnServers?.[PLANS.VPN], vpnCountries?.[PLANS.VPN].count),\n            },\n        ];\n        return (\n            <StripedList>\n                {items.map((item) => {\n                    return (\n                        <StripedItem\n                            key={item.icon}\n                            left={<Icon className=\"color-success\" name={item.icon} size={20} />}\n                        >\n                            {item.text}\n                        </StripedItem>\n                    );\n                })}\n            </StripedList>\n        );\n    };\n\n    const getDefault = () => {\n        const items: (Item | false)[] = [\n            (MaxMembers > 1 || getHasB2BPlan(subscription)) && {\n                icon: 'users',\n                text: c('Subscription attribute').ngettext(\n                    msgid`${UsedMembers} of ${MaxMembers} user`,\n                    `${UsedMembers} of ${MaxMembers} users`,\n                    MaxMembers\n                ),\n            },\n            {\n                icon: 'envelope',\n                text:\n                    MaxAddresses === 1 && UsedAddresses === 1\n                        ? c('Subscription attribute').t`1 email address`\n                        : c('Subscription attribute').ngettext(\n                              msgid`${UsedAddresses} of ${MaxAddresses} email address`,\n                              `${UsedAddresses} of ${MaxAddresses} email addresses`,\n                              MaxAddresses\n                          ),\n            },\n            !!MaxDomains && {\n                icon: 'globe',\n                text: c('Subscription attribute').ngettext(\n                    msgid`${UsedDomains} of ${MaxDomains} custom domain`,\n                    `${UsedDomains} of ${MaxDomains} custom domains`,\n                    MaxDomains\n                ),\n            },\n            {\n                icon: 'calendar-checkmark',\n                text: (() => {\n                    if (MaxMembers > 1) {\n                        const n = MAX_CALENDARS_PER_USER;\n                        return c('Subscription attribute').ngettext(\n                            msgid`${n} calendar per user`,\n                            `${n} calendars per user`,\n                            n\n                        );\n                    }\n                    const n = user.isFree ? MAX_CALENDARS_FREE : MAX_CALENDARS_PAID;\n                    return c('Subscription attribute').ngettext(msgid`${n} calendar`, `${n} calendars`, n);\n                })(),\n            },\n            {\n                icon: 'brand-proton-vpn',\n                text: (() => {\n                    if (user.hasPaidVpn) {\n                        if (MaxMembers > 1) {\n                            return getB2BHighSpeedVPNConnectionsText(VPN_CONNECTIONS);\n                        }\n                        return getHighSpeedVPNConnectionsText(VPN_CONNECTIONS);\n                    }\n                    if (MaxMembers > 1) {\n                        return getFreeVPNConnectionTotal();\n                    }\n                    return getVPNConnectionsText(1);\n                })(),\n            },\n        ];\n        return (\n            <StripedList>\n                <StripedItem left={<Icon className=\"color-success\" name=\"storage\" size={20} />}>\n                    <span className=\"block\">{c('Label').t`${humanUsedSpace} of ${humanMaxSpace}`}</span>\n                    <Meter className=\"mt1 mb1\" aria-hidden=\"true\" value={Math.ceil(percentage(MaxSpace, UsedSpace))} />\n                </StripedItem>\n                {items.filter(isTruthy).map((item) => {\n                    return (\n                        <StripedItem\n                            key={item.icon}\n                            left={<Icon className=\"color-success\" name={item.icon} size={20} />}\n                        >\n                            {item.text}\n                        </StripedItem>\n                    );\n                })}\n            </StripedList>\n        );\n    };\n\n    return (\n        <div className=\"border rounded px2 py1-5 subscription-panel-container\">\n            <div className=\"flex flex-nowrap flex-align-items-center flex-justify-space-between pt0-5\">\n                <h3 className=\"m0\">\n                    <strong>{planTitle}</strong>\n                </h3>\n                <Price\n                    className=\"h3 m0 color-weak\"\n                    currency={subscription?.Currency || DEFAULT_CURRENCY}\n                    suffix={subscription && amount ? c('Suffix').t`/month` : ''}\n                >\n                    {amount}\n                </Price>\n            </div>\n            {(() => {\n                if (user.isFree && isVpnApp) {\n                    return getVpnAppFree();\n                }\n                if (hasVPN(subscription)) {\n                    return getVpnPlus();\n                }\n                return getDefault();\n            })()}\n            {user.isPaid && user.canPay ? (\n                <Button onClick={handleEditPayment} className=\"mb0-5\" size=\"large\" color=\"norm\" fullWidth>{c('Action')\n                    .t`Edit billing details`}</Button>\n            ) : null}\n            {user.isPaid && user.canPay && getHasB2BPlan(subscription) ? (\n                <Button\n                    onClick={handleCustomizeSubscription}\n                    className=\"mb0-5\"\n                    size=\"large\"\n                    color=\"weak\"\n                    shape=\"outline\"\n                    fullWidth\n                >{c('Action').t`Customize plan`}</Button>\n            ) : null}\n            {user.canPay ? (\n                <Button onClick={handleExplorePlans} size=\"large\" color=\"norm\" shape=\"ghost\" fullWidth>{c('Action')\n                    .t`Explore other ${BRAND_NAME} plans`}</Button>\n            ) : null}\n        </div>\n    );\n};\n\nexport default SubscriptionPanel;\n","import { ReactNode } from 'react';\nimport { c, msgid } from 'ttag';\nimport { format, fromUnixTime } from 'date-fns';\nimport {\n    CYCLE,\n    DEFAULT_CURRENCY,\n    PLANS,\n    APPS,\n    BRAND_NAME,\n    VPN_CONNECTIONS,\n    MAIL_APP_NAME,\n} from '@proton/shared/lib/constants';\nimport isTruthy from '@proton/shared/lib/helpers/isTruthy';\nimport {\n    hasMailPro,\n    hasMail,\n    hasDrive,\n    hasVPN,\n    isTrial,\n    getHasLegacyPlans,\n} from '@proton/shared/lib/helpers/subscription';\nimport { Plan, Subscription, UserModel } from '@proton/shared/lib/interfaces';\nimport { MAX_CALENDARS_PER_USER } from '@proton/shared/lib/calendar/constants';\nimport { getAppName } from '@proton/shared/lib/apps/helper';\nimport humanSize from '@proton/shared/lib/helpers/humanSize';\n\nimport { StripedList, StripedItem, Button, Price, IconName, Icon } from '../../../components';\nimport { OpenSubscriptionModalCallback } from './SubscriptionModalProvider';\nimport { SUBSCRIPTION_STEPS } from './constants';\nimport './UpsellPanel.scss';\n\ninterface UpsellBoxProps {\n    title: string;\n    children?: ReactNode;\n    items: Item[];\n    actions: ReactNode;\n    description?: ReactNode;\n}\n\nconst UpsellBox = ({ title, items, children, actions, description }: UpsellBoxProps) => {\n    return (\n        <div className=\"border border-primary rounded px2 py1-5 pt0-5 upsell-box\">\n            <h3>\n                <strong>{title}</strong>\n            </h3>\n            {children}\n            {description && <div className=\"color-weak text-lg\">{description}</div>}\n            <StripedList>\n                {items.map((item) => {\n                    return (\n                        <StripedItem\n                            key={item.text}\n                            left={<Icon className=\"color-success\" name=\"checkmark\" size={20} />}\n                        >\n                            {item.text}\n                        </StripedItem>\n                    );\n                })}\n            </StripedList>\n            {actions}\n        </div>\n    );\n};\n\ninterface Item {\n    icon: IconName;\n    text: string;\n}\n\ninterface Props {\n    subscription?: Subscription;\n    plans: Plan[];\n    user: UserModel;\n    openSubscriptionModal: OpenSubscriptionModalCallback;\n}\n\nconst getHighSpeedVPN = (connections: number) => {\n    return c('new_plans: attribute').ngettext(\n        msgid`Get ${connections} high-speed VPN connection`,\n        `Get ${connections} high-speed VPN connections`,\n        connections\n    );\n};\n\nconst getHighSpeedVPNB2B = (connections: number) => {\n    return c('new_plans: attribute').ngettext(\n        msgid`Get ${connections} high-speed VPN connection per user`,\n        `Get ${connections} high-speed VPN connections per user`,\n        connections\n    );\n};\n\nconst getUpgradeText = (planName: string) => {\n    return c('new_plans: Title').t`Upgrade to ${planName}`;\n};\n\nconst UpsellPanel = ({ subscription, plans, user, openSubscriptionModal }: Props) => {\n    if (!user.canPay || !subscription) {\n        return null;\n    }\n\n    if (getHasLegacyPlans(subscription)) {\n        return null;\n    }\n\n    // Trial upsell\n    const mailPlan = plans.find(({ Name }) => Name === PLANS.MAIL);\n    if (isTrial(subscription) && subscription.PeriodEnd && mailPlan) {\n        const mailPlanName = mailPlan.Title;\n        const formattedTrialExpirationDate = format(fromUnixTime(subscription.PeriodEnd || 0), 'MMMM d, y');\n        const calendarAppName = getAppName(APPS.PROTONCALENDAR);\n        const handleUpgrade = () =>\n            openSubscriptionModal({\n                plan: PLANS.MAIL,\n                step: SUBSCRIPTION_STEPS.CHECKOUT,\n                disablePlanSelection: true,\n            });\n        const handleExplorePlans = () =>\n            openSubscriptionModal({\n                step: SUBSCRIPTION_STEPS.PLAN_SELECTION,\n            });\n        const storageSize = humanSize(15 * 1024 ** 3, undefined, undefined, 0);\n        const items: Item[] = [\n            {\n                icon: 'storage',\n                text: c('new_plans: Upsell attribute').t`${storageSize} total storage`,\n            },\n            {\n                icon: 'envelope',\n                text: c('new_plans: Upsell attribute').t`10 email addresses/aliases`,\n            },\n            {\n                icon: 'tag',\n                text: c('new_plans: Upsell attribute').t`Unlimited folders, labels, and filters`,\n            },\n            {\n                icon: 'speech-bubble',\n                text: c('new_plans: Upsell attribute').t`Unlimited messages`,\n            },\n            {\n                icon: 'globe',\n                text: c('new_plans: Upsell attribute').t`Support for 1 custom email domain`,\n            },\n            {\n                icon: 'life-ring',\n                text: c('new_plans: Upsell attribute').t`Priority support`,\n            },\n            {\n                icon: 'brand-proton-calendar',\n                text: calendarAppName,\n            },\n        ];\n        return (\n            <UpsellBox\n                title={c('new_plans: Title').t`${mailPlanName} Trial`}\n                items={items}\n                actions={\n                    <>\n                        <Button onClick={handleUpgrade} size=\"large\" color=\"norm\" shape=\"solid\" fullWidth>{c(\n                            'new_plans: Action'\n                        ).t`Upgrade now`}</Button>\n                        <Button\n                            onClick={handleExplorePlans}\n                            size=\"large\"\n                            color=\"norm\"\n                            shape=\"ghost\"\n                            className=\"mt0-5\"\n                            fullWidth\n                        >{c('new_plans: Action').t`Explore all ${BRAND_NAME} plans`}</Button>\n                    </>\n                }\n            >\n                <h4>{c('new_plans: Info').t`Your trial ends ${formattedTrialExpirationDate}`}</h4>\n                <div className=\"color-weak\">\n                    {c('new_plans: Info')\n                        .t`To continue to use ${MAIL_APP_NAME} with premium features, choose your subscription and payment options.`}\n                    <br />\n                    <br />\n                    {c('new_plans: Info')\n                        .t`Otherwise access to your account will be limited, and your account will eventually be disabled.`}\n                </div>\n            </UpsellBox>\n        );\n    }\n\n    const cycle = CYCLE.TWO_YEARS;\n\n    const bundlePlan = plans.find(({ Name }) => Name === PLANS.BUNDLE);\n    const bundleStorage = humanSize(bundlePlan?.MaxSpace ?? 500, undefined, undefined, 0);\n    // Bundle upsell\n    if ((user.isFree || hasMail(subscription) || hasDrive(subscription) || hasVPN(subscription)) && bundlePlan) {\n        const plan = bundlePlan;\n        const price = (\n            <Price\n                key=\"plan-price\"\n                currency={subscription?.Currency || DEFAULT_CURRENCY}\n                suffix={c('new_plans: Plan frequency').t`/month`}\n            >\n                {(plan.Pricing[cycle] || 0) / cycle}\n            </Price>\n        );\n        const handleUpgrade = () =>\n            openSubscriptionModal({\n                cycle,\n                plan: PLANS.BUNDLE,\n                step: SUBSCRIPTION_STEPS.CHECKOUT,\n                disablePlanSelection: true,\n            });\n        const numberOfPersonalCalendars = MAX_CALENDARS_PER_USER;\n        const items: (Item | undefined)[] = [\n            {\n                icon: 'storage',\n                text: c('new_plans: Upsell attribute').t`Boost your storage space to ${bundleStorage} total`,\n            },\n            {\n                icon: 'checkmark-circle',\n                text: c('new_plans: Upsell attribute')\n                    .t`Add more personalization with 15 email addresses and support for 3 custom email domains`,\n            },\n            !hasMail(subscription)\n                ? {\n                      icon: 'calendar-checkmark',\n                      text: c('new_plans: Upsell attribute').ngettext(\n                          msgid`Create up to ${numberOfPersonalCalendars} personal calendar`,\n                          `Create up to ${numberOfPersonalCalendars} personal calendars`,\n                          numberOfPersonalCalendars\n                      ),\n                  }\n                : undefined,\n            {\n                icon: 'brand-proton-vpn',\n                text: getHighSpeedVPN(VPN_CONNECTIONS),\n            },\n            {\n                icon: 'checkmark-circle',\n                text: c('new_plans: Upsell attribute').t`Access advanced VPN features`,\n            },\n        ];\n        return (\n            <UpsellBox\n                title={getUpgradeText(plan.Title)}\n                description={c('new_plans: Info')\n                    .t`Upgrade to the ultimate privacy pack and access all premium Proton services.`}\n                items={items.filter(isTruthy)}\n                actions={\n                    <Button onClick={handleUpgrade} size=\"large\" color=\"norm\" shape=\"solid\" fullWidth>\n                        {c('new_plans: Action').jt`From ${price}`}\n                    </Button>\n                }\n            />\n        );\n    }\n\n    const businessPlan = plans.find(({ Name }) => Name === PLANS.BUNDLE_PRO);\n    const businessStorage = humanSize(businessPlan?.MaxSpace ?? 500, undefined, undefined, 0);\n    // Mail pro upsell\n    if (hasMailPro(subscription) && businessPlan) {\n        const plan = businessPlan;\n        const price = (\n            <Price\n                key=\"plan-price\"\n                currency={subscription?.Currency || DEFAULT_CURRENCY}\n                suffix={c('new_plans: Plan frequency').t`/month`}\n            >\n                {(plan.Pricing[cycle] || 0) / cycle}\n            </Price>\n        );\n        const handleUpgrade = () =>\n            openSubscriptionModal({\n                cycle,\n                plan: PLANS.BUNDLE_PRO,\n                step: SUBSCRIPTION_STEPS.CUSTOMIZATION,\n                disablePlanSelection: true,\n            });\n        const items: Item[] = [\n            {\n                icon: 'storage',\n                text: c('new_plans: Upsell attribute').t`Boost your storage space to ${businessStorage} per user`,\n            },\n            {\n                icon: 'envelope',\n                text: c('new_plans: Upsell attribute').t`Get 5 additional email addresses per user`,\n            },\n            {\n                icon: 'globe',\n                text: c('new_plans: Upsell attribute').t`Cover more ground with support for 10 custom email domains`,\n            },\n            {\n                icon: 'brand-proton-vpn',\n                text: getHighSpeedVPNB2B(VPN_CONNECTIONS),\n            },\n        ];\n        return (\n            <UpsellBox\n                title={getUpgradeText(plan.Title)}\n                description={c('new_plans: Info')\n                    .t`Upgrade to the business pack with access to all premium Proton services.`}\n                items={items}\n                actions={\n                    <Button onClick={handleUpgrade} size=\"large\" color=\"norm\" shape=\"solid\" fullWidth>\n                        {c('new_plans: Action').jt`From ${price} per user`}\n                    </Button>\n                }\n            />\n        );\n    }\n\n    return null;\n};\n\nexport default UpsellPanel;\n","import { Loader } from '../../../components';\nimport {\n    useAddresses,\n    useCalendars,\n    useOrganization,\n    useSubscription,\n    useUser,\n    usePlans,\n    useVPNCountriesCount,\n    useVPNServersCount,\n} from '../../../hooks';\nimport MozillaInfoPanel from '../../account/MozillaInfoPanel';\nimport UsagePanel from './UsagePanel';\nimport { useSubscriptionModal } from './SubscriptionModalProvider';\nimport SubscriptionPanel from './SubscriptionPanel';\nimport UpsellPanel from './UpsellPanel';\n\nimport './YourPlanSection.scss';\n\nconst YourPlanSection = () => {\n    const [user] = useUser();\n    const [plans = [], loadingPlans] = usePlans();\n    const [addresses] = useAddresses();\n    const [calendars] = useCalendars();\n    const [subscription, loadingSubscription] = useSubscription();\n    const [organization, loadingOrganization] = useOrganization();\n    const [vpnCountries] = useVPNCountriesCount();\n    const [vpnServers] = useVPNServersCount();\n    const [openSubscriptionModal] = useSubscriptionModal();\n\n    const loading = loadingSubscription || loadingOrganization || loadingPlans;\n\n    if (loading) {\n        return <Loader />;\n    }\n\n    const { isManagedByMozilla } = subscription;\n\n    if (isManagedByMozilla) {\n        return <MozillaInfoPanel />;\n    }\n\n    return (\n        <div className=\"your-plan-section-container flex-gap-2\">\n            <SubscriptionPanel\n                subscription={subscription}\n                organization={organization}\n                user={user}\n                addresses={addresses}\n                vpnCountries={vpnCountries}\n                vpnServers={vpnServers}\n                openSubscriptionModal={openSubscriptionModal}\n            />\n            <UpsellPanel\n                subscription={subscription}\n                plans={plans}\n                user={user}\n                openSubscriptionModal={openSubscriptionModal}\n            />\n            <UsagePanel addresses={addresses} calendars={calendars} organization={organization} user={user} />\n        </div>\n    );\n};\nexport default YourPlanSection;\n","import { ComponentPropsWithoutRef } from 'react';\nimport { classnames } from '../../helpers';\n\nconst SettingsSection = ({ className, ...rest }: ComponentPropsWithoutRef<'div'>) => {\n    return <div className={classnames(['max-w46e', className])} {...rest} />;\n};\n\nexport default SettingsSection;\n","import { c } from 'ttag';\nimport { DEFAULT_CYCLE, DEFAULT_CURRENCY } from '@proton/shared/lib/constants';\nimport { Currency, Cycle } from '@proton/shared/lib/interfaces';\n\nimport Price, { Props as PriceProps } from '../../../components/price/Price';\n\ninterface Props extends Omit<PriceProps, 'suffix' | 'children'> {\n    quantity?: number;\n    amount?: number;\n    cycle?: Cycle;\n    currency?: Currency;\n    suffix?: string;\n}\n\nconst PlanPrice = ({\n    quantity = 1,\n    amount = 0,\n    cycle = DEFAULT_CYCLE,\n    currency = DEFAULT_CURRENCY,\n    suffix,\n    ...rest\n}: Props) => {\n    return (\n        <Price currency={currency} suffix={suffix || c('Suffix').t`/month`} {...rest}>\n            {(quantity * amount) / cycle}\n        </Price>\n    );\n};\n\nexport default PlanPrice;\n","import { c, msgid } from 'ttag';\nimport { PLANS } from '@proton/shared/lib/constants';\nimport { unique } from '@proton/shared/lib/helpers/array';\nimport {\n    getBaseAmount,\n    getHasLegacyPlans,\n    hasVisionary,\n    getCycleDiscount,\n} from '@proton/shared/lib/helpers/subscription';\nimport humanSize from '@proton/shared/lib/helpers/humanSize';\nimport { Plan } from '@proton/shared/lib/interfaces';\nimport { toMap } from '@proton/shared/lib/helpers/object';\n\nimport { Loader, Time } from '../../components';\nimport { useOrganization, usePlans, useSubscription, useUser } from '../../hooks';\nimport { classnames } from '../../helpers';\nimport { SettingsSection } from '../account';\nimport MozillaInfoPanel from '../account/MozillaInfoPanel';\nimport { formatPlans } from './subscription/helpers';\nimport DiscountBadge from './DiscountBadge';\nimport PlanPrice from './subscription/PlanPrice';\nimport CycleDiscountBadge from './CycleDiscountBadge';\nimport Price from '../../components/price/Price';\nimport { getDueCycleText, getTotalBillingText } from './helper';\n\nconst getRenewalText = (periodEnd: number) => {\n    const formattedEndTime = <Time key=\"time-text\">{periodEnd}</Time>;\n    return c('Billing cycle').jt`Renews automatically on ${formattedEndTime}`;\n};\n\nconst BillingSection = () => {\n    const [{ hasPaidMail, hasPaidVpn }] = useUser();\n    const [plans = [], loadingPlans] = usePlans();\n    const plansMap = toMap(plans, 'Name');\n    const [subscription, loadingSubscription] = useSubscription();\n    const [organization, loadingOrganization] = useOrganization();\n\n    if (loadingSubscription || loadingPlans || loadingOrganization) {\n        return <Loader />;\n    }\n\n    if (subscription.isManagedByMozilla) {\n        return <MozillaInfoPanel />;\n    }\n\n    const { Plans = [], Cycle, Currency, CouponCode, Amount, PeriodEnd } = subscription;\n    const { plan, mailPlan, vpnPlan, addressAddon, domainAddon, memberAddon, vpnAddon, spaceAddon } =\n        formatPlans(Plans);\n    const subTotal = unique(Plans.map(({ Name }) => Name)).reduce((acc, planName) => {\n        return acc + getBaseAmount(planName as PLANS, plansMap, subscription, Cycle);\n    }, 0);\n    const discount = subTotal - Amount;\n    const spaceBonus = organization?.BonusSpace;\n    const vpnBonus = organization?.BonusVPN;\n    const maxUsers = organization?.MaxMembers || 1;\n\n    const priceRowClassName = 'flex w100 mb1';\n    const priceLabelClassName = 'flex-item-fluid';\n    const weakRowClassName = classnames([priceRowClassName, 'color-weak']);\n\n    const getCycleBadge = (plan: Plan) => {\n        const cycleDiscount = getCycleDiscount(Cycle, plan.Name, plansMap);\n        if (cycleDiscount) {\n            return (\n                <span className=\"ml0-5\">\n                    <CycleDiscountBadge cycle={Cycle} discount={cycleDiscount} />\n                </span>\n            );\n        }\n        return null;\n    };\n\n    const hasLegacyPlans = getHasLegacyPlans(subscription);\n\n    const usersText = maxUsers\n        ? c('Title').ngettext(msgid`${maxUsers} user`, `${maxUsers} users`, maxUsers)\n        : undefined;\n\n    const addons = (\n        <>\n            {memberAddon && hasLegacyPlans ? (\n                <div className={weakRowClassName}>\n                    <div className={priceLabelClassName}>\n                        +{' '}\n                        {c('Addon unit for subscription').ngettext(\n                            msgid`${memberAddon.MaxMembers} user`,\n                            `${memberAddon.MaxMembers} users`,\n                            memberAddon.MaxMembers\n                        )}\n                        {getCycleBadge(memberAddon)}\n                    </div>\n                    <div className=\"text-right\">\n                        <PlanPrice\n                            amount={getBaseAmount(memberAddon.Name, plansMap, subscription, Cycle)}\n                            currency={Currency}\n                            cycle={Cycle}\n                        />\n                    </div>\n                </div>\n            ) : null}\n            {addressAddon ? (\n                <div className={weakRowClassName}>\n                    <div className={priceLabelClassName}>\n                        +{' '}\n                        {c('Addon unit for subscription').ngettext(\n                            msgid`${addressAddon.MaxAddresses} address`,\n                            `${addressAddon.MaxAddresses} addresses`,\n                            addressAddon.MaxAddresses\n                        )}\n                        {getCycleBadge(addressAddon)}\n                    </div>\n                    <div className=\"text-right\">\n                        <PlanPrice\n                            amount={getBaseAmount(addressAddon.Name, plansMap, subscription, Cycle)}\n                            currency={Currency}\n                            cycle={Cycle}\n                        />\n                    </div>\n                </div>\n            ) : null}\n            {domainAddon ? (\n                <div className={weakRowClassName}>\n                    <div className={priceLabelClassName}>\n                        +{' '}\n                        {c('Addon unit for subscription').ngettext(\n                            msgid`${domainAddon.MaxDomains} domain`,\n                            `${domainAddon.MaxDomains} domains`,\n                            domainAddon.MaxDomains\n                        )}\n                        {getCycleBadge(domainAddon)}\n                    </div>\n                    <div className=\"text-right\">\n                        <PlanPrice\n                            amount={getBaseAmount(domainAddon.Name, plansMap, subscription, Cycle)}\n                            currency={Currency}\n                            cycle={Cycle}\n                        />\n                    </div>\n                </div>\n            ) : null}\n            {spaceAddon ? (\n                <div className={weakRowClassName}>\n                    <div className={priceLabelClassName}>\n                        + {humanSize(spaceAddon.MaxSpace)} {c('Label').t`extra storage`}\n                    </div>\n                    {getCycleBadge(spaceAddon)}\n                    <div className=\"text-right\">\n                        <PlanPrice\n                            amount={getBaseAmount(spaceAddon.Name, plansMap, subscription, Cycle)}\n                            currency={Currency}\n                            cycle={Cycle}\n                        />\n                    </div>\n                </div>\n            ) : null}\n            {spaceBonus ? (\n                <div className={weakRowClassName}>\n                    <div className={priceLabelClassName}>\n                        + {humanSize(spaceBonus)} {c('Label').t`bonus storage`}\n                    </div>\n                    <div className=\"text-right\">\n                        <PlanPrice amount={0} currency={Currency} cycle={Cycle} />\n                    </div>\n                </div>\n            ) : null}\n        </>\n    );\n\n    return (\n        <SettingsSection>\n            {!hasLegacyPlans && plan ? (\n                <div className=\"border-bottom on-mobile-pb1\">\n                    <div className={classnames([priceRowClassName, 'text-bold'])}>{plan.Title}</div>\n                    <div className={weakRowClassName}>\n                        <div className={priceLabelClassName}>\n                            {usersText}\n                            {getCycleBadge(plan)}\n                        </div>\n                        <div className=\"text-right\">\n                            <PlanPrice\n                                amount={\n                                    getBaseAmount(plan.Name, plansMap, subscription, Cycle) +\n                                    (memberAddon ? getBaseAmount(memberAddon.Name, plansMap, subscription, Cycle) : 0)\n                                }\n                                currency={Currency}\n                                cycle={Cycle}\n                            />\n                        </div>\n                    </div>\n                    {addons}\n                </div>\n            ) : null}\n            {hasLegacyPlans && hasPaidMail ? (\n                <div className=\"border-bottom on-mobile-pb1\">\n                    {mailPlan ? (\n                        <div className={classnames([priceRowClassName, 'text-bold'])}>\n                            <div className={priceLabelClassName}>\n                                {mailPlan.Title}\n                                {getCycleBadge(mailPlan)}\n                            </div>\n                            <div className=\"text-right\">\n                                <PlanPrice\n                                    amount={getBaseAmount(mailPlan.Name, plansMap, subscription, Cycle)}\n                                    currency={Currency}\n                                    cycle={Cycle}\n                                />\n                            </div>\n                        </div>\n                    ) : null}\n                    {addons}\n                </div>\n            ) : null}\n            {hasLegacyPlans && hasPaidVpn && !hasVisionary(subscription) ? (\n                <div className=\"border-bottom pt1 on-mobile-pb1\">\n                    {vpnPlan ? (\n                        <div className={classnames([priceRowClassName, 'text-bold'])}>\n                            <div className={priceLabelClassName}>\n                                {vpnPlan.Title}\n                                {getCycleBadge(vpnPlan)}\n                            </div>\n                            <div className=\"text-right\">\n                                <PlanPrice\n                                    amount={getBaseAmount(vpnPlan.Name, plansMap, subscription, Cycle)}\n                                    currency={Currency}\n                                    cycle={Cycle}\n                                />\n                            </div>\n                        </div>\n                    ) : null}\n                    {vpnAddon ? (\n                        <div className={weakRowClassName}>\n                            <div className={priceLabelClassName}>\n                                +{' '}\n                                {c('Addon unit for subscription').ngettext(\n                                    msgid`${vpnAddon.MaxVPN} connection`,\n                                    `${vpnAddon.MaxVPN} connections`,\n                                    vpnAddon.MaxVPN\n                                )}\n                                {getCycleBadge(vpnAddon)}\n                            </div>\n                            <div className=\"text-right\">\n                                <PlanPrice\n                                    amount={getBaseAmount(vpnAddon.Name, plansMap, subscription, Cycle)}\n                                    currency={Currency}\n                                    cycle={Cycle}\n                                />\n                            </div>\n                        </div>\n                    ) : null}\n                    {vpnBonus ? (\n                        <div className={weakRowClassName}>\n                            <div className={priceLabelClassName}>\n                                +{' '}\n                                {c('Addon unit for subscription').ngettext(\n                                    msgid`${vpnBonus} connection`,\n                                    `${vpnBonus} connections`,\n                                    vpnBonus\n                                )}\n                            </div>\n                            <div className=\"text-right\">\n                                <PlanPrice amount={0} currency={Currency} cycle={Cycle} />\n                            </div>\n                        </div>\n                    ) : null}\n                </div>\n            ) : null}\n            {discount > 0 ? (\n                <>\n                    <div className=\"border-bottom pt1 on-mobile-pb1\">\n                        <div className={classnames([priceRowClassName, 'text-bold'])}>\n                            <div className={priceLabelClassName}>{getTotalBillingText(Cycle)}</div>\n                            <div className=\"text-right\">\n                                <Price currency={Currency}>{subTotal}</Price>\n                            </div>\n                        </div>\n                        <div className={weakRowClassName}>\n                            <div className={classnames([priceLabelClassName, 'flex flex-align-items-center'])}>\n                                {CouponCode ? (\n                                    <div className=\"\">\n                                        {c('Coupon').t`Coupon applied: ${CouponCode}`}{' '}\n                                        <DiscountBadge code={CouponCode}>\n                                            {Math.round((Math.abs(discount) / subTotal) * 100)}%\n                                        </DiscountBadge>\n                                    </div>\n                                ) : (\n                                    <div className=\"\">{c('Label').t`Discount`}</div>\n                                )}\n                            </div>\n                            <div className=\"text-right\">\n                                <Price currency={Currency}>{-discount}</Price>\n                            </div>\n                        </div>\n                    </div>\n                    <div className=\"pt1\">\n                        <div className={classnames([priceRowClassName, 'text-bold'])}>\n                            <div className={priceLabelClassName}>{getDueCycleText(Cycle)}</div>\n                            <div className=\"text-right\">\n                                <Price currency={Currency}>{Amount}</Price>\n                            </div>\n                        </div>\n                    </div>\n                </>\n            ) : (\n                <div className=\"pt1\">\n                    <div className={classnames([priceRowClassName, 'text-bold'])}>\n                        <div className={priceLabelClassName}>{getTotalBillingText(Cycle)}</div>\n                        <div className=\"text-right\">\n                            <Price currency={Currency}>{Amount}</Price>\n                        </div>\n                    </div>\n                </div>\n            )}\n            <div className={classnames([weakRowClassName, 'text-right mt1'])}>\n                <div className=\"text-right w100\">{getRenewalText(PeriodEnd)}</div>\n            </div>\n        </SettingsSection>\n    );\n};\n\nexport default BillingSection;\n","import { DetailedHTMLProps, HTMLAttributes, ReactNode } from 'react';\nimport { classnames } from '../../helpers';\n\ninterface Props extends DetailedHTMLProps<HTMLAttributes<HTMLDivElement>, HTMLDivElement> {\n    children?: ReactNode;\n    className?: string;\n    collapseOnMobile?: boolean;\n}\n\nconst Row = ({ children, className = '', collapseOnMobile = true, ...rest }: Props) => {\n    return (\n        <div\n            className={classnames(['flex flex-nowrap mb1', collapseOnMobile && 'on-mobile-flex-column', className])}\n            {...rest}\n        >\n            {children}\n        </div>\n    );\n};\n\nexport default Row;\n","import PropTypes from 'prop-types';\n\nconst Field = ({ children, className }) => {\n    return <div className={['field-container', className].filter(Boolean).join(' ')}>{children}</div>;\n};\n\nField.propTypes = {\n    children: PropTypes.node,\n    className: PropTypes.string,\n};\n\nexport default Field;\n","import { Currency } from '@proton/shared/lib/interfaces';\n\nimport { Button, ButtonProps, Price } from '../../components';\nimport { classnames } from '../../helpers';\n\ninterface Props extends Omit<ButtonProps, 'onSelect' | 'onClick'> {\n    value?: number;\n    amount?: number;\n    currency?: Currency;\n    onSelect: (value: number) => void;\n}\n\nconst AmountButton = ({ value = 0, amount = 0, currency, onSelect, className = '', ...rest }: Props) => {\n    return (\n        <Button\n            aria-pressed={value === amount}\n            className={classnames([className, value === amount && 'is-active'])}\n            onClick={() => onSelect(value)}\n            {...rest}\n        >\n            <Price currency={currency}>{value}</Price>\n        </Button>\n    );\n};\n\nexport default AmountButton;\n","import { useState } from 'react';\nimport { c } from 'ttag';\nimport { isNumber } from '@proton/shared/lib/helpers/validators';\nimport { Currency } from '@proton/shared/lib/interfaces';\n\nimport { Input, Label } from '../../components';\nimport CurrencySelector from './CurrencySelector';\nimport AmountButton from './AmountButton';\n\ninterface Props {\n    currency?: Currency;\n    amount: number;\n    onChangeCurrency: (currency: Currency) => void;\n    onChangeAmount: (amount: number) => void;\n    maxAmount?: number;\n    minAmount?: number;\n}\n\nconst PaymentSelector = ({ currency, amount, onChangeCurrency, onChangeAmount, minAmount, maxAmount }: Props) => {\n    const [inputValue, setInputValue] = useState('');\n\n    const handleButton = (value: number) => {\n        setInputValue('');\n        onChangeAmount(value);\n    };\n\n    return (\n        <>\n            <div className=\"flex-autogrid on-mobile-flex-column\">\n                <div className=\"flex-autogrid-item on-mobile-mb0-5\">\n                    <AmountButton className=\"w100\" onSelect={handleButton} value={500} amount={amount} />\n                </div>\n                <div className=\"flex-autogrid-item on-mobile-mb0-5\">\n                    <AmountButton className=\"w100\" onSelect={handleButton} value={1000} amount={amount} />\n                </div>\n                <div className=\"flex-autogrid-item on-mobile-mb0-5\">\n                    <AmountButton className=\"w100\" onSelect={handleButton} value={5000} amount={amount} />\n                </div>\n                <div className=\"flex-autogrid-item on-mobile-mb0-5\">\n                    <AmountButton className=\"w100\" onSelect={handleButton} value={10000} amount={amount} />\n                </div>\n            </div>\n            <div className=\"flex-autogrid on-mobile-flex-column\">\n                <div className=\"flex-autogrid-item on-mobile-mb0-5\">\n                    <Label htmlFor=\"otherAmount\" className=\"sr-only\">{c('Label').t`Other amount`}</Label>\n                    <Input\n                        className=\"w100\"\n                        onChange={({ target }) => {\n                            if (target.value === '') {\n                                setInputValue('');\n                                onChangeAmount(0);\n                                return;\n                            }\n                            if (!isNumber(target.value)) {\n                                return;\n                            }\n                            const value = Number(target.value);\n                            if (minAmount && value < minAmount / 100) {\n                                return;\n                            }\n                            if (maxAmount && value > maxAmount / 100) {\n                                return;\n                            }\n                            setInputValue(`${value}`);\n                            onChangeAmount(Math.floor(value * 100));\n                        }}\n                        onBlur={() => {\n                            setInputValue(`${amount / 100}`);\n                        }}\n                        value={inputValue}\n                        id=\"otherAmount\"\n                        placeholder={c('Placeholder').t`Other`}\n                    />\n                </div>\n                <div className=\"flex-autogrid-item on-mobile-mb0-5\">\n                    <CurrencySelector className=\"w100\" currency={currency} onSelect={onChangeCurrency} />\n                </div>\n            </div>\n        </>\n    );\n};\n\nexport default PaymentSelector;\n","import { PAYMENT_METHOD_TYPE, PAYMENT_METHOD_TYPES } from '@proton/shared/lib/constants';\nimport { Currency } from '@proton/shared/lib/interfaces';\nimport { c } from 'ttag';\nimport { Row, Label, Field } from '../../components';\nimport PaymentSelector from './PaymentSelector';\n\ninterface Props {\n    method?: PAYMENT_METHOD_TYPE;\n    amount: number;\n    onChangeAmount: (value: number) => void;\n    currency?: Currency;\n    onChangeCurrency: (currency: Currency) => void;\n}\n\nconst AmountRow = ({ method, amount, onChangeAmount, currency, onChangeCurrency }: Props) => {\n    if (method === PAYMENT_METHOD_TYPES.CASH) {\n        return null;\n    }\n    return (\n        <Row>\n            <Label>{c('Label').t`Amount`}</Label>\n            <Field>\n                <PaymentSelector\n                    amount={amount}\n                    onChangeAmount={onChangeAmount}\n                    currency={currency}\n                    onChangeCurrency={onChangeCurrency}\n                />\n            </Field>\n        </Row>\n    );\n};\n\nexport default AmountRow;\n","import { PAYMENT_METHOD_TYPE, PAYMENT_METHOD_TYPES } from '@proton/shared/lib/constants';\nimport { c } from 'ttag';\n\nimport { Alert } from '../../components';\n\ninterface Props {\n    method?: PAYMENT_METHOD_TYPE;\n}\nconst PaymentInfo = ({ method }: Props) => {\n    if (method && [PAYMENT_METHOD_TYPES.BITCOIN, PAYMENT_METHOD_TYPES.CASH].includes(method as any)) {\n        return null;\n    }\n\n    return (\n        <Alert className=\"mb1\">{c('Info')\n            .t`Your payment details are protected with TLS encryption and Swiss privacy laws.`}</Alert>\n    );\n};\n\nexport default PaymentInfo;\n","import { useState } from 'react';\nimport { c } from 'ttag';\nimport { buyCredit } from '@proton/shared/lib/api/payments';\nimport {\n    APPS,\n    DEFAULT_CURRENCY,\n    DEFAULT_CREDITS_AMOUNT,\n    MIN_CREDIT_AMOUNT,\n    PAYMENT_METHOD_TYPES,\n} from '@proton/shared/lib/constants';\nimport { Currency } from '@proton/shared/lib/interfaces';\nimport { getKnowledgeBaseUrl } from '@proton/shared/lib/helpers/url';\n\nimport {\n    ModalTwo,\n    ModalTwoHeader,\n    ModalTwoContent,\n    ModalTwoFooter,\n    ModalProps,\n    Form,\n    Button,\n    PrimaryButton,\n    Alert,\n    useDebounceInput,\n} from '../../components';\nimport { useNotifications, useEventManager, useConfig, useModals, useApi, useLoading } from '../../hooks';\n\nimport AmountRow from './AmountRow';\nimport PaymentInfo from './PaymentInfo';\nimport Payment from './Payment';\nimport usePayment from './usePayment';\nimport { handlePaymentToken } from './paymentTokenHelper';\nimport StyledPayPalButton from './StyledPayPalButton';\nimport { PaymentParameters } from './interface';\n\nconst getCurrenciesI18N = () => ({\n    EUR: c('Monetary unit').t`Euro`,\n    CHF: c('Monetary unit').t`Swiss franc`,\n    USD: c('Monetary unit').t`Dollar`,\n});\n\nconst CreditsModal = (props: ModalProps) => {\n    const api = useApi();\n    const { APP_NAME } = useConfig();\n    const { call } = useEventManager();\n    const { createModal } = useModals();\n    const { createNotification } = useNotifications();\n    const [loading, withLoading] = useLoading();\n    const [currency, setCurrency] = useState<Currency>(DEFAULT_CURRENCY);\n    const [amount, setAmount] = useState(DEFAULT_CREDITS_AMOUNT);\n    const debouncedAmount = useDebounceInput(amount);\n    const i18n = getCurrenciesI18N();\n    const i18nCurrency = i18n[currency];\n\n    const handleSubmit = async (params: PaymentParameters) => {\n        const requestBody = await handlePaymentToken({\n            params: { ...params, Amount: debouncedAmount, Currency: currency },\n            api,\n            createModal,\n        });\n        await api(buyCredit(requestBody));\n        await call();\n        props.onClose?.();\n        createNotification({ text: c('Success').t`Credits added` });\n    };\n\n    const { card, setCard, cardErrors, handleCardSubmit, method, setMethod, parameters, canPay, paypal, paypalCredit } =\n        usePayment({\n            amount: debouncedAmount,\n            currency,\n            onPay: handleSubmit,\n        });\n\n    const submit =\n        debouncedAmount >= MIN_CREDIT_AMOUNT ? (\n            method === PAYMENT_METHOD_TYPES.PAYPAL ? (\n                <StyledPayPalButton paypal={paypal} amount={debouncedAmount} />\n            ) : (\n                <PrimaryButton loading={loading} disabled={!canPay} type=\"submit\">{c('Action')\n                    .t`Top up`}</PrimaryButton>\n            )\n        ) : null;\n\n    return (\n        <ModalTwo\n            className=\"credits-modal\"\n            size=\"large\"\n            as={Form}\n            onSubmit={() => {\n                if (!handleCardSubmit()) {\n                    return;\n                }\n                withLoading(handleSubmit(parameters));\n            }}\n            {...props}\n        >\n            <ModalTwoHeader title={c('Title').t`Add credits`} />\n            <ModalTwoContent>\n                <PaymentInfo method={method} />\n                <Alert\n                    className=\"mb1\"\n                    learnMore={\n                        APP_NAME === APPS.PROTONVPN_SETTINGS\n                            ? 'https://protonvpn.com/support/vpn-credit-proration/'\n                            : getKnowledgeBaseUrl('/credit-proration-coupons')\n                    }\n                >{c('Info')\n                    .jt`Top up your account with credits that you can use to subscribe to a new plan or renew your current plan. You get one credit for every ${i18nCurrency} spent.`}</Alert>\n                <AmountRow\n                    method={method}\n                    amount={amount}\n                    onChangeAmount={setAmount}\n                    currency={currency}\n                    onChangeCurrency={setCurrency}\n                />\n                <Payment\n                    type=\"credit\"\n                    method={method}\n                    amount={debouncedAmount}\n                    currency={currency}\n                    card={card}\n                    onMethod={setMethod}\n                    onCard={setCard}\n                    cardErrors={cardErrors}\n                    paypal={paypal}\n                    paypalCredit={paypalCredit}\n                    noMaxWidth\n                />\n            </ModalTwoContent>\n\n            <ModalTwoFooter>\n                <Button onClick={props.onClose}>{c('Action').t`Close`}</Button>\n                {submit}\n            </ModalTwoFooter>\n        </ModalTwo>\n    );\n};\n\nexport default CreditsModal;\n","import { c } from 'ttag';\n\nimport { useModals, useUser } from '../../hooks';\n\nimport { Button } from '../../components';\nimport { SettingsSection, SettingsParagraph } from '../account';\nimport CreditsModal from './CreditsModal';\n\nconst CreditsSection = () => {\n    const { createModal } = useModals();\n\n    const handleAddCreditsClick = () => {\n        createModal(<CreditsModal />);\n    };\n\n    const [{ Credit }] = useUser();\n\n    return (\n        <SettingsSection>\n            <SettingsParagraph>\n                {c('Info')\n                    .t`When your subscription renews, we will apply any available credits before we charge the payment method above.`}\n            </SettingsParagraph>\n            <div className=\"mb2\">\n                <Button shape=\"outline\" onClick={handleAddCreditsClick}>{c('Action').t`Add credits`}</Button>\n            </div>\n            <div className=\"pl1 pr1 mb1 flex flex-justify-space-between\">\n                <span className=\"text-bold\">{c('Credits').t`Unused credits`}</span>\n                <span className=\"text-bold\">{Credit / 100}</span>\n            </div>\n            <hr />\n        </SettingsSection>\n    );\n};\n\nexport default CreditsSection;\n","import { useCallback, useReducer, useRef } from 'react';\nimport useIsMounted from './useIsMounted';\n\nconst DEFAULT_STATE = {\n    loading: false,\n};\n\nconst reducer = (state, action) => {\n    switch (action.type) {\n        case 'loading':\n            return {\n                ...state,\n                loading: true,\n            };\n        case 'success':\n            return {\n                error: undefined,\n                loading: false,\n                result: action.payload,\n            };\n        default:\n        case 'error':\n            return {\n                result: undefined,\n                loading: false,\n                error: action.payload,\n            };\n    }\n};\n\nconst useAsync = (setResults = true) => {\n    const [{ loading, result, error }, dispatch] = useReducer(reducer, DEFAULT_STATE);\n    const isMounted = useIsMounted();\n    const promiseRef = useRef();\n\n    const run = useCallback(async (promise) => {\n        const isCurrentPromise = () => promiseRef.current === promise;\n        promiseRef.current = promise;\n\n        dispatch({ type: 'loading' });\n        try {\n            const data = await promise;\n            if (isMounted() && isCurrentPromise()) {\n                dispatch({ type: 'success', payload: setResults ? data : undefined });\n            }\n            return data;\n        } catch (e) {\n            if (isMounted() && isCurrentPromise() && e.name !== 'AbortError') {\n                dispatch({ type: 'error', payload: setResults ? e : undefined });\n            }\n            throw e;\n        }\n    }, []);\n\n    return {\n        result,\n        error,\n        loading,\n        run,\n    };\n};\n\nexport default useAsync;\n","import { useCallback } from 'react';\nimport useAsync from './useAsync';\nimport useApi from './useApi';\nimport { QueryFunction } from './useApiResult';\n\ninterface Result<R, U extends any[]> {\n    loading: boolean;\n    request: (...args: U) => Promise<R>;\n}\n\nconst useApiWithoutResult = <R, F extends QueryFunction = QueryFunction>(fn: F): Result<R, Parameters<F>> => {\n    const request = useApi();\n    const { loading, run } = useAsync(false);\n\n    const requestAndSetLoading = useCallback(\n        (...args) => {\n            const promise = request<R>(fn(...args));\n            run(promise);\n            return promise;\n        },\n        [request, run, fn]\n    );\n\n    return {\n        loading,\n        request: requestAndSetLoading,\n    };\n};\n\nexport default useApiWithoutResult;\n","import { ChangeEvent, useState } from 'react';\nimport { c } from 'ttag';\nimport { validateCredit, buyCredit } from '@proton/shared/lib/api/payments';\nimport { requiredValidator } from '@proton/shared/lib/helpers/formValidators';\n\nimport { useLoading, useEventManager, useNotifications, useApiWithoutResult } from '../../hooks';\n\nimport { Button, InputFieldTwo, useFormErrors } from '../../components';\nimport SettingsParagraph from '../account/SettingsParagraph';\nimport { SettingsSection } from '../account';\n\nconst GiftCodeSection = () => {\n    const [value, setValue] = useState('');\n    const { validator, reset, onFormSubmit } = useFormErrors();\n    const [loading, withLoading] = useLoading();\n    const { request: requestBuyCredit } = useApiWithoutResult(buyCredit);\n    const { request: requestValidateCredit } = useApiWithoutResult(validateCredit);\n    const { call } = useEventManager();\n    const { createNotification } = useNotifications();\n\n    const handleChange = ({ target }: ChangeEvent<HTMLInputElement>) => {\n        setValue(target.value.replace(/\\s|\\t/g, '').toUpperCase());\n    };\n\n    const submit = async () => {\n        await requestValidateCredit({ GiftCode: value });\n        await requestBuyCredit({ GiftCode: value, Amount: 0 });\n        await call();\n        setValue('');\n        reset();\n        createNotification({ text: c('Success').t`Gift code applied` });\n    };\n\n    return (\n        <SettingsSection>\n            <SettingsParagraph>\n                {c('Info').t`If you have a gift code, enter it below to apply your discount.`}\n            </SettingsParagraph>\n\n            <label htmlFor=\"gift-code-input\" className=\"sr-only\">\n                {c('Label').t`Gift code`}\n            </label>\n\n            <form\n                className=\"gift-code_container flex flex-nowrap flex-align-items-start on-mobile-flex-column-no-stretch\"\n                onSubmit={(e) => {\n                    e.preventDefault();\n                    if (onFormSubmit()) {\n                        withLoading(submit());\n                    }\n                }}\n            >\n                <InputFieldTwo\n                    id=\"gift-code-input\"\n                    rootClassName=\"mr1 on-mobile-mr0 on-mobile-mb0-5\"\n                    value={value}\n                    error={validator([requiredValidator(value)])}\n                    placeholder={c('Placeholder').t`Add gift code`}\n                    onChange={handleChange}\n                />\n                <Button\n                    className=\"on-mobile-flex-align-self-start flex-item-noshrink\"\n                    color=\"norm\"\n                    type=\"submit\"\n                    loading={loading}\n                >\n                    {c('Action').t`Submit`}\n                </Button>\n            </form>\n        </SettingsSection>\n    );\n};\n\nexport default GiftCodeSection;\n","import { c } from 'ttag';\n\nimport { MAIL_APP_NAME, PLAN_SERVICES, VPN_APP_NAME } from '@proton/shared/lib/constants';\nimport { hasBit } from '@proton/shared/lib/helpers/bitset';\nimport { UserModel } from '@proton/shared/lib/interfaces';\n\nimport { Alert, AlertModal, Button, ModalProps } from '../../components';\n\ninterface Props extends ModalProps {\n    user: UserModel;\n    onConfirm: () => void;\n}\n\nconst { MAIL, VPN } = PLAN_SERVICES;\n\nconst DowngradeModal = ({ user, onConfirm, onClose, ...rest }: Props) => {\n    const hasMail = hasBit(user.Services, MAIL);\n    const hasVpn = hasBit(user.Services, VPN);\n    const hasBundle = hasMail && hasVpn;\n\n    return (\n        <AlertModal\n            title={c('Title').t`Confirm downgrade`}\n            buttons={[\n                <Button\n                    onClick={() => {\n                        onConfirm();\n                        onClose?.();\n                    }}\n                    color=\"norm\"\n                >\n                    {c('Action').t`Downgrade`}\n                </Button>,\n                <Button onClick={onClose}>{c('Action').t`Cancel`}</Button>,\n            ]}\n            onClose={onClose}\n            {...rest}\n        >\n            <Alert className=\"mb1\" type=\"error\">\n                {(() => {\n                    if (hasBundle) {\n                        return c('Info')\n                            .t`If you proceed with the downgrade, you will lose access to ${MAIL_APP_NAME} and ${VPN_APP_NAME} paid features.`;\n                    }\n\n                    if (hasMail) {\n                        return c('Info')\n                            .t`If you proceed with the downgrade, you will lose access to ${MAIL_APP_NAME} paid features, including additional storage and filters.`;\n                    }\n\n                    return c('Info')\n                        .t`If you proceed with the downgrade, you will lose access to ${VPN_APP_NAME} paid features.`;\n                })()}\n            </Alert>\n            <Alert type=\"warning\">\n                {[\n                    hasMail &&\n                        c('Info')\n                            .t`You must disable or remove any additional ${MAIL_APP_NAME} users, addresses, and custom domains before you can downgrade.`,\n                    hasVpn && c('Info').t`Downgrading will terminate any connections to paid ${VPN_APP_NAME} servers.`,\n                ]\n                    .filter(Boolean)\n                    .join(' ')}\n            </Alert>\n        </AlertModal>\n    );\n};\n\nexport default DowngradeModal;\n","import { Icon, Info } from '../../../components';\nimport { classnames } from '../../../helpers';\nimport { PlanCardFeatureDefinition } from '../features/interface';\nimport './SubscriptionCancelPlan.scss';\n\ninterface Props {\n    name: string;\n    info: string;\n    features: PlanCardFeatureDefinition[];\n    downgrade?: boolean;\n}\n\nconst SubscriptionCancelPlan = ({ name, info, features, downgrade = false }: Props) => {\n    return (\n        <div className=\"pt1 pb1 pr1 on-mobile-pr0 flex-item-fluid\">\n            <h3 className=\"text-bold text-capitalize mb0-5\" id={`desc_${name}`}>\n                {name}\n            </h3>\n            <p className=\"text-lg subscription-cancel-plan-info\">{info}</p>\n            {features.length ? (\n                <ul className=\"unstyled mt1\">\n                    {features.map((feature) => {\n                        return (\n                            <li key={feature.featureName} className=\"flex flex-nowrap mb0-5\">\n                                <span className={classnames(['flex-item-noshrink mr1', downgrade && 'color-weak'])}>\n                                    {downgrade ? '-' : <Icon name=\"checkmark\" className=\"color-primary\" />}\n                                </span>\n                                <span className={classnames(['mr0-25', downgrade && 'text-strike color-weak'])}>\n                                    {feature.featureName}\n                                </span>\n                                <span>\n                                    {feature.tooltip ? <Info className=\"ml0-5\" title={feature.tooltip} /> : null}\n                                </span>\n                            </li>\n                        );\n                    })}\n                </ul>\n            ) : null}\n        </div>\n    );\n};\n\nexport default SubscriptionCancelPlan;\n","import { c, msgid } from 'ttag';\nimport { getDifferenceInDays } from '@proton/shared/lib/date/date';\nimport { BRAND_NAME } from '@proton/shared/lib/constants';\nimport {\n    Alert,\n    Button,\n    ModalProps,\n    ModalTwo as Modal,\n    ModalTwoHeader as ModalHeader,\n    ModalTwoContent as ModalContent,\n    ModalTwoFooter as ModalFooter,\n    Form,\n} from '../../../components';\n\nimport SubscriptionCancelPlan from './SubscriptionCancelPlan';\nimport { getFreePlan } from '../features/plan';\nimport { ShortPlan } from '../features/interface';\n\ninterface Props extends Omit<ModalProps, 'onSubmit'> {\n    onConfirm: () => void;\n    shortPlan: ShortPlan;\n    periodEnd: number;\n}\n\nconst HighlightPlanDowngradeModal = ({ onConfirm, onClose, shortPlan, periodEnd, ...rest }: Props) => {\n    const downgradedShortPlan = getFreePlan();\n    const downgradedPlanName = `${BRAND_NAME} ${downgradedShortPlan.title}`;\n    const currentPlanName = shortPlan.title;\n\n    const daysRemaining = getDifferenceInDays(new Date(), new Date(periodEnd * 1000));\n\n    // translator: daysRemaining contains the number of days remaining for the current subscription eg 288 days remaining\n    const planTimeRemainingString = c('new_plans: Plan time remaining').ngettext(\n        msgid`You still have ${daysRemaining} day left on your ${currentPlanName} account.`,\n        `You still have ${daysRemaining} days left on your ${currentPlanName} account.`,\n        daysRemaining\n    );\n\n    // translator: will be something like \"Downgrade to Proton Free\" (where \"Free\" is the plan name)\n    const downgradeButtonString = c('new_plans: Action').t`Downgrade to ${downgradedPlanName}`;\n\n    // translator: will be something like \"Keep my Proton Plus account\"\n    const keepButtonString = c('new_plans: Action').t`Keep my ${currentPlanName} account`;\n\n    return (\n        <Modal as={Form} onClose={onClose} size=\"large\" {...rest}>\n            <ModalHeader title={c('Title').t`Downgrade account`} />\n            <ModalContent>\n                {daysRemaining > 0 && (\n                    <Alert className=\"mb1\" type=\"warning\">\n                        {planTimeRemainingString}\n                        <br />\n                        {c('Info')\n                            .t`By downgrading you will lose the following benefits. Are you sure you want to proceed?`}\n                    </Alert>\n                )}\n                <div className=\"flex flex-row flex-nowrap on-mobile-flex-column\">\n                    <SubscriptionCancelPlan\n                        name={downgradedPlanName}\n                        info={downgradedShortPlan?.description || ''}\n                        features={shortPlan?.features || []}\n                        downgrade\n                    />\n                    <SubscriptionCancelPlan\n                        name={currentPlanName}\n                        info={shortPlan?.description || ''}\n                        features={shortPlan?.features || []}\n                    />\n                </div>\n            </ModalContent>\n            <ModalFooter>\n                <Button\n                    className=\"on-mobile-w100 on-mobile-mb1\"\n                    onClick={() => {\n                        onConfirm();\n                        onClose?.();\n                    }}\n                >\n                    {downgradeButtonString}\n                </Button>\n                <Button className=\"on-mobile-w100\" color=\"norm\" onClick={onClose}>\n                    {keepButtonString}\n                </Button>\n            </ModalFooter>\n        </Modal>\n    );\n};\n\nexport default HighlightPlanDowngradeModal;\n","import { Fragment, ReactNode, useState } from 'react';\nimport { c } from 'ttag';\nimport { SUBSCRIPTION_CANCELLATION_REASONS } from '@proton/shared/lib/constants';\nimport { shuffle } from '@proton/shared/lib/helpers/array';\nimport { requiredValidator } from '@proton/shared/lib/helpers/formValidators';\nimport { UserModel } from '@proton/shared/lib/interfaces';\nimport isTruthy from '@proton/shared/lib/helpers/isTruthy';\nimport {\n    Button,\n    InputFieldTwo,\n    ModalProps,\n    ModalTwo as Modal,\n    ModalTwoHeader as ModalHeader,\n    ModalTwoContent as ModalContent,\n    ModalTwoFooter as ModalFooter,\n    Option,\n    SelectTwo,\n    TextAreaTwo,\n    useFormErrors,\n    Form,\n} from '../../../components';\nimport { useConfig } from '../../../hooks';\n\ninterface ReasonOption {\n    title: string;\n    value: string;\n}\n\ninterface ReasonDetail {\n    forReason: SUBSCRIPTION_CANCELLATION_REASONS;\n    content: ReactNode;\n}\n\nconst {\n    DIFFERENT_ACCOUNT,\n    TOO_EXPENSIVE,\n    MISSING_FEATURE,\n    QUALITY_ISSUE,\n    STREAMING_SERVICE_UNSUPPORTED,\n    SWITCHING_TO_DIFFERENT_SERVICE,\n    TEMPORARY,\n    OTHER,\n} = SUBSCRIPTION_CANCELLATION_REASONS;\n\nexport interface FeedbackDowngradeData {\n    Reason?: string;\n    Feedback?: string;\n    ReasonDetails?: string;\n    Context?: 'vpn' | 'mail';\n}\n\ninterface Props extends Omit<ModalProps, 'onSubmit'> {\n    onSubmit: (model: FeedbackDowngradeData) => void;\n    user: UserModel;\n}\n\nconst FeedbackDowngradeModal = ({ onSubmit, onClose, user, ...rest }: Props) => {\n    const { APP_NAME } = useConfig();\n\n    const { isPaid } = user;\n\n    const isVpnApp = APP_NAME === 'proton-vpn-settings';\n\n    const [model, setModel] = useState<FeedbackDowngradeData>({\n        Reason: '',\n        Feedback: '',\n        ReasonDetails: '',\n        Context: isVpnApp ? 'vpn' : 'mail',\n    });\n    const { validator, onFormSubmit } = useFormErrors();\n\n    const [randomisedOptions] = useState(() => {\n        const reasons: ReasonOption[] = [\n            !isVpnApp\n                ? {\n                      title: c('Downgrade account reason').t`I use a different Proton account`,\n                      value: DIFFERENT_ACCOUNT,\n                  }\n                : undefined,\n            isPaid\n                ? {\n                      title: c('Downgrade account reason').t`Subscription is too expensive`,\n                      value: TOO_EXPENSIVE,\n                  }\n                : undefined,\n            {\n                title: c('Downgrade account reason').t`Missing feature(s)`,\n                value: MISSING_FEATURE,\n            },\n            {\n                title: c('Downgrade account reason').t`Bugs or quality issue`,\n                value: QUALITY_ISSUE,\n            },\n            isVpnApp\n                ? {\n                      title: c('Downgrade account reason').t`Streaming service unsupported`,\n                      value: STREAMING_SERVICE_UNSUPPORTED,\n                  }\n                : undefined,\n            {\n                title: c('Downgrade account reason').t`Switching to a different provider`,\n                value: SWITCHING_TO_DIFFERENT_SERVICE,\n            },\n            {\n                title: c('Downgrade account reason').t`Temporary need, may come back in the future`,\n                value: TEMPORARY,\n            },\n        ].filter(isTruthy);\n        return shuffle(reasons);\n    });\n\n    const options = [\n        ...randomisedOptions.map(({ title, value }) => <Option key={value} title={title} value={value} />),\n        <Option\n            title={c('Downgrade account reason').t`My reason isn't listed, please comment`}\n            value={OTHER}\n            key={OTHER}\n        />,\n    ];\n\n    const sharedReasonDetailsProps = {\n        value: model.ReasonDetails,\n        onValue: (value: string) => setModel({ ...model, ReasonDetails: value }),\n    };\n    const reasonDetails: ReasonDetail[] = [\n        {\n            forReason: MISSING_FEATURE,\n            content: (\n                <InputFieldTwo\n                    id={MISSING_FEATURE}\n                    as={TextAreaTwo}\n                    rows={3}\n                    label={c('Label').t`Could you please specify?`}\n                    error={validator(model.Reason === MISSING_FEATURE ? [requiredValidator(model.ReasonDetails)] : [])}\n                    {...sharedReasonDetailsProps}\n                />\n            ),\n        },\n\n        {\n            forReason: QUALITY_ISSUE,\n            content: (\n                <InputFieldTwo\n                    id={QUALITY_ISSUE}\n                    as={TextAreaTwo}\n                    rows={3}\n                    label={c('Label').t`Could you please specify?`}\n                    error={validator(model.Reason === QUALITY_ISSUE ? [requiredValidator(model.ReasonDetails)] : [])}\n                    {...sharedReasonDetailsProps}\n                />\n            ),\n        },\n\n        {\n            forReason: STREAMING_SERVICE_UNSUPPORTED,\n            content: (\n                <InputFieldTwo\n                    id={STREAMING_SERVICE_UNSUPPORTED}\n                    as={TextAreaTwo}\n                    rows={3}\n                    label={c('Label').t`Could you please specify which streaming service?`}\n                    error={validator(\n                        model.Reason === STREAMING_SERVICE_UNSUPPORTED ? [requiredValidator(model.ReasonDetails)] : []\n                    )}\n                    {...sharedReasonDetailsProps}\n                />\n            ),\n        },\n\n        {\n            forReason: SWITCHING_TO_DIFFERENT_SERVICE,\n            content: (\n                <InputFieldTwo\n                    id={SWITCHING_TO_DIFFERENT_SERVICE}\n                    as={TextAreaTwo}\n                    rows={3}\n                    label={c('Label').t`Could you please let us know which provider?`}\n                    error={validator(\n                        model.Reason === SWITCHING_TO_DIFFERENT_SERVICE ? [requiredValidator(model.ReasonDetails)] : []\n                    )}\n                    {...sharedReasonDetailsProps}\n                />\n            ),\n        },\n    ];\n\n    const handleSubmit = () => {\n        if (!onFormSubmit()) {\n            return;\n        }\n\n        const shouldSendReasonDetails = reasonDetails.some(({ forReason }) => model.Reason === forReason);\n\n        onSubmit({ ...model, ReasonDetails: shouldSendReasonDetails ? model.ReasonDetails : '' });\n        onClose?.();\n    };\n\n    return (\n        <Modal as={Form} onClose={onClose} onSubmit={handleSubmit} {...rest}>\n            <ModalHeader title={c('Downgrade modal exit survey title').t`Help us improve!`} />\n            <ModalContent>\n                <InputFieldTwo\n                    as={SelectTwo}\n                    label={c('Label').t`What is the main reason you are cancelling?`}\n                    placeholder={c('Placeholder').t`Select a reason`}\n                    id=\"reason\"\n                    autoFocus\n                    value={model.Reason}\n                    onValue={(value: unknown) => setModel({ ...model, Reason: value as string })}\n                    error={validator([requiredValidator(model.Reason)])}\n                >\n                    {options}\n                </InputFieldTwo>\n\n                {reasonDetails.map(({ forReason, content }) => {\n                    if (model.Reason !== forReason) {\n                        return;\n                    }\n                    return <Fragment key={forReason}>{content}</Fragment>;\n                })}\n\n                <InputFieldTwo\n                    id=\"feedback\"\n                    as={TextAreaTwo}\n                    rootClassName=\"mt0-5\"\n                    rows={5}\n                    label={c('Label').t`Do you have any suggestions for our team?`}\n                    hint={c('Label').t`Optional`}\n                    placeholder={c('Placeholder').t`Feedback`}\n                    value={model.Feedback}\n                    onValue={(value: string) => setModel({ ...model, Feedback: value })}\n                />\n            </ModalContent>\n            <ModalFooter>\n                <Button onClick={onClose}>{c('Action').t`Cancel`}</Button>\n                <Button type=\"submit\" color=\"norm\">\n                    {c('Action').t`Submit`}\n                </Button>\n            </ModalFooter>\n        </Modal>\n    );\n};\n\nexport default FeedbackDowngradeModal;\n","import { ReactNode } from 'react';\nimport { c } from 'ttag';\nimport { getCalendars } from '@proton/shared/lib/models/calendarsModel';\nimport { deleteSubscription } from '@proton/shared/lib/api/payments';\nimport { hasBonuses } from '@proton/shared/lib/helpers/organization';\nimport { MAX_CALENDARS_PER_FREE_USER } from '@proton/shared/lib/calendar/constants';\nimport { Calendar, CalendarUrlsResponse } from '@proton/shared/lib/interfaces/calendar';\nimport { getPublicLinks } from '@proton/shared/lib/api/calendars';\nimport { getIsPersonalCalendar } from '@proton/shared/lib/calendar/subscribe/helpers';\nimport { unary } from '@proton/shared/lib/helpers/function';\nimport { hasMigrationDiscount, hasNewVisionary } from '@proton/shared/lib/helpers/subscription';\nimport { APPS, PLANS } from '@proton/shared/lib/constants';\nimport { toMap } from '@proton/shared/lib/helpers/object';\nimport Button, { ButtonProps } from '../../../components/button/Button';\nimport {\n    useApi,\n    useUser,\n    useNotifications,\n    useLoading,\n    useModals,\n    useEventManager,\n    useOrganization,\n    usePlans,\n    useSubscription,\n    useConfig,\n    useVPNCountriesCount,\n    useVPNServersCount,\n} from '../../../hooks';\nimport LossLoyaltyModal from '../LossLoyaltyModal';\nimport DowngradeModal from '../DowngradeModal';\nimport HighlightPlanDowngradeModal from './HighlightPlanDowngradeModal';\nimport CalendarDowngradeModal from './CalendarDowngradeModal';\nimport MemberDowngradeModal from '../MemberDowngradeModal';\nimport { DiscountWarningModal, NewVisionaryWarningModal } from './PlanLossWarningModal';\nimport FeedbackDowngradeModal, { FeedbackDowngradeData } from './FeedbackDowngradeModal';\nimport { getShortPlan } from '../features/plan';\nimport { formatPlans } from './helpers';\n\ninterface Props extends Omit<ButtonProps, 'loading' | 'onClick'> {\n    children: ReactNode;\n}\n\nconst UnsubscribeButton = ({ className, children, ...rest }: Props) => {\n    const { APP_NAME } = useConfig();\n    const [user] = useUser();\n    const [subscription, loadingSubscription] = useSubscription();\n    const [organization] = useOrganization();\n    const [plans, loadingPlans] = usePlans();\n    const [vpnCountries] = useVPNCountriesCount();\n    const [vpnServers] = useVPNServersCount();\n    const { createNotification, hideNotification } = useNotifications();\n    const { createModal } = useModals();\n    const api = useApi();\n    const { call } = useEventManager();\n    const [loading, withLoading] = useLoading();\n\n    const { Plans = [], PeriodEnd = 0 } = subscription || {};\n    const { mailPlan, vpnPlan } = formatPlans(Plans);\n\n    const currentPlan = APP_NAME === APPS.PROTONVPN_SETTINGS ? vpnPlan || mailPlan : mailPlan || vpnPlan;\n    const plansMap = toMap(plans, 'Name');\n\n    const handleUnsubscribe = async (data: FeedbackDowngradeData) => {\n        const downgradeNotificationId = createNotification({\n            type: 'info',\n            text: c('State').t`Downgrading your account, please wait`,\n            expiration: 99999,\n        });\n\n        try {\n            await api(deleteSubscription(data));\n            await call();\n            createNotification({ text: c('Success').t`You have successfully unsubscribed` });\n        } finally {\n            hideNotification(downgradeNotificationId);\n        }\n    };\n\n    const handleClick = async () => {\n        if (user.isFree) {\n            return createNotification({ type: 'error', text: c('Info').t`You already have a free account` });\n        }\n\n        // Start promise early\n        const calendarPromise = (async () => {\n            const calendars: Calendar[] = await getCalendars(api);\n            const personalCalendars = calendars.filter(unary(getIsPersonalCalendar));\n\n            const hasLinks = !!(\n                await Promise.all(\n                    personalCalendars.map((calendar) => api<CalendarUrlsResponse>(getPublicLinks(calendar.ID)))\n                )\n            ).flatMap(({ CalendarUrls }) => CalendarUrls).length;\n\n            return personalCalendars.length > MAX_CALENDARS_PER_FREE_USER || hasLinks;\n        })();\n\n        if (hasMigrationDiscount(subscription)) {\n            await new Promise<void>((resolve, reject) => {\n                createModal(<DiscountWarningModal type=\"downgrade\" onClose={reject} onConfirm={resolve} />);\n            });\n        }\n\n        if (hasNewVisionary(subscription)) {\n            await new Promise<void>((resolve, reject) => {\n                createModal(<NewVisionaryWarningModal type=\"downgrade\" onClose={reject} onConfirm={resolve} />);\n            });\n        }\n\n        const shortPlan = currentPlan\n            ? getShortPlan(currentPlan.Name as PLANS, plansMap, vpnCountries, vpnServers)\n            : undefined;\n        // We only show the plan downgrade plan modal for plans that are defined with features\n        if (shortPlan) {\n            await new Promise<void>((resolve, reject) => {\n                createModal(\n                    <HighlightPlanDowngradeModal\n                        shortPlan={shortPlan}\n                        periodEnd={PeriodEnd}\n                        onConfirm={resolve}\n                        onClose={reject}\n                    />\n                );\n            });\n        }\n\n        if (await calendarPromise) {\n            await new Promise<void>((resolve, reject) => {\n                createModal(<CalendarDowngradeModal onConfirm={reject} onClose={reject} />);\n            });\n        }\n\n        if (hasBonuses(organization)) {\n            await new Promise<void>((resolve, reject) => {\n                createModal(<LossLoyaltyModal organization={organization} onConfirm={resolve} onClose={reject} />);\n            });\n        }\n\n        if (organization.UsedMembers > 1) {\n            await new Promise<void>((resolve, reject) => {\n                createModal(<MemberDowngradeModal organization={organization} onConfirm={resolve} onClose={reject} />);\n            });\n        }\n\n        await new Promise<void>((resolve, reject) => {\n            createModal(<DowngradeModal user={user} onConfirm={resolve} onClose={reject} />);\n        });\n\n        const data = await new Promise<FeedbackDowngradeData>((resolve, reject) => {\n            createModal(<FeedbackDowngradeModal user={user} onSubmit={resolve} onClose={reject} />);\n        });\n\n        return handleUnsubscribe(data);\n    };\n\n    return (\n        <Button\n            disabled={loading || loadingPlans || loadingSubscription}\n            className={className}\n            onClick={() => withLoading(handleClick())}\n            {...rest}\n        >\n            {children}\n        </Button>\n    );\n};\n\nexport default UnsubscribeButton;\n","import { c } from 'ttag';\n\nimport { SettingsParagraph, SettingsSection } from '../../account';\n\nimport UnsubscribeButton from './UnsubscribeButton';\n\nconst CancelSubscriptionSection = () => {\n    return (\n        <SettingsSection>\n            <SettingsParagraph>\n                {c('Info')\n                    .t`This will cancel your current paid subscription and you will lose any loyalty benefits you have accumulated. The remaining balance of your subscription will be returned as account credits.`}\n            </SettingsParagraph>\n            <UnsubscribeButton color=\"danger\" shape=\"outline\">\n                {c('Action').t`Downgrade account`}\n            </UnsubscribeButton>\n        </SettingsSection>\n    );\n};\n\nexport default CancelSubscriptionSection;\n","import { ComponentPropsWithoutRef } from 'react';\nimport { classnames } from '../../helpers';\nimport './SettingsLayout.scss';\n\nconst SettingsLayout = ({ className = '', ...rest }: ComponentPropsWithoutRef<'div'>) => {\n    return <div className={classnames(['settings-layout', className])} {...rest} />;\n};\n\nexport default SettingsLayout;\n","import { ComponentPropsWithoutRef } from 'react';\nimport { classnames } from '../../helpers';\n\nimport './SettingsLayoutLeft.scss';\n\nconst SettingsLayoutLeft = ({ className, ...rest }: ComponentPropsWithoutRef<'div'>) => {\n    return <div className={classnames(['settings-layout-left', className])} {...rest} />;\n};\n\nexport default SettingsLayoutLeft;\n","import { ComponentPropsWithoutRef } from 'react';\nimport { classnames } from '../../helpers';\n\nimport './SettingsLayoutRight.scss';\n\nconst SettingsLayoutRight = ({ className, ...rest }: ComponentPropsWithoutRef<'div'>) => {\n    return <div className={classnames(['settings-layout-right', className])} {...rest} />;\n};\n\nexport default SettingsLayoutRight;\n","import { c } from 'ttag';\nimport { updateLocale } from '@proton/shared/lib/api/settings';\nimport { loadLocale, loadDateLocale } from '@proton/shared/lib/i18n/loadLocale';\nimport { getBrowserLocale, getClosestLocaleCode } from '@proton/shared/lib/i18n/helper';\nimport { TtagLocaleMap } from '@proton/shared/lib/interfaces/Locale';\nimport {\n    useApi,\n    useConfig,\n    useLoading,\n    useNotifications,\n    useForceRefresh,\n    useEventManager,\n    useUserSettings,\n} from '../../hooks';\nimport { Option, SelectTwo } from '../../components';\nimport SettingsLayout from '../account/SettingsLayout';\nimport SettingsLayoutLeft from '../account/SettingsLayoutLeft';\nimport SettingsLayoutRight from '../account/SettingsLayoutRight';\n\ninterface Props {\n    locales: TtagLocaleMap;\n}\n\nconst LanguageSection = ({ locales = {} }: Props) => {\n    const api = useApi();\n    const { call } = useEventManager();\n    const { LOCALES = {} } = useConfig();\n    const [userSettings] = useUserSettings();\n    const { createNotification } = useNotifications();\n    const [loading, withLoading] = useLoading();\n    const forceRefresh = useForceRefresh();\n\n    const options = Object.keys(LOCALES).map((value) => ({\n        title: LOCALES[value],\n        value,\n    }));\n\n    const handleChange = async (locale: string) => {\n        await api(updateLocale(locale));\n        const localeCode = getClosestLocaleCode(locale, locales);\n        await Promise.all([\n            loadLocale(localeCode, locales),\n            loadDateLocale(localeCode, getBrowserLocale(), userSettings),\n        ]);\n        await call();\n        createNotification({ text: c('Success').t`Locale updated` });\n        forceRefresh();\n    };\n\n    const displayedValue = getClosestLocaleCode(userSettings?.Locale, locales);\n\n    return (\n        <SettingsLayout>\n            <SettingsLayoutLeft>\n                <label className=\"text-semibold\" htmlFor=\"languageSelect\">\n                    {c('Label').t`Default language`}\n                </label>\n            </SettingsLayoutLeft>\n            <SettingsLayoutRight>\n                <SelectTwo\n                    id=\"languageSelect\"\n                    value={displayedValue}\n                    disabled={loading}\n                    onChange={({ value }) => {\n                        withLoading(handleChange(value));\n                    }}\n                >\n                    {options.map((option) => (\n                        <Option key={option.value} {...option} />\n                    ))}\n                </SelectTwo>\n            </SettingsLayoutRight>\n        </SettingsLayout>\n    );\n};\n\nexport default LanguageSection;\n","import { c } from 'ttag';\nimport { APPS, MAIL_APP_NAME } from '@proton/shared/lib/constants';\n\nimport { Label, Row, Field, Href } from '../../components';\nimport { useUser, useConfig } from '../../hooks';\n\nconst UsernameSection = () => {\n    const { APP_NAME } = useConfig();\n    const [{ Name, Email }] = useUser();\n\n    if (APP_NAME === APPS.PROTONVPN_SETTINGS) {\n        return (\n            <>\n                {Name ? (\n                    <Row>\n                        <Label>{c('Label').t`Name`}</Label>\n                        <Field className=\"pt0-5\">\n                            <strong>{Name}</strong>\n                        </Field>\n                    </Row>\n                ) : null}\n                <Row>\n                    <Label>{c('Label').t`${MAIL_APP_NAME} address`}</Label>\n                    <Field className=\"pt0-5\">\n                        {Email ? (\n                            <strong>{Email}</strong>\n                        ) : (\n                            <Href\n                                url=\"https://account.proton.me/switch?product=mail\"\n                                title={c('Info').t`Log in to ${MAIL_APP_NAME} to activate your address`}\n                            >{c('Link').t`Not activated`}</Href>\n                        )}\n                    </Field>\n                </Row>\n            </>\n        );\n    }\n\n    return (\n        <>\n            {Name ? (\n                <Row>\n                    <Label>{c('Label').t`Name`}</Label>\n                    <Field className=\"pt0-5\">\n                        <strong>{Name}</strong>\n                    </Field>\n                </Row>\n            ) : (\n                <Row>\n                    <Label>{c('Label').t`Email address`}</Label>\n                    <Field className=\"pt0-5\">\n                        <strong>{Email}</strong>\n                    </Field>\n                </Row>\n            )}\n        </>\n    );\n};\n\nexport default UsernameSection;\n","import { ChangeEvent, DetailedHTMLProps, forwardRef, InputHTMLAttributes, Ref } from 'react';\n\nimport Icon, { IconName } from '../icon/Icon';\nimport { classnames } from '../../helpers';\nimport { CircleLoader } from '../loader';\n\nexport interface Props extends DetailedHTMLProps<InputHTMLAttributes<HTMLInputElement>, HTMLInputElement> {\n    loading?: boolean;\n}\n\nconst Toggle = (\n    { id = 'toggle', className = '', checked = false, loading = false, onChange, disabled, title, ...rest }: Props,\n    ref: Ref<HTMLInputElement>\n) => {\n    const handleChange = (event: ChangeEvent<HTMLInputElement>) => {\n        if (!disabled && onChange) {\n            onChange(event);\n        }\n    };\n    const label = (name: IconName, condition: boolean) => {\n        return (\n            <span className=\"toggle-label-text\" aria-hidden=\"true\">\n                <Icon name={name} alt=\"\" size={16} className=\"toggle-label-img\" />\n                {condition && (\n                    <span className=\"toggle-label-loader\">\n                        <CircleLoader />\n                    </span>\n                )}\n            </span>\n        );\n    };\n    return (\n        <label\n            htmlFor={id}\n            className={classnames([\n                'toggle-label',\n                className,\n                disabled && 'toggle-label--disabled',\n                checked && 'toggle-label--checked',\n                loading && 'toggle-label--loading',\n            ])}\n            title={title}\n        >\n            <input\n                disabled={loading || disabled}\n                id={id}\n                onChange={handleChange}\n                type=\"checkbox\"\n                className={classnames(['toggle-checkbox sr-only', className])}\n                checked={checked}\n                aria-busy={loading}\n                ref={ref}\n                {...rest}\n            />\n            {label('cross', loading && !checked)}\n            {label('checkmark', loading && checked)}\n        </label>\n    );\n};\n\nexport default forwardRef<HTMLInputElement, Props>(Toggle);\n","import { encryptPrivateKey, OpenPGPKey } from 'pmcrypto';\nimport { Address as tsAddress, DecryptedKey } from '../interfaces';\nimport { noop } from '../helpers/function';\nimport isTruthy from '../helpers/isTruthy';\n\nimport { getHasMigratedAddressKeys } from './keyMigration';\nimport { getEncryptedArmoredAddressKey } from './addressKeys';\n\nconst getEncryptedArmoredUserKey = async ({ ID, privateKey }: DecryptedKey, newKeyPassword: string) => {\n    if (!privateKey || !privateKey.isDecrypted()) {\n        return;\n    }\n    const privateKeyArmored = await encryptPrivateKey(privateKey, newKeyPassword);\n    return {\n        ID,\n        PrivateKey: privateKeyArmored,\n    };\n};\n\nexport const getEncryptedArmoredOrganizationKey = async (\n    organizationKey: OpenPGPKey | undefined,\n    newKeyPassword: string\n) => {\n    if (!organizationKey || !organizationKey.isDecrypted()) {\n        return;\n    }\n    return encryptPrivateKey(organizationKey, newKeyPassword);\n};\n\nexport const getArmoredPrivateUserKeys = async (keys: DecryptedKey[], keyPassword: string) => {\n    if (keys.length === 0) {\n        return [];\n    }\n    const armoredKeys = await Promise.all(\n        keys.map((key) => {\n            return getEncryptedArmoredUserKey(key, keyPassword).catch(noop);\n        })\n    );\n    const result = armoredKeys.filter(isTruthy);\n\n    if (result.length === 0) {\n        const decryptedError = new Error('No decrypted keys exist');\n        decryptedError.name = 'NoDecryptedKeys';\n        throw decryptedError;\n    }\n\n    return result;\n};\n\nexport const getArmoredPrivateAddressKeys = async (keys: DecryptedKey[], address: tsAddress, keyPassword: string) => {\n    const armoredKeys = await Promise.all(\n        keys.map(async ({ ID, privateKey }) => {\n            const PrivateKey = await getEncryptedArmoredAddressKey(privateKey, address.Email, keyPassword).catch(noop);\n            if (!PrivateKey) {\n                return;\n            }\n            return {\n                ID,\n                PrivateKey,\n            };\n        })\n    );\n\n    const result = armoredKeys.filter(isTruthy);\n\n    if (result.length === 0) {\n        const decryptedError = new Error('No decrypted keys exist');\n        decryptedError.name = 'NoDecryptedKeys';\n        throw decryptedError;\n    }\n\n    return result;\n};\n\ninterface AddressesKeys {\n    address: tsAddress;\n    keys: DecryptedKey[];\n}\n\nexport const getArmoredPrivateAddressesKeys = async (addressesWithKeysList: AddressesKeys[], keyPassword: string) => {\n    const result = await Promise.all(\n        addressesWithKeysList.map(({ address, keys }) => {\n            if (!keys.length) {\n                return;\n            }\n            return getArmoredPrivateAddressKeys(keys, address, keyPassword);\n        })\n    );\n    return result.flat().filter(isTruthy);\n};\n\nexport const getUpdateKeysPayload = async (\n    addressesKeys: AddressesKeys[],\n    userKeys: DecryptedKey[],\n    organizationKey: OpenPGPKey | undefined,\n    keyPassword: string,\n    keySalt: string\n) => {\n    const hasMigratedAddressKeys = getHasMigratedAddressKeys(addressesKeys.map(({ address }) => address));\n\n    const [armoredUserKeys, armoredAddressesKeys, armoredOrganizationKey] = await Promise.all([\n        getArmoredPrivateUserKeys(userKeys, keyPassword),\n        hasMigratedAddressKeys ? [] : getArmoredPrivateAddressesKeys(addressesKeys, keyPassword),\n        getEncryptedArmoredOrganizationKey(organizationKey, keyPassword),\n    ]);\n\n    return hasMigratedAddressKeys\n        ? {\n              UserKeys: armoredUserKeys,\n              KeySalt: keySalt,\n              OrganizationKey: armoredOrganizationKey,\n          }\n        : {\n              Keys: [...armoredUserKeys, ...armoredAddressesKeys],\n              KeySalt: keySalt,\n              OrganizationKey: armoredOrganizationKey,\n          };\n};\n","import { srpAuth, srpVerify } from '@proton/shared/lib/srp';\nimport { unlockPasswordChanges } from '@proton/shared/lib/api/user';\nimport { updatePassword } from '@proton/shared/lib/api/settings';\nimport { Api } from '@proton/shared/lib/interfaces';\n\nexport const handleUnlock = ({ api, oldPassword, totp }: { api: Api; oldPassword: string; totp?: string }) => {\n    return srpAuth({\n        api,\n        credentials: {\n            password: oldPassword,\n            totp,\n        },\n        config: unlockPasswordChanges(),\n    });\n};\n\nexport const handleChangeLoginPassword = async ({ api, newPassword }: { api: Api; newPassword: string }) => {\n    return srpVerify({\n        api,\n        credentials: {\n            password: newPassword,\n        },\n        config: updatePassword(),\n    });\n};\n","import { useCallback } from 'react';\nimport { OrganizationKey } from '@proton/shared/lib/interfaces';\nimport { getCachedOrganizationKey } from '@proton/shared/lib/keys';\nimport { getOrganizationKeys } from '@proton/shared/lib/api/organization';\n\nimport useApi from './useApi';\nimport useAuthentication from './useAuthentication';\n\nexport const useGetOrganizationKeyRaw = () => {\n    const authentication = useAuthentication();\n    const api = useApi();\n\n    return useCallback(async () => {\n        const Key = await api<OrganizationKey>(getOrganizationKeys());\n        return getCachedOrganizationKey({ keyPassword: authentication.getPassword(), Key });\n    }, []);\n};\n\nexport default useGetOrganizationKeyRaw;\n","import { useEffect, useState } from 'react';\nimport { InfoAuthedResponse, TwoFaResponse } from '@proton/shared/lib/authentication/interface';\nimport { getInfo } from '@proton/shared/lib/api/auth';\nimport { getHasTOTPEnabled, getHasTOTPSettingEnabled } from '@proton/shared/lib/settings/twoFactor';\nimport { noop } from '@proton/shared/lib/helpers/function';\nimport { useApi, useUser, useUserSettings } from '../../hooks';\n\nconst useAskAuth = (onError: () => void = noop) => {\n    const [userSettings, loadingUserSettings] = useUserSettings();\n    const [{ isSubUser }] = useUser();\n    const api = useApi();\n    const [adminAuthTwoFA, setAdminAuthTwoFA] = useState<TwoFaResponse>();\n\n    useEffect(() => {\n        if (!isSubUser) {\n            return;\n        }\n        const run = async () => {\n            /**\n             * There is a special case for admins logged into non-private users. User settings returns two factor\n             * information for the non-private user, and not for the admin to which the session actually belongs.\n             * So we query auth info to get the information about the admin.\n             */\n            const infoResult = await api<InfoAuthedResponse>({ ...getInfo(), silent: true });\n            setAdminAuthTwoFA(infoResult['2FA']);\n        };\n        run().catch(onError);\n    }, []);\n\n    const hasTOTPEnabled = isSubUser\n        ? getHasTOTPEnabled(adminAuthTwoFA?.Enabled)\n        : getHasTOTPSettingEnabled(userSettings);\n\n    const isLoading = loadingUserSettings || (isSubUser && !adminAuthTwoFA);\n\n    return [hasTOTPEnabled, isLoading];\n};\n\nexport default useAskAuth;\n","import { useState } from 'react';\nimport { c } from 'ttag';\nimport { lockSensitiveSettings } from '@proton/shared/lib/api/user';\nimport { PASSWORD_WRONG_ERROR } from '@proton/shared/lib/api/auth';\nimport { generateKeySaltAndPassphrase } from '@proton/shared/lib/keys';\nimport { isSSOMode, MAIL_APP_NAME } from '@proton/shared/lib/constants';\nimport { persistSessionWithPassword } from '@proton/shared/lib/authentication/persistedSessionHelper';\nimport { PASSWORD_CHANGE_MESSAGE_TYPE, sendMessageToTabs } from '@proton/shared/lib/helpers/crossTab';\nimport { noop } from '@proton/shared/lib/helpers/function';\nimport { updatePrivateKeyRoute } from '@proton/shared/lib/api/keys';\nimport { srpVerify } from '@proton/shared/lib/srp';\nimport { Address } from '@proton/shared/lib/interfaces';\nimport { getUpdateKeysPayload } from '@proton/shared/lib/keys/changePassword';\nimport {\n    confirmPasswordValidator,\n    passwordLengthValidator,\n    requiredValidator,\n} from '@proton/shared/lib/helpers/formValidators';\n\nimport { handleUnlock, handleChangeLoginPassword } from './changePasswordHelper';\nimport {\n    Alert,\n    Button,\n    Form,\n    InputFieldTwo,\n    Loader,\n    ModalProps,\n    ModalTwo as Modal,\n    ModalTwoContent as ModalContent,\n    ModalTwoFooter as ModalFooter,\n    ModalTwoHeader as ModalHeader,\n    PasswordInputTwo,\n    SettingsLink,\n    useFormErrors,\n} from '../../components';\n\nimport { GenericError } from '../error';\nimport {\n    useAuthentication,\n    useEventManager,\n    useNotifications,\n    useApi,\n    useUser,\n    useGetUserKeys,\n    useGetOrganizationKeyRaw,\n    useBeforeUnload,\n    useGetAddresses,\n    useGetAddressKeys,\n} from '../../hooks';\nimport { useAskAuth } from '../password';\n\nexport enum MODES {\n    CHANGE_ONE_PASSWORD_MODE = 1,\n    CHANGE_TWO_PASSWORD_MAILBOX_MODE = 2,\n    CHANGE_TWO_PASSWORD_LOGIN_MODE = 3,\n    SWITCH_ONE_PASSWORD = 4,\n    SWITCH_TWO_PASSWORD = 5,\n}\n\ninterface Inputs {\n    oldPassword: string;\n    newPassword: string;\n    confirmPassword: string;\n    totp: string;\n}\n\ninterface Errors {\n    loginError: string;\n    fatalError: boolean;\n    persistError?: boolean;\n}\n\nconst DEFAULT_ERRORS: Errors = {\n    loginError: '',\n    fatalError: false,\n};\n\ninterface ModalProperties {\n    title: string;\n    description?: JSX.Element | null;\n    labels: {\n        oldPassword?: string;\n        newPassword: string;\n        confirmPassword: string;\n    };\n    close?: string;\n    submit?: string;\n    onSubmit?: () => Promise<void>;\n}\n\ninterface Props extends ModalProps {\n    mode: MODES;\n}\n\nconst ChangePasswordModal = ({ mode, onClose, ...rest }: Props) => {\n    const api = useApi();\n    const { call, stop, start } = useEventManager();\n    const authentication = useAuthentication();\n    const { createNotification } = useNotifications();\n    const getOrganizationKeyRaw = useGetOrganizationKeyRaw();\n    const getUserKeys = useGetUserKeys();\n    const getAddressKeys = useGetAddressKeys();\n    const getAddresses = useGetAddresses();\n    const { validator, onFormSubmit, reset } = useFormErrors();\n\n    const [User] = useUser();\n\n    const { isSubUser, isAdmin, Name, Email } = User;\n\n    const [inputs, setInputs] = useState<Inputs>({\n        oldPassword: '',\n        newPassword: '',\n        confirmPassword: '',\n        totp: '',\n    });\n    const [loading, setLoading] = useState<boolean>(false);\n    const [errors, setErrors] = useState<Errors>(DEFAULT_ERRORS);\n    const [isSecondPhase, setSecondPhase] = useState<boolean>(false);\n\n    useBeforeUnload(loading ? c('Info').t`By leaving now, changes may not be saved` : '');\n\n    const setPartialError = (object: Partial<Errors>) => setErrors((oldState) => ({ ...oldState, ...object }));\n    const setPartialInput = (object: Partial<Inputs>) => setInputs((oldState) => ({ ...oldState, ...object }));\n    const resetErrors = () => setErrors(DEFAULT_ERRORS);\n\n    const [hasTOTPEnabled, isLoadingAuth] = useAskAuth(() => {\n        setPartialError({ fatalError: true });\n    });\n\n    const newPasswordError = passwordLengthValidator(inputs.newPassword);\n    const confirmPasswordError =\n        passwordLengthValidator(inputs.confirmPassword) ||\n        confirmPasswordValidator(inputs.newPassword, inputs.confirmPassword);\n\n    const validateNewPasswords = () => {\n        if (newPasswordError || confirmPasswordError) {\n            throw new Error('Password error');\n        }\n    };\n\n    const checkLoginError = ({ data: { Code, Error } = { Code: 0, Error: '' } }) => {\n        if (Code === PASSWORD_WRONG_ERROR) {\n            setPartialError({\n                ...DEFAULT_ERRORS,\n                loginError: Error,\n            });\n        }\n    };\n\n    const checkFatalError = (e: Error) => {\n        if (e.name === 'NoDecryptedKeys') {\n            setPartialError({ fatalError: true });\n        }\n    };\n\n    const notifySuccess = () => {\n        createNotification({ text: c('Success').t`Password updated` });\n    };\n\n    const mutatePassword = async (keyPassword: string) => {\n        // Don't mutate the password when signed in as sub-user\n        if (isSubUser) {\n            return;\n        }\n        const localID = authentication.getLocalID?.();\n        if (!isSSOMode || localID === undefined) {\n            authentication.setPassword(keyPassword);\n            return;\n        }\n        try {\n            authentication.setPassword(keyPassword);\n\n            await persistSessionWithPassword({\n                api,\n                keyPassword,\n                User,\n                UID: authentication.getUID(),\n                LocalID: localID,\n                persistent: authentication.getPersistent(),\n            });\n            sendMessageToTabs(PASSWORD_CHANGE_MESSAGE_TYPE, { localID, status: true });\n        } catch (e: any) {\n            sendMessageToTabs(PASSWORD_CHANGE_MESSAGE_TYPE, { localID, status: false });\n            // If persisting the password fails for some reason.\n            setPartialError({ fatalError: true, persistError: true });\n            throw e;\n        }\n    };\n\n    const getModalProperties = (mode: MODES): ModalProperties => {\n        if ([MODES.CHANGE_TWO_PASSWORD_LOGIN_MODE, MODES.CHANGE_ONE_PASSWORD_MODE].includes(mode)) {\n            if (isSubUser) {\n                return {\n                    title: c('Title').t`Change password`,\n                    description: (\n                        <div className=\"mb1\">\n                            {c('Info')\n                                .t`Enter your own password (as organization admin) and new password for this user ${Name} (${Email}).`}\n                        </div>\n                    ),\n                    labels: {\n                        oldPassword: c('Label').t`Your password (admin)`,\n                        newPassword: c('Label').t`User's new password`,\n                        confirmPassword: c('Label').t`Confirm new password`,\n                    },\n                    close: c('Action').t`Cancel`,\n                    submit: c('Action').t`Change password`,\n                };\n            }\n\n            if (mode === MODES.CHANGE_ONE_PASSWORD_MODE) {\n                return {\n                    title: c('Title').t`Change password`,\n                    labels: {\n                        oldPassword: c('Label').t`Old password`,\n                        newPassword: c('Label').t`New password`,\n                        confirmPassword: c('Label').t`Confirm password`,\n                    },\n                };\n            }\n\n            return {\n                title: c('Title').t`Change login password`,\n                labels: {\n                    oldPassword: c('Label').t`Old login password`,\n                    newPassword: c('Label').t`New login password`,\n                    confirmPassword: c('Label').t`Confirm login password`,\n                },\n            };\n        }\n\n        throw new Error('mode not supported');\n    };\n\n    const {\n        labels,\n        description = null,\n        title,\n        close = undefined,\n        submit = undefined,\n        onSubmit,\n    } = ((): ModalProperties => {\n        if (mode === MODES.CHANGE_TWO_PASSWORD_LOGIN_MODE) {\n            return {\n                ...getModalProperties(mode),\n                async onSubmit() {\n                    if (!onFormSubmit()) {\n                        return;\n                    }\n                    try {\n                        validateNewPasswords();\n                        resetErrors();\n                        setLoading(true);\n\n                        await handleUnlock({ api, oldPassword: inputs.oldPassword, totp: inputs.totp });\n                        await handleChangeLoginPassword({ api, newPassword: inputs.newPassword });\n                        await api(lockSensitiveSettings());\n\n                        notifySuccess();\n                        onClose?.();\n                    } catch (e: any) {\n                        setLoading(false);\n                        checkLoginError(e);\n                    }\n                },\n            };\n        }\n\n        if (mode === MODES.SWITCH_TWO_PASSWORD && !isSecondPhase) {\n            return {\n                title: c('Title').t`Switch to two-password mode`,\n                description: (\n                    <div className=\"mb1\">\n                        {c('Info')\n                            .t`Two-password mode uses separate passwords for login and mailbox decryption. This provides a minor security benefit in some situations, however we recommend one-password mode for most users. To switch to two password mode, first set a login password and then set a mailbox password.`}\n                    </div>\n                ),\n                labels: {\n                    oldPassword: isSubUser ? c('Label').t`Your password (admin)` : c('Label').t`Old password`,\n                    newPassword: c('Label').t`New login password`,\n                    confirmPassword: c('Label').t`Confirm login password`,\n                },\n                async onSubmit() {\n                    if (!onFormSubmit()) {\n                        return;\n                    }\n\n                    try {\n                        validateNewPasswords();\n                        resetErrors();\n                        setLoading(true);\n\n                        await handleUnlock({ api, oldPassword: inputs.oldPassword, totp: inputs.totp });\n                        await handleChangeLoginPassword({ api, newPassword: inputs.newPassword });\n\n                        setSecondPhase(true);\n                        setInputs({\n                            newPassword: '',\n                            confirmPassword: '',\n                            totp: '',\n                            oldPassword: '',\n                        });\n                        reset();\n                        setLoading(false);\n                    } catch (e: any) {\n                        setLoading(false);\n                        checkLoginError(e);\n                    }\n                },\n            };\n        }\n\n        const getAddressesWithKeysList = (addresses: Address[]) => {\n            return Promise.all(\n                addresses.map(async (address) => {\n                    return {\n                        address,\n                        keys: await getAddressKeys(address.ID),\n                    };\n                })\n            );\n        };\n\n        if (mode === MODES.SWITCH_TWO_PASSWORD && isSecondPhase) {\n            return {\n                title: c('Title').t`Switch to two-password mode`,\n                labels: {\n                    newPassword: c('Label').t`New mailbox password`,\n                    confirmPassword: c('Label').t`Confirm mailbox password`,\n                },\n                async onSubmit() {\n                    if (!onFormSubmit()) {\n                        return;\n                    }\n\n                    try {\n                        // Stop the event manager to prevent race conditions\n                        stop();\n\n                        const [addresses, userKeysList, organizationKey] = await Promise.all([\n                            getAddresses(),\n                            getUserKeys(),\n                            isAdmin ? getOrganizationKeyRaw() : undefined,\n                        ]);\n\n                        validateNewPasswords();\n                        resetErrors();\n                        setLoading(true);\n\n                        const { passphrase: keyPassword, salt: keySalt } = await generateKeySaltAndPassphrase(\n                            inputs.newPassword\n                        );\n                        const addressesKeys = await getAddressesWithKeysList(addresses);\n                        const updateKeysPayload = await getUpdateKeysPayload(\n                            addressesKeys,\n                            userKeysList,\n                            organizationKey?.privateKey,\n                            keyPassword,\n                            keySalt\n                        );\n\n                        await api(updatePrivateKeyRoute(updateKeysPayload));\n\n                        await mutatePassword(keyPassword);\n                        await api(lockSensitiveSettings());\n                        await call();\n\n                        notifySuccess();\n                        onClose?.();\n                    } catch (e: any) {\n                        setLoading(false);\n                        checkFatalError(e);\n                    } finally {\n                        start();\n                    }\n                },\n            };\n        }\n\n        const onSubmit = async () => {\n            if (!onFormSubmit()) {\n                return;\n            }\n\n            try {\n                stop();\n\n                const [addresses, userKeysList, organizationKey] = await Promise.all([\n                    getAddresses(),\n                    getUserKeys(),\n                    isAdmin ? getOrganizationKeyRaw() : undefined,\n                ]);\n\n                /**\n                 * This is the case for a user who does not have any keys set-up.\n                 * They will be in 2-password mode, but not have any keys.\n                 * Changing to one-password mode or mailbox password is not allowed.\n                 * It's not handled better because it's a rare case.\n                 */\n                if (userKeysList.length === 0) {\n                    createNotification({\n                        type: 'error',\n                        text: c('Error').t`Please generate keys before you try to change your password`,\n                    });\n                    return;\n                }\n                validateNewPasswords();\n                resetErrors();\n                setLoading(true);\n\n                await handleUnlock({\n                    api,\n                    oldPassword: inputs.oldPassword,\n                    totp: inputs.totp,\n                });\n\n                const { passphrase: keyPassword, salt: keySalt } = await generateKeySaltAndPassphrase(\n                    inputs.newPassword\n                );\n\n                const addressesWithKeys = await getAddressesWithKeysList(addresses);\n                const updateKeysPayload = await getUpdateKeysPayload(\n                    addressesWithKeys,\n                    userKeysList,\n                    organizationKey?.privateKey,\n                    keyPassword,\n                    keySalt\n                );\n\n                const routeConfig = updatePrivateKeyRoute(updateKeysPayload);\n\n                if (mode === MODES.CHANGE_TWO_PASSWORD_MAILBOX_MODE) {\n                    await api(routeConfig);\n                } else {\n                    await srpVerify({\n                        api,\n                        credentials: {\n                            password: inputs.newPassword,\n                            totp: inputs.totp,\n                        },\n                        config: routeConfig,\n                    });\n                }\n                await mutatePassword(keyPassword);\n                await api(lockSensitiveSettings());\n                await call();\n\n                notifySuccess();\n                onClose?.();\n            } catch (e: any) {\n                setLoading(false);\n                checkFatalError(e);\n                checkLoginError(e);\n            } finally {\n                start();\n            }\n        };\n\n        if (mode === MODES.SWITCH_ONE_PASSWORD) {\n            return {\n                title: c('Title').t`Switch to one-password mode`,\n                labels: {\n                    oldPassword: isSubUser ? c('Label').t`Your password (admin)` : c('Label').t`Old login password`,\n                    newPassword: c('Label').t`New password`,\n                    confirmPassword: c('Label').t`Confirm password`,\n                },\n                description: (\n                    <div className=\"mb1\">\n                        {c('Info')\n                            .t`${MAIL_APP_NAME} can also be used with a single password which replaces both the login and mailbox password. To switch to single password mode, enter the single password you would like to use and click Save.`}\n                    </div>\n                ),\n                onSubmit,\n            };\n        }\n\n        if (mode === MODES.CHANGE_ONE_PASSWORD_MODE) {\n            return {\n                ...getModalProperties(mode),\n                onSubmit,\n            };\n        }\n\n        if (mode === MODES.CHANGE_TWO_PASSWORD_MAILBOX_MODE) {\n            return {\n                title: c('Title').t`Change mailbox password`,\n                labels: {\n                    oldPassword: isSubUser ? c('Label').t`Your password (admin)` : c('Label').t`Current login password`,\n                    newPassword: c('Label').t`New mailbox password`,\n                    confirmPassword: c('Label').t`Confirm mailbox password`,\n                },\n                onSubmit,\n            };\n        }\n\n        throw new Error('Unknown mode');\n    })();\n\n    // translator: Make sure you remember the password to log in and decrypt emails. Proton can't help you recover any lost passwords. We recommend adding a recovery method first.\n    const boldAlert = <b key=\"bold-alert\">{c('Info').t`Proton can't help you recover any lost passwords.`}</b>;\n    // translator: Make sure you remember the password to log in and decrypt emails. Proton can't help you recover any lost passwords. We recommend adding a recovery method first.\n    const recoveryLink = (\n        <SettingsLink key=\"recovery-link\" path=\"/recovery\">{c('Info').t`recovery method`}</SettingsLink>\n    );\n    const alert = (\n        <>\n            <Alert className=\"mb1\" type=\"warning\">\n                {\n                    // translator: Make sure you remember the password to log in and decrypt emails. Proton can't help you recover any lost passwords. We recommend adding a recovery method first.\n                    c('Info')\n                        .jt`Make sure you remember the password to log in and decrypt emails. ${boldAlert} We recommend adding a ${recoveryLink} first.`\n                }\n            </Alert>\n        </>\n    );\n\n    const children = isLoadingAuth ? (\n        <Loader />\n    ) : (\n        <>\n            {description}\n            {alert}\n            {!isSecondPhase && (\n                <InputFieldTwo\n                    id=\"oldPassword\"\n                    label={labels.oldPassword}\n                    placeholder={c('Placeholder').t`Password`}\n                    autoComplete=\"current-password\"\n                    error={validator([requiredValidator(inputs.oldPassword), errors.loginError])}\n                    as={PasswordInputTwo}\n                    value={inputs.oldPassword}\n                    onValue={(value: string) => {\n                        setPartialInput({ oldPassword: value });\n                        setPartialError({ loginError: '' });\n                    }}\n                    disabled={loading}\n                    autoFocus\n                />\n            )}\n            {!isSecondPhase && hasTOTPEnabled && (\n                <InputFieldTwo\n                    id=\"totp\"\n                    label={c('Label').t`Two-factor authentication code`}\n                    value={inputs.totp}\n                    autoCapitalize=\"off\"\n                    autoCorrect=\"off\"\n                    autoComplete=\"one-time-code\"\n                    placeholder={c('Placeholder').t`Two-factor authentication code`}\n                    onValue={(value: string) => {\n                        setPartialInput({ totp: value });\n                        setPartialError({ loginError: '' });\n                    }}\n                    error={validator([requiredValidator(inputs.totp) && errors.loginError])}\n                    disabled={loading}\n                />\n            )}\n\n            <InputFieldTwo\n                id=\"newPassword\"\n                label={labels.newPassword}\n                placeholder={c('Placeholder').t`Password`}\n                error={validator([requiredValidator(inputs.newPassword), passwordLengthValidator(inputs.newPassword)])}\n                as={PasswordInputTwo}\n                autoComplete=\"new-password\"\n                value={inputs.newPassword}\n                onValue={(value: string) => setPartialInput({ newPassword: value })}\n                disabled={loading}\n            />\n\n            <InputFieldTwo\n                key={`${isSecondPhase}${labels.confirmPassword}`}\n                id=\"confirmPassword\"\n                label={labels.confirmPassword}\n                placeholder={c('Placeholder').t`Confirm`}\n                error={validator([\n                    requiredValidator(inputs.confirmPassword),\n                    passwordLengthValidator(inputs.confirmPassword),\n                    confirmPasswordValidator(inputs.newPassword, inputs.confirmPassword),\n                ])}\n                as={PasswordInputTwo}\n                autoComplete=\"new-password\"\n                value={inputs.confirmPassword}\n                onValue={(value: string) => setPartialInput({ confirmPassword: value })}\n                disabled={loading}\n            />\n        </>\n    );\n\n    if (errors.fatalError) {\n        const handleFatalErrorClose = () => {\n            if (errors.persistError) {\n                // If there was an error with persisting the session, we have no choice but to logout\n                authentication.logout();\n            }\n            onClose?.();\n        };\n\n        return (\n            <Modal {...rest} onClose={handleFatalErrorClose}>\n                <ModalHeader title={title} />\n                <ModalContent>\n                    <GenericError />\n                </ModalContent>\n                <ModalFooter>\n                    <Button onClick={handleFatalErrorClose}>{close || c('Action').t`Cancel`}</Button>\n                    <Button color=\"norm\" onClick={handleFatalErrorClose}>\n                        {submit || c('Action').t`Ok`}\n                    </Button>\n                </ModalFooter>\n            </Modal>\n        );\n    }\n\n    const handleClose = loading || isLoadingAuth ? noop : onClose;\n\n    return (\n        <Modal as={Form} onClose={handleClose} {...rest} onSubmit={onSubmit}>\n            <ModalHeader title={title} />\n            <ModalContent>{children}</ModalContent>\n            <ModalFooter>\n                <Button onClick={handleClose} disabled={loading}>\n                    {close || c('Action').t`Cancel`}\n                </Button>\n                <Button loading={loading} type=\"submit\" color=\"norm\">\n                    {submit || c('Action').t`Save`}\n                </Button>\n            </ModalFooter>\n        </Modal>\n    );\n};\n\nexport default ChangePasswordModal;\n","import saveAs from 'file-saver';\n\nimport { isFileSaverSupported } from './browser';\n\nconst downloadFile = (blob: Blob | undefined, filename: string | undefined) => {\n    if (!isFileSaverSupported()) {\n        throw new Error('Download requires a newer browser.');\n    }\n\n    saveAs(blob, filename);\n};\n\nexport default downloadFile;\n","import { c } from 'ttag';\n\nimport { InputFieldTwo, PasswordInputTwo } from '../../components';\n\ninterface Props {\n    password: string;\n    setPassword?: (value: string) => void;\n    totp: string;\n    setTotp: (value: string) => void;\n    showTotp: boolean;\n    totpError?: string;\n    passwordError?: string;\n}\n\nconst PasswordTotpInputs = ({ password, setPassword, passwordError, totp, setTotp, totpError, showTotp }: Props) => {\n    return (\n        <>\n            {setPassword && (\n                <InputFieldTwo\n                    required\n                    autoFocus\n                    autoComplete=\"current-password\"\n                    id=\"password\"\n                    as={PasswordInputTwo}\n                    value={password}\n                    error={passwordError}\n                    onValue={setPassword}\n                    label={c('Label').t`Password`}\n                    placeholder={c('Placeholder').t`Password`}\n                />\n            )}\n\n            {showTotp && (\n                <InputFieldTwo\n                    required\n                    autoFocus={!setPassword}\n                    autoCapitalize=\"off\"\n                    autoCorrect=\"off\"\n                    autoComplete=\"one-time-code\"\n                    id=\"totp\"\n                    value={totp}\n                    error={totpError}\n                    onValue={setTotp}\n                    placeholder={c('Placeholder').t`Two-factor authentication code`}\n                    label={c('Label').t`Two-factor authentication code`}\n                />\n            )}\n        </>\n    );\n};\n\nexport default PasswordTotpInputs;\n","import { useState } from 'react';\nimport { c } from 'ttag';\nimport { PASSWORD_WRONG_ERROR } from '@proton/shared/lib/api/auth';\nimport { srpAuth, SrpConfig } from '@proton/shared/lib/srp';\nimport { getApiError } from '@proton/shared/lib/api/helpers/apiErrorHelper';\nimport { noop } from '@proton/shared/lib/helpers/function';\n\nimport { useApi } from '../../hooks';\n\nimport {\n    Button,\n    Form,\n    Loader,\n    ModalProps,\n    ModalTwo as Modal,\n    ModalTwoContent as ModalContent,\n    ModalTwoFooter as ModalFooter,\n    ModalTwoHeader as ModalHeader,\n} from '../../components';\nimport PasswordTotpInputs from './PasswordTotpInputs';\nimport useAskAuth from './useAskAuth';\n\ninterface Props<T> extends Omit<ModalProps<typeof Form>, 'as' | 'onSubmit' | 'size' | 'onSuccess' | 'onError'> {\n    config: SrpConfig;\n    onSuccess: (data: { password: string; totp: string; result: T }) => void;\n}\n\nconst AuthModal = <T,>({ config, onSuccess, onClose, ...rest }: Props<T>) => {\n    const api = useApi();\n    const [submitting, setSubmitting] = useState(false);\n\n    const [password, setPassword] = useState('');\n    const [totp, setTotp] = useState('');\n    const [hasTOTPEnabled, isLoadingAuth] = useAskAuth();\n\n    const handleSubmit = async ({ password, totp }: { password: string; totp: string }) => {\n        try {\n            setSubmitting(true);\n\n            const result = await srpAuth<T>({\n                api,\n                credentials: { password, totp },\n                config,\n            });\n\n            onSuccess({ password, totp, result });\n            onClose?.();\n        } catch (error: any) {\n            setSubmitting(false);\n            const { code } = getApiError(error);\n            if (code !== PASSWORD_WRONG_ERROR) {\n                onClose?.();\n            }\n        }\n    };\n\n    const loading = submitting || isLoadingAuth;\n\n    // Don't allow to close this modal if it's loading as it could leave other consumers in an undefined state\n    const handleClose = loading ? noop : onClose;\n\n    return (\n        <Modal {...rest} size=\"small\" as={Form} onSubmit={() => handleSubmit({ password, totp })} onClose={handleClose}>\n            <ModalHeader title={c('Title').t`Sign in again to continue`} />\n            <ModalContent>\n                {isLoadingAuth ? (\n                    <Loader />\n                ) : (\n                    <PasswordTotpInputs\n                        password={password}\n                        setPassword={setPassword}\n                        totp={totp}\n                        setTotp={setTotp}\n                        showTotp={hasTOTPEnabled}\n                    />\n                )}\n            </ModalContent>\n            <ModalFooter>\n                <Button onClick={handleClose} disabled={loading}>{c('Action').t`Cancel`}</Button>\n                <Button color=\"norm\" type=\"submit\" disabled={isLoadingAuth} loading={submitting}>\n                    {c('Action').t`Submit`}\n                </Button>\n            </ModalFooter>\n        </Modal>\n    );\n};\n\nexport default AuthModal;\n","import { ReactNode, useState } from 'react';\nimport { c } from 'ttag';\nimport { setupTotp, TOTP_WRONG_ERROR } from '@proton/shared/lib/api/settings';\nimport { srpAuth } from '@proton/shared/lib/srp';\nimport { PASSWORD_WRONG_ERROR } from '@proton/shared/lib/api/auth';\nimport downloadFile from '@proton/shared/lib/helpers/downloadFile';\nimport { APPS } from '@proton/shared/lib/constants';\nimport { getApiError } from '@proton/shared/lib/api/helpers/apiErrorHelper';\nimport { getTOTPData } from '@proton/shared/lib/settings/twoFactor';\nimport { noop } from '@proton/shared/lib/helpers/function';\nimport { getKnowledgeBaseUrl } from '@proton/shared/lib/helpers/url';\n\nimport {\n    Alert,\n    Button,\n    Href,\n    InlineLinkButton,\n    Loader,\n    ModalProps,\n    ModalTwo as Modal,\n    ModalTwoHeader as ModalHeader,\n    ModalTwoContent as ModalContent,\n    ModalTwoFooter as ModalFooter,\n    QRCode,\n    Form,\n} from '../../components';\nimport { useConfig, useNotifications, useLoading, useApi, useEventManager, useUser, useModals } from '../../hooks';\n\nimport PasswordTotpInputs from '../password/PasswordTotpInputs';\nimport AuthModal from '../password/AuthModal';\n\ninterface ModalProperties {\n    section: ReactNode;\n    cancelButtonText?: string | null;\n    onCancel?: () => void;\n    submitButtonText?: string;\n    onSubmit?: () => void;\n}\n\ninterface SetupTOTPResponse {\n    TwoFactorRecoveryCodes: string[];\n}\n\nconst STEPS = {\n    INFO: 1,\n    SCAN_CODE: 2,\n    CONFIRM_CODE: 3,\n    RECOVERY_CODES: 4,\n};\n\nconst EnableTOTPModal = ({ onClose, ...rest }: ModalProps) => {\n    const { APP_NAME } = useConfig();\n    const [user] = useUser();\n    const api = useApi();\n    const { call } = useEventManager();\n    const { createNotification } = useNotifications();\n    const { createModal } = useModals();\n    const [{ sharedSecret, uri = '', period, digits }] = useState(() => {\n        return getTOTPData(user.Email || user.Name);\n    });\n    const [step, setStep] = useState(STEPS.INFO);\n    const [manualCode, setManualCode] = useState(false);\n    const [recoveryCodes, setRecoveryCodes] = useState<string[]>([]);\n    const [password, setPassword] = useState('');\n    const [totp, setTotp] = useState('');\n    const [passwordError, setPasswordError] = useState('');\n    const [totpError, setTotpError] = useState('');\n    const [loading, withLoading] = useLoading();\n\n    const handleClose = loading ? noop : onClose;\n\n    const {\n        section,\n        cancelButtonText,\n        onCancel = handleClose,\n        submitButtonText,\n        onSubmit,\n    } = ((): ModalProperties => {\n        if (!sharedSecret) {\n            return {\n                section: <Loader />,\n            };\n        }\n\n        if (step === STEPS.INFO) {\n            const twoFactorAuthLink =\n                APP_NAME === APPS.PROTONVPN_SETTINGS\n                    ? 'https://protonvpn.com/support/two-factor-authentication'\n                    : getKnowledgeBaseUrl('/two-factor-authentication-2fa');\n\n            // translator: complete sentence is: If you have never used two-factor authentication before, we strongly recommend you <link>read our two-factor authentication Guide first</link>.\n            const guideButton = (\n                <Href key=\"0\" url={twoFactorAuthLink}>{c('Info')\n                    .t`read our two-factor authentication Guide first`}</Href>\n            );\n\n            return {\n                section: (\n                    <>\n                        <div className=\"mb1\">\n                            {c('Info')\n                                .t`This wizard will enable Two-Factor Authentication (2FA) on your Proton account. Two-factor authentication will make your Proton account more secure so we recommend enabling it.`}\n                        </div>\n                        <div className=\"mb1\">\n                            {\n                                // translator: complete sentence is: If you have never used two-factor authentication before, we strongly recommend you <link>read our two-factor authentication Guide first</link>.\n                                c('Info')\n                                    .jt`If you have never used two-factor authentication before, we strongly recommend you ${guideButton}.`\n                            }\n                        </div>\n                    </>\n                ),\n                onSubmit() {\n                    setStep(STEPS.SCAN_CODE);\n                },\n            };\n        }\n\n        const handleSubmitScan = () => {\n            setStep(STEPS.CONFIRM_CODE);\n        };\n\n        if (step === STEPS.SCAN_CODE && !manualCode) {\n            const switchButton = (\n                <InlineLinkButton data-testid=\"totp:manual-button\" key=\"0\" onClick={() => setManualCode(true)}>\n                    {c('Info').t`Enter key manually instead`}\n                </InlineLinkButton>\n            );\n\n            return {\n                section: (\n                    <>\n                        <div className=\"mb1\">\n                            {c('Info')\n                                .jt`Scan this code with your two-factor authentication device to set up your account. ${switchButton}.`}\n                        </div>\n                        <div className=\"text-center\">\n                            <QRCode value={uri} size={200} />\n                        </div>\n                    </>\n                ),\n                onSubmit: handleSubmitScan,\n            };\n        }\n\n        if (step === STEPS.SCAN_CODE && manualCode) {\n            const switchButton = (\n                <InlineLinkButton key=\"0\" onClick={() => setManualCode(false)}>\n                    {c('Info').t`Scan QR code instead`}\n                </InlineLinkButton>\n            );\n\n            return {\n                section: (\n                    <>\n                        <div className=\"mb1\">\n                            {c('Info')\n                                .jt`Manually enter this information into your two-factor authentication device to set up your account. ${switchButton}.`}\n                        </div>\n                        <div>\n                            <div className=\"flex flex-justify-space-between mb0-5\">\n                                <div className=\"w20\">{c('Label').t`Key`}</div>\n                                <div className=\"w80 flex-align-self-center text-bold\">\n                                    <code data-testid=\"totp:secret-key\">{sharedSecret}</code>\n                                </div>\n                            </div>\n                            <div className=\"flex flex-justify-space-between mb0-5\">\n                                <div className=\"w20\">{c('Label').t`Interval`}</div>\n                                <div className=\"w80 flex-align-self-center text-bold\">\n                                    <code>{period}</code>\n                                </div>\n                            </div>\n                            <div className=\"flex flex-justify-space-between mb0-5\">\n                                <div className=\"w20\">{c('Label').t`Digits`}</div>\n                                <div className=\"w80 flex-align-self-center text-bold\">\n                                    <code>{digits}</code>\n                                </div>\n                            </div>\n                        </div>\n                    </>\n                ),\n                onSubmit: handleSubmitScan,\n            };\n        }\n\n        if (step === STEPS.CONFIRM_CODE) {\n            const handleSubmit = async () => {\n                try {\n                    const apiConfig = setupTotp(sharedSecret, totp);\n                    let result: SetupTOTPResponse;\n\n                    // Signed into a public user as an admin, the password and totp are related to the admin and not the user\n                    // so to clarify that we ask in another modal\n                    if (user.isSubUser) {\n                        result = await new Promise<SetupTOTPResponse>((resolve, reject) => {\n                            createModal(\n                                <AuthModal<SetupTOTPResponse>\n                                    onClose={reject}\n                                    onSuccess={({ result }) => resolve(result)}\n                                    config={apiConfig}\n                                />\n                            );\n                        });\n                    } else {\n                        result = await srpAuth<SetupTOTPResponse>({\n                            api,\n                            credentials: { password },\n                            config: apiConfig,\n                        });\n                    }\n\n                    await call();\n                    createNotification({ text: c('Info').t`Two-factor authentication enabled` });\n                    setRecoveryCodes(result.TwoFactorRecoveryCodes);\n                    setStep(STEPS.RECOVERY_CODES);\n                } catch (error: any) {\n                    const { code, message } = getApiError(error);\n\n                    setPasswordError('');\n                    setTotpError('');\n\n                    if (code === PASSWORD_WRONG_ERROR) {\n                        setPasswordError(message);\n                    }\n\n                    if (code === TOTP_WRONG_ERROR) {\n                        setTotpError(message);\n                    }\n                }\n            };\n\n            return {\n                section: (\n                    <PasswordTotpInputs\n                        password={password}\n                        // Password is asked for in a modal when signed into public user\n                        setPassword={user.isSubUser ? undefined : setPassword}\n                        passwordError={passwordError}\n                        totp={totp}\n                        setTotp={setTotp}\n                        totpError={totpError}\n                        showTotp\n                    />\n                ),\n                cancelButtonText: c('Action').t`Back`,\n                onCancel: () => {\n                    setStep(STEPS.SCAN_CODE);\n                },\n                submitButtonText: c('Action').t`Submit`,\n                onSubmit() {\n                    void withLoading(handleSubmit());\n                },\n            };\n        }\n\n        if (step === STEPS.RECOVERY_CODES) {\n            return {\n                section: (\n                    <>\n                        <Alert className=\"mb1\">\n                            <span className=\"text-bold\">{c('Info')\n                                .t`Important: Please make sure you save the recovery codes. Otherwise you can permanently lose access to your account if you lose your two-factor authentication device.`}</span>\n                            <br />\n                            <br />\n                            {c('Info')\n                                .t`If you lose your two-factor-enabled device, these codes can be used instead of the 6-digit two-factor authentication code to log into your account. Each code can only be used once.`}\n                        </Alert>\n                        <div className=\"flex text-center\">\n                            {recoveryCodes.map((code) => {\n                                return (\n                                    <code data-testid=\"totp:recovery-code\" key={code} className=\"w49 p0-5\">\n                                        {code}\n                                    </code>\n                                );\n                            })}\n                        </div>\n                        <div className=\"text-center\">\n                            <Button\n                                onClick={() => {\n                                    const blob = new Blob([recoveryCodes.join('\\r\\n')], {\n                                        type: 'text/plain;charset=utf-8',\n                                    });\n                                    const filename = 'proton_recovery_codes.txt';\n                                    downloadFile(blob, filename);\n                                }}\n                            >\n                                {c('Action').t`Download`}\n                            </Button>\n                        </div>\n                    </>\n                ),\n                submitButtonText: c('Action').t`Ok`,\n                onSubmit() {\n                    onClose?.();\n                },\n                cancelButtonText: null,\n            };\n        }\n\n        throw new Error('Unknown step');\n    })();\n\n    return (\n        <Modal as={Form} onSubmit={onSubmit} onClose={handleClose} size=\"large\" {...rest}>\n            <ModalHeader title={c('Title').t`Set up two-factor authentication`} />\n            <ModalContent>{section}</ModalContent>\n            <ModalFooter>\n                {cancelButtonText !== null ? (\n                    <Button onClick={onCancel} disabled={loading}>\n                        {cancelButtonText || c('Action').t`Cancel`}\n                    </Button>\n                ) : (\n                    // Maintain submit button positioning\n                    <div />\n                )}\n                <Button loading={loading} type=\"submit\" color=\"norm\">\n                    {submitButtonText || c('Action').t`Next`}\n                </Button>\n            </ModalFooter>\n        </Modal>\n    );\n};\n\nexport default EnableTOTPModal;\n","import { ReactNode, useState } from 'react';\nimport { c } from 'ttag';\nimport { disableTotp } from '@proton/shared/lib/api/settings';\nimport { srpAuth } from '@proton/shared/lib/srp';\nimport { PASSWORD_WRONG_ERROR } from '@proton/shared/lib/api/auth';\nimport { getApiError } from '@proton/shared/lib/api/helpers/apiErrorHelper';\nimport { noop } from '@proton/shared/lib/helpers/function';\n\nimport {\n    Loader,\n    ModalProps,\n    ModalTwo as Modal,\n    ModalTwoHeader as ModalHeader,\n    ModalTwoContent as ModalContent,\n    ModalTwoFooter as ModalFooter,\n    Form,\n    Button,\n} from '../../components';\nimport { useLoading, useApi, useEventManager, useNotifications } from '../../hooks';\n\nimport PasswordTotpInputs from '../password/PasswordTotpInputs';\nimport useAskAuth from '../password/useAskAuth';\n\ninterface ModalProperties {\n    section: ReactNode;\n    submitButtonText: string;\n    onSubmit: () => void;\n}\n\nconst STEPS = {\n    CONFIRM: 1,\n    PASSWORD: 2,\n};\n\nconst DisableTOTPModal = ({ onClose, ...rest }: ModalProps) => {\n    const api = useApi();\n    const { call } = useEventManager();\n    const { createNotification } = useNotifications();\n    const [step, setStep] = useState(STEPS.CONFIRM);\n    const [password, setPassword] = useState('');\n    const [totp, setTotp] = useState('');\n    const [error, setError] = useState('');\n    const [loading, withLoading] = useLoading();\n    // Special case for admins signed into public users, TOTP is requested if it's enabled on the admin\n    const [hasTOTPEnabled, isLoadingAuth] = useAskAuth();\n\n    const { section, submitButtonText, onSubmit } = ((): ModalProperties => {\n        if (step === STEPS.CONFIRM) {\n            return {\n                section: (\n                    <div className=\"mb1\">{c('Message')\n                        .t`Are you sure you want to disable two-factor authentication?`}</div>\n                ),\n                submitButtonText: c('Action').t`Yes`,\n                onSubmit() {\n                    setStep(STEPS.PASSWORD);\n                },\n            };\n        }\n\n        if (step === STEPS.PASSWORD) {\n            return {\n                section: isLoadingAuth ? (\n                    <Loader />\n                ) : (\n                    <PasswordTotpInputs\n                        password={password}\n                        setPassword={setPassword}\n                        passwordError={error}\n                        totp={totp}\n                        setTotp={setTotp}\n                        totpError={error}\n                        showTotp={hasTOTPEnabled}\n                    />\n                ),\n                submitButtonText: c('Action').t`Submit`,\n                onSubmit() {\n                    const handleSubmit = async () => {\n                        try {\n                            await srpAuth({\n                                api,\n                                credentials: { password, totp },\n                                config: disableTotp(),\n                            });\n                            await call();\n                            createNotification({ text: c('Info').t`Two-factor authentication disabled` });\n                            onClose?.();\n                        } catch (error: any) {\n                            const { code, message } = getApiError(error);\n                            if (code === PASSWORD_WRONG_ERROR) {\n                                setError(message);\n                            }\n                        }\n                    };\n                    void withLoading(handleSubmit());\n                },\n            };\n        }\n\n        throw new Error('Invalid step');\n    })();\n\n    const handleClose = loading ? noop : onClose;\n\n    return (\n        <Modal as={Form} onSubmit={onSubmit} onClose={handleClose} size=\"large\" {...rest}>\n            <ModalHeader title={c('Title').t`Disable two-factor authentication`} />\n            <ModalContent>{section}</ModalContent>\n            <ModalFooter>\n                <Button onClick={handleClose} disabled={loading}>\n                    {c('Action').t`Cancel`}\n                </Button>\n                <Button loading={loading} type=\"submit\" color=\"norm\">\n                    {submitButtonText || c('Action').t`Next`}\n                </Button>\n            </ModalFooter>\n        </Modal>\n    );\n};\n\nexport default DisableTOTPModal;\n","import { c } from 'ttag';\nimport { APPS } from '@proton/shared/lib/constants';\nimport { getHasTOTPSettingEnabled } from '@proton/shared/lib/settings/twoFactor';\n\nimport { getKnowledgeBaseUrl } from '@proton/shared/lib/helpers/url';\nimport { Info, Toggle, useModalState } from '../../components';\nimport { useConfig, useUserSettings } from '../../hooks';\n\nimport EnableTOTPModal from './EnableTOTPModal';\nimport DisableTOTPModal from './DisableTOTPModal';\nimport SettingsLayout from './SettingsLayout';\nimport SettingsLayoutLeft from './SettingsLayoutLeft';\nimport SettingsLayoutRight from './SettingsLayoutRight';\n\nconst TwoFactorSection = () => {\n    const { APP_NAME } = useConfig();\n    const [userSettings] = useUserSettings();\n    const [enableTOTPModal, setEnableTOTPModalopen, renderEnableTOTPModal] = useModalState();\n    const [disableTOTPModal, setDisableTOTPModalopen, renderDisableTOTPModal] = useModalState();\n\n    const hasTOTPEnabled = getHasTOTPSettingEnabled(userSettings);\n\n    const handleChange = () => {\n        if (hasTOTPEnabled) {\n            setDisableTOTPModalopen(true);\n        } else {\n            setEnableTOTPModalopen(true);\n        }\n    };\n\n    const twoFactorAuthLink =\n        APP_NAME === APPS.PROTONVPN_SETTINGS\n            ? 'https://protonvpn.com/support/two-factor-authentication'\n            : getKnowledgeBaseUrl('/two-factor-authentication-2fa');\n\n    return (\n        <>\n            {renderEnableTOTPModal && <EnableTOTPModal {...enableTOTPModal} />}\n            {renderDisableTOTPModal && <DisableTOTPModal {...disableTOTPModal} />}\n            <SettingsLayout>\n                <SettingsLayoutLeft>\n                    <label htmlFor=\"twoFactorToggle\" className=\"text-semibold\">\n                        <span className=\"mr0-5\">{c('Label').t`Two-factor authentication`}</span>\n                        <Info\n                            url={twoFactorAuthLink}\n                            title={c('Info')\n                                .t`Two-factor authentication adds an extra layer of security to your account in case your password is compromised.`}\n                        />\n                    </label>\n                </SettingsLayoutLeft>\n                <SettingsLayoutRight className=\"pt0-5\">\n                    <Toggle checked={hasTOTPEnabled} id=\"twoFactorToggle\" onChange={handleChange} />\n                </SettingsLayoutRight>\n            </SettingsLayout>\n        </>\n    );\n};\n\nexport default TwoFactorSection;\n","import { useState } from 'react';\nimport { c } from 'ttag';\nimport { SETTINGS_PASSWORD_MODE } from '@proton/shared/lib/interfaces';\nimport { getKnowledgeBaseUrl } from '@proton/shared/lib/helpers/url';\n\nimport { Button, Info, Loader, Toggle } from '../../components';\nimport useModalState from '../../components/modalTwo/useModalState';\nimport { useAddresses, useSearchParamsEffect, useUserSettings } from '../../hooks';\n\nimport ChangePasswordModal, { MODES } from './ChangePasswordModal';\nimport TwoFactorSection from './TwoFactorSection';\nimport SettingsSection from './SettingsSection';\nimport SettingsLayout from './SettingsLayout';\nimport SettingsLayoutLeft from './SettingsLayoutLeft';\nimport SettingsLayoutRight from './SettingsLayoutRight';\n\nconst PasswordsSection = () => {\n    const [userSettings, loadingUserSettings] = useUserSettings();\n    const [addresses, loadingAddresses] = useAddresses();\n\n    const [tmpPasswordMode, setTmpPasswordMode] = useState<MODES>();\n    const [changePasswordModal, setChangePasswordModalOpen, render] = useModalState();\n\n    const isOnePasswordMode = userSettings?.Password?.Mode === SETTINGS_PASSWORD_MODE.ONE_PASSWORD_MODE;\n    const passwordLabel = isOnePasswordMode ? c('Title').t`Password` : c('Title').t`Login password`;\n    const passwordButtonLabel = isOnePasswordMode ? c('Title').t`Change password` : c('Title').t`Change login password`;\n    const changePasswordMode = isOnePasswordMode\n        ? MODES.CHANGE_ONE_PASSWORD_MODE\n        : MODES.CHANGE_TWO_PASSWORD_LOGIN_MODE;\n    const loading = loadingUserSettings || loadingAddresses;\n\n    const handleChangePassword = (mode: MODES) => {\n        setTmpPasswordMode(mode);\n        setChangePasswordModalOpen(true);\n    };\n\n    useSearchParamsEffect(\n        (params) => {\n            if (!loading && params.get('action') === 'change-password') {\n                handleChangePassword(changePasswordMode);\n                params.delete('action');\n                return params;\n            }\n        },\n        [loading]\n    );\n\n    if (loading) {\n        return <Loader />;\n    }\n\n    // VPN users are by default in two password mode, even if they don't have any addresses. Don't allow them to change two-password mode.\n    const hasAddresses = Array.isArray(addresses) && addresses.length > 0;\n\n    return (\n        <>\n            {render && tmpPasswordMode && <ChangePasswordModal mode={tmpPasswordMode} {...changePasswordModal} />}\n            <SettingsSection>\n                <SettingsLayout>\n                    <SettingsLayoutLeft>\n                        <label htmlFor=\"passwordChange\" className=\"text-semibold\">\n                            {passwordLabel}\n                        </label>\n                    </SettingsLayoutLeft>\n                    <SettingsLayoutRight>\n                        <Button color=\"norm\" onClick={() => handleChangePassword(changePasswordMode)}>\n                            {passwordButtonLabel}\n                        </Button>\n                    </SettingsLayoutRight>\n                </SettingsLayout>\n                <TwoFactorSection />\n                {hasAddresses && (\n                    <>\n                        <SettingsLayout>\n                            <SettingsLayoutLeft>\n                                <label htmlFor=\"passwordModeToggle\" className=\"text-semibold\">\n                                    <span className=\"mr0-5\">{c('Label').t`Two-password mode`}</span>\n                                    <Info\n                                        url={getKnowledgeBaseUrl('/single-password')}\n                                        title={c('Info')\n                                            .t`Two-password mode requires two passwords: one to log in to your account and one to decrypt your mailbox. (Advanced)`}\n                                    />\n                                </label>\n                            </SettingsLayoutLeft>\n                            <SettingsLayoutRight className=\"pt0-5\">\n                                <Toggle\n                                    loading={loadingUserSettings}\n                                    checked={!isOnePasswordMode}\n                                    id=\"passwordModeToggle\"\n                                    onChange={() =>\n                                        handleChangePassword(\n                                            isOnePasswordMode ? MODES.SWITCH_TWO_PASSWORD : MODES.SWITCH_ONE_PASSWORD\n                                        )\n                                    }\n                                />\n                            </SettingsLayoutRight>\n                        </SettingsLayout>\n                        {!isOnePasswordMode && (\n                            <SettingsLayout>\n                                <SettingsLayoutLeft>\n                                    <label htmlFor=\"passwordModeToggle\" className=\"text-semibold\">\n                                        <span className=\"mr0-5\">{c('Label').t`Mailbox password`}</span>\n                                        <Info url={getKnowledgeBaseUrl('/single-password')} />\n                                    </label>\n                                </SettingsLayoutLeft>\n                                <SettingsLayoutRight>\n                                    <Button\n                                        color=\"norm\"\n                                        onClick={() => handleChangePassword(MODES.CHANGE_TWO_PASSWORD_MAILBOX_MODE)}\n                                    >\n                                        {c('Action').t`Change mailbox password`}\n                                    </Button>\n                                </SettingsLayoutRight>\n                            </SettingsLayout>\n                        )}\n                    </>\n                )}\n            </SettingsSection>\n        </>\n    );\n};\n\nexport default PasswordsSection;\n","import { useState, useCallback, useEffect, useMemo, useRef } from 'react';\nimport { getClientVPNInfo } from '@proton/shared/lib/api/vpn';\nimport useApi from './useApi';\nimport useCache from './useCache';\n\nexport interface VPNUserInfo {\n    VPN: {\n        ExpirationTime: number;\n        Name: string;\n        Password: string;\n        GroupID: string;\n        Status: number;\n        PlanName: string | null;\n        PlanTitle: string | null;\n        MaxTier: number | null;\n        MaxConnect: number;\n        Groups: string[];\n        NeedConnectionAllocation: boolean;\n    };\n    Warnings: any[];\n    Services: number;\n    Subscribed: number;\n    Delinquent: number;\n    HasPaymentMethod: number;\n    Credit: number;\n    Currency: string;\n}\n\nconst useUserVPN = () => {\n    const api = useApi();\n    const mountedRef = useRef(true);\n    const cache = useCache();\n    const [state, setState] = useState<{\n        error?: Error;\n        result?: VPNUserInfo;\n        loading: boolean;\n    }>(() => ({ result: cache.get('vpn')?.result, loading: false }));\n\n    const fetch = useCallback(async (maxAge = 0) => {\n        try {\n            const cachedValue = cache.get('vpn');\n            const time = new Date().getTime();\n\n            if (cachedValue?.time + maxAge >= time) {\n                setState({ result: cachedValue?.result, loading: false });\n\n                return;\n            }\n\n            if (cachedValue?.promise) {\n                const result = await cachedValue?.promise;\n                setState({ result, loading: false });\n\n                return;\n            }\n\n            const promise = api(getClientVPNInfo()) as Promise<VPNUserInfo>;\n            cache.set('vpn', { promise });\n            const result = await promise;\n            cache.set('vpn', {\n                result,\n                time,\n            });\n\n            if (mountedRef.current) {\n                setState({ result, loading: false });\n            }\n        } catch (e) {\n            cache.delete('vpn');\n\n            if (mountedRef.current) {\n                setState({ error: e as Error, loading: false });\n            }\n        }\n    }, []);\n\n    useEffect(() => {\n        fetch(30_000);\n\n        return () => {\n            mountedRef.current = false;\n        };\n    }, []);\n\n    return useMemo(\n        () => ({\n            ...state,\n            fetch,\n        }),\n        [state]\n    );\n};\n\nexport default useUserVPN;\n","import { ComponentPropsWithoutRef } from 'react';\nimport { classnames } from '../../helpers';\n\nconst SettingsSectionWide = ({ className, ...rest }: ComponentPropsWithoutRef<'div'>) => {\n    return <div className={classnames(['max-w69e', className])} {...rest} />;\n};\n\nexport default SettingsSectionWide;\n","import { useState } from 'react';\nimport { c } from 'ttag';\nimport { resetVPNSettings } from '@proton/shared/lib/api/vpn';\nimport { VPN_APP_NAME } from '@proton/shared/lib/constants';\n\nimport { useApi, useLoading, useNotifications, useUserVPN } from '../../hooks';\nimport { SettingsParagraph, SettingsSectionWide } from '../account';\nimport { Button, Icon, PrimaryButton, Copy, LearnMore } from '../../components';\n\nimport SettingsLayout from '../account/SettingsLayout';\nimport SettingsLayoutLeft from '../account/SettingsLayoutLeft';\nimport SettingsLayoutRight from '../account/SettingsLayoutRight';\n\ninterface Props {\n    app?: string;\n}\n\nconst OpenVPNCredentialsSection = (props: Props) => {\n    const [updating, withUpdating] = useLoading();\n    const { result = {}, fetch: fetchUserVPN } = useUserVPN();\n    const { VPN = {} } = result as any;\n    const { Name = '', Password = '' } = VPN;\n    const [show, setShow] = useState(false);\n    const api = useApi();\n    const { createNotification } = useNotifications();\n    const { app } = props;\n\n    const handleResetCredentials = async () => {\n        await api(resetVPNSettings());\n        await fetchUserVPN();\n\n        createNotification({ text: c('Notification').t`OpenVPN / IKEv2 credentials regenerated` });\n    };\n\n    const learnMore = <LearnMore key=\"learn-more\" url=\"https://protonvpn.com/support/vpn-login/\" />;\n\n    return (\n        <SettingsSectionWide>\n            {app ? (\n                <>\n                    <SettingsParagraph>\n                        {c('Info')\n                            .t`You can use the following credentials to connect to a ${VPN_APP_NAME} server using a third-party, open source VPN app, like Tunnelblick for macOS or OpenVPN for GNU/Linux.`}\n                    </SettingsParagraph>\n                    <SettingsParagraph>\n                        {c('Info').t`Learn how to log in to ${VPN_APP_NAME} with third-party VPN applications.`}\n                    </SettingsParagraph>\n                    <SettingsParagraph>\n                        {c('Info').t`We advise you to use official ${VPN_APP_NAME} applications when possible.`}\n                    </SettingsParagraph>\n                    <SettingsParagraph>\n                        {c('Info').jt`\n                     You cannot use the OpenVPN / IKEv2 credentials to log in to ${VPN_APP_NAME} applications or the ${VPN_APP_NAME} dashboard. ${learnMore}`}\n                    </SettingsParagraph>\n                </>\n            ) : (\n                <>\n                    <SettingsParagraph>\n                        {c('Info')\n                            .t`Use the following credentials when connecting to ${VPN_APP_NAME} servers without application. Examples use cases include: Tunnelblick on macOS, OpenVPN on GNU/Linux.`}\n                    </SettingsParagraph>\n                    <SettingsParagraph>\n                        {c('Info').jt`\n                    Do not use the OpenVPN / IKEv2 credentials in ${VPN_APP_NAME} applications or on the ${VPN_APP_NAME} dashboard. ${learnMore}`}\n                    </SettingsParagraph>\n                </>\n            )}\n\n            <SettingsLayout>\n                <SettingsLayoutLeft>\n                    <span className=\"label pt0\">{c('Label').t`OpenVPN / IKEv2 username`}</span>\n                </SettingsLayoutLeft>\n                <SettingsLayoutRight className=\"flex flex-align-items-center\">\n                    <div className=\"text-ellipsis max-w100 mr1 on-mobile-mr0\">\n                        <code title={Name}>{Name}</code>\n                    </div>\n                    <div className=\"flex flex-item-noshrink on-mobile-mt0-5\">\n                        <Copy value={Name} />\n                    </div>\n                </SettingsLayoutRight>\n            </SettingsLayout>\n            <SettingsLayout>\n                <SettingsLayoutLeft>\n                    <span className=\"label pt0\">{c('Label').t`OpenVPN / IKEv2 password`}</span>\n                </SettingsLayoutLeft>\n                <SettingsLayoutRight className=\"flex flex-align-items-center\">\n                    <div className=\"text-ellipsis max-w100 mr1 on-mobile-mr0\">\n                        <code>{show ? Password : '••••••••••••••••'}</code>\n                    </div>\n                    <div className=\"flex flex-item-noshrink on-mobile-mt0-5\">\n                        <Copy className=\"mr1\" value={Password} />\n                        <Button\n                            icon\n                            onClick={() => setShow(!show)}\n                            title={show ? c('Action').t`Hide` : c('Action').t`Show`}\n                        >\n                            <Icon name={show ? 'eye-slash' : 'eye'} />\n                        </Button>\n                    </div>\n                </SettingsLayoutRight>\n            </SettingsLayout>\n            <PrimaryButton\n                disabled={!Name || !Password}\n                loading={updating}\n                onClick={() => withUpdating(handleResetCredentials())}\n            >{c('Action').t`Reset credentials`}</PrimaryButton>\n        </SettingsSectionWide>\n    );\n};\n\nexport default OpenVPNCredentialsSection;\n","import { c } from 'ttag';\nimport {\n    Alert,\n    Button,\n    ModalProps,\n    ModalTwo as Modal,\n    ModalTwoContent as ModalContent,\n    ModalTwoFooter as ModalFooter,\n    ModalTwoHeader as ModalHeader,\n} from '../../../components';\n\ninterface Props extends ModalProps {\n    onConfirm: () => void;\n    hasReset: boolean;\n    hasNotify: boolean;\n}\n\nconst ConfirmRemoveEmailModal = ({ hasReset, hasNotify, onConfirm, onClose, ...rest }: Props) => {\n    return (\n        <Modal onClose={onClose} {...rest}>\n            <ModalHeader title={c('Title').t`Confirm address`} />\n            <ModalContent>\n                <Alert type=\"warning\">\n                    {hasReset &&\n                        !hasNotify &&\n                        c('Warning').t`By deleting this address, you will no longer be able to recover your account.`}\n                    {hasNotify &&\n                        !hasReset &&\n                        c('Warning')\n                            .t`By deleting this address, you will no longer be able to receive daily email notifications.`}\n                    {hasNotify &&\n                        hasReset &&\n                        c('Warning')\n                            .t`By deleting this address, you will no longer be able to recover your account or receive daily email notifications.`}\n                    <br />\n                    <br />\n                    {c('Warning').t`Are you sure you want to delete the address?`}\n                </Alert>\n            </ModalContent>\n            <ModalFooter>\n                <Button onClick={onClose}>{c('Action').t`Cancel`}</Button>\n                <Button\n                    color=\"norm\"\n                    onClick={() => {\n                        onConfirm();\n                        onClose?.();\n                    }}\n                >\n                    {c('Action').t`Confirm`}\n                </Button>\n            </ModalFooter>\n        </Modal>\n    );\n};\n\nexport default ConfirmRemoveEmailModal;\n","import { useState } from 'react';\nimport { c } from 'ttag';\nimport { postVerifySend } from '@proton/shared/lib/api/verify';\nimport { UserSettings } from '@proton/shared/lib/interfaces';\n\nimport { AlertModal, Button, ModalProps } from '../../../components';\nimport { useApi, useNotifications } from '../../../hooks';\n\ninterface Props extends ModalProps {\n    email: UserSettings['Email'];\n}\n\nconst VerifyRecoveryEmailModal = ({ email, onClose, ...rest }: Props) => {\n    const [loading, setLoading] = useState(false);\n    const api = useApi();\n    const { createNotification } = useNotifications();\n\n    const handleSendVerificationEmailClick = async () => {\n        setLoading(true);\n        await api(postVerifySend({ Type: 'recovery_email' }));\n\n        createNotification({\n            type: 'success',\n            text: c('Recovery Email').t`Verification email sent to ${email.Value}`,\n        });\n\n        onClose?.();\n    };\n    return (\n        <AlertModal\n            title={c('Recovery Email').t`Verify recovery email?`}\n            buttons={[\n                <Button loading={loading} shape=\"solid\" color=\"norm\" onClick={handleSendVerificationEmailClick}>{c(\n                    'Recovery Email'\n                ).t`Send verification email`}</Button>,\n                <Button onClick={onClose} disabled={loading}>{c('Recovery Email').t`Cancel`}</Button>,\n            ]}\n            {...rest}\n        >\n            {c('Recovery Email')\n                .t`Verifying your email address increases your account security and allows additional options for recovery.`}\n        </AlertModal>\n    );\n};\n\nexport default VerifyRecoveryEmailModal;\n","export const postVerifySend = (data: {\n    Type: 'recovery_email' | 'external_email';\n    /* required if type is external_email, optional & not used if type is recovery_email */\n    Destination?: string;\n}) => ({\n    url: 'core/v4/verify/send',\n    method: 'post',\n    data,\n});\n\nexport const postVerifyValidate = (data: { JWT: string }) => ({\n    url: 'core/v4/verify/validate',\n    method: 'post',\n    data,\n});\n","import { useState } from 'react';\nimport { c } from 'ttag';\nimport { updateEmail } from '@proton/shared/lib/api/settings';\nimport { emailValidator } from '@proton/shared/lib/helpers/formValidators';\nimport isTruthy from '@proton/shared/lib/helpers/isTruthy';\nimport { SETTINGS_STATUS, UserSettings } from '@proton/shared/lib/interfaces';\n\nimport { Button, Icon, InputFieldTwo, useFormErrors, useModalState } from '../../../components';\nimport { useEventManager, useLoading, useModals, useNotifications } from '../../../hooks';\nimport { classnames } from '../../../helpers';\nimport AuthModal from '../../password/AuthModal';\nimport ConfirmRemoveEmailModal from './ConfirmRemoveEmailModal';\nimport VerifyRecoveryEmailModal from './VerifyRecoveryEmailModal';\n\ninterface Props {\n    email: UserSettings['Email'];\n    hasReset: boolean;\n    hasNotify: boolean;\n    className?: string;\n}\n\nconst RecoveryEmail = ({ email, hasReset, hasNotify, className }: Props) => {\n    const [input, setInput] = useState(email.Value || '');\n    const [submitting, withSubmitting] = useLoading();\n    const { createNotification } = useNotifications();\n    const { createModal } = useModals();\n    const { call } = useEventManager();\n    const { validator, onFormSubmit } = useFormErrors();\n    const [verifyRecoveryEmailModal, setVerifyRecoveryEmailModalOpen, renderVerifyRecoveryEmailModal] = useModalState();\n\n    const handleSubmit = async () => {\n        const confirmStep = !input && (hasReset || hasNotify);\n        if (confirmStep) {\n            await new Promise<void>((resolve, reject) => {\n                createModal(\n                    <ConfirmRemoveEmailModal\n                        hasReset={hasReset}\n                        hasNotify={hasNotify}\n                        onClose={reject}\n                        onConfirm={resolve}\n                    />\n                );\n            });\n        }\n\n        await new Promise((resolve, reject) => {\n            createModal(<AuthModal onClose={reject} onSuccess={resolve} config={updateEmail({ Email: input })} />);\n        });\n\n        await call();\n\n        createNotification({ text: c('Success').t`Email updated` });\n    };\n\n    return (\n        <>\n            {renderVerifyRecoveryEmailModal && <VerifyRecoveryEmailModal email={email} {...verifyRecoveryEmailModal} />}\n            <form\n                className={classnames(['flex flex-wrap on-mobile-flex-column', className])}\n                onSubmit={(e) => {\n                    e.preventDefault();\n                    if (onFormSubmit()) {\n                        void withSubmitting(handleSubmit());\n                    }\n                }}\n            >\n                <div className=\"mr1 mb1 on-mobile-mr0 flex-item-fluid min-w14e\" title={email.Value || ''}>\n                    <InputFieldTwo\n                        type=\"email\"\n                        autoComplete=\"email\"\n                        id=\"recovery-email-input\"\n                        disableChange={submitting}\n                        value={input || ''}\n                        placeholder={c('Info').t`Not set`}\n                        error={validator([input && emailValidator(input)].filter(isTruthy))}\n                        onValue={setInput}\n                        assistiveText={\n                            email.Value &&\n                            (email.Status === SETTINGS_STATUS.UNVERIFIED ? (\n                                <>\n                                    <Icon\n                                        className=\"color-danger flex-item-noshrink aligntop mr0-25\"\n                                        name=\"exclamation-circle-filled\"\n                                    />\n                                    <span className=\"color-norm mr0-5\">{c('Recovery Email')\n                                        .t`Email address not yet verified.`}</span>\n                                    <button\n                                        className=\"link\"\n                                        type=\"button\"\n                                        onClick={() => setVerifyRecoveryEmailModalOpen(true)}\n                                    >\n                                        {c('Recovery Email').t`Verify now`}\n                                    </button>\n                                </>\n                            ) : (\n                                <>\n                                    <Icon\n                                        className=\"color-success flex-item-noshrink aligntop mr0-25\"\n                                        name=\"checkmark-circle-filled\"\n                                    />\n                                    <span className=\"mr0-5\">{c('Recovery Email')\n                                        .t`Email address has been verified.`}</span>\n                                </>\n                            ))\n                        }\n                    />\n                </div>\n                <div className=\"mb0-5\">\n                    <Button\n                        type=\"submit\"\n                        shape=\"outline\"\n                        disabled={(email.Value || '') === input}\n                        loading={submitting}\n                        data-testid=\"account:recovery:emailSubmit\"\n                    >\n                        {c('Action').t`Save`}\n                    </Button>\n                </div>\n            </form>\n        </>\n    );\n};\n\nexport default RecoveryEmail;\n","import { c } from 'ttag';\nimport {\n    Alert,\n    Button,\n    ModalProps,\n    ModalTwo as Modal,\n    ModalTwoContent as ModalContent,\n    ModalTwoFooter as ModalFooter,\n    ModalTwoHeader as ModalHeader,\n} from '../../../components';\n\ninterface Props extends ModalProps {\n    onConfirm: () => void;\n}\n\nconst ConfirmRemovePhoneModal = ({ onConfirm, onClose, ...rest }: Props) => {\n    return (\n        <Modal onClose={onClose} {...rest}>\n            <ModalHeader title={c('Title').t`Confirm phone number`} />\n            <ModalContent>\n                <Alert type=\"warning\">\n                    {c('Warning').t`By deleting this phone number, you will no longer be able to recover your account.`}\n                    <br />\n                    <br />\n                    {c('Warning').t`Are you sure you want to delete the phone number?`}\n                </Alert>\n            </ModalContent>\n            <ModalFooter>\n                <Button onClick={onClose}>{c('Action').t`Cancel`}</Button>\n                <Button\n                    color=\"norm\"\n                    onClick={() => {\n                        onClose?.();\n                        onConfirm();\n                    }}\n                >\n                    {c('Action').t`Confirm`}\n                </Button>\n            </ModalFooter>\n        </Modal>\n    );\n};\n\nexport default ConfirmRemovePhoneModal;\n","import { useState } from 'react';\nimport { c } from 'ttag';\nimport { updatePhone } from '@proton/shared/lib/api/settings';\n\nimport { Button, InputFieldTwo, PhoneInput, useFormErrors } from '../../../components';\nimport { useNotifications, useEventManager, useModals, useLoading } from '../../../hooks';\nimport { classnames } from '../../../helpers';\nimport ConfirmRemovePhoneModal from './ConfirmRemovePhoneModal';\nimport AuthModal from '../../password/AuthModal';\n\ninterface Props {\n    phone: string | null;\n    hasReset: boolean;\n    defaultCountry?: string;\n    className?: string;\n}\n\nconst RecoveryPhone = ({ phone, hasReset, defaultCountry, className }: Props) => {\n    const [input, setInput] = useState(phone || '');\n    const [submitting, withSubmitting] = useLoading();\n    const { createNotification } = useNotifications();\n    const { createModal } = useModals();\n    const { call } = useEventManager();\n    const { onFormSubmit } = useFormErrors();\n\n    const handleSubmit = async () => {\n        const confirmStep = !input && hasReset;\n        if (confirmStep) {\n            await new Promise<void>((resolve, reject) => {\n                createModal(<ConfirmRemovePhoneModal onClose={reject} onConfirm={resolve} />);\n            });\n        }\n\n        await new Promise((resolve, reject) => {\n            createModal(<AuthModal onClose={reject} onSuccess={resolve} config={updatePhone({ Phone: input })} />);\n        });\n\n        await call();\n\n        createNotification({ text: c('Success').t`Phone number updated` });\n    };\n\n    return (\n        <form\n            className={classnames(['flex flex-wrap on-mobile-flex-column', className])}\n            onSubmit={(e) => {\n                e.preventDefault();\n                if (onFormSubmit()) {\n                    void withSubmitting(handleSubmit());\n                }\n            }}\n        >\n            <div className=\"mr1 on-mobile-mr0 flex-item-fluid min-w14e\">\n                <InputFieldTwo\n                    as={PhoneInput}\n                    id=\"phoneInput\"\n                    disableChange={submitting}\n                    defaultCountry={defaultCountry}\n                    value={input}\n                    onChange={setInput}\n                    aria-label={c('label').t`Recovery phone number`}\n                />\n            </div>\n            <div className=\"mb0-5\">\n                <Button\n                    shape=\"outline\"\n                    type=\"submit\"\n                    disabled={(phone || '') === input}\n                    loading={submitting}\n                    data-testid=\"account:recovery:phoneSubmit\"\n                >\n                    {c('Action').t`Save`}\n                </Button>\n            </div>\n        </form>\n    );\n};\n\nexport default RecoveryPhone;\n","import { c } from 'ttag';\nimport { updateResetEmail, updateResetPhone } from '@proton/shared/lib/api/settings';\n\nimport { Loader, Toggle } from '../../components';\nimport { useEventManager, useLoading, useModals, useMyLocation, useNotifications, useUserSettings } from '../../hooks';\nimport RecoveryEmail from './email/RecoveryEmail';\nimport RecoveryPhone from './phone/RecoveryPhone';\nimport AuthModal from '../password/AuthModal';\nimport SettingsParagraph from '../account/SettingsParagraph';\nimport { SettingsSection } from '../account';\nimport SettingsLayout from '../account/SettingsLayout';\nimport SettingsLayoutLeft from '../account/SettingsLayoutLeft';\nimport SettingsLayoutRight from '../account/SettingsLayoutRight';\n\nconst AccountRecoverySection = () => {\n    const { createModal } = useModals();\n    const [userSettings, loadingUserSettings] = useUserSettings();\n    const [loadingEmailReset, withLoadingEmailReset] = useLoading();\n    const [loadingPhoneReset, withLoadingPhoneReset] = useLoading();\n    const { createNotification } = useNotifications();\n    const { call } = useEventManager();\n    const [myLocation, loadingMyLocation] = useMyLocation();\n    const defaultCountry = myLocation?.Country?.toUpperCase();\n\n    if (loadingUserSettings || !userSettings || loadingMyLocation) {\n        return <Loader />;\n    }\n\n    const handleChangePasswordEmailToggle = async (value: number) => {\n        if (value && !userSettings.Email.Value) {\n            return createNotification({\n                type: 'error',\n                text: c('Error').t`Please set a recovery email first`,\n            });\n        }\n        await new Promise((resolve, reject) => {\n            createModal(<AuthModal onClose={reject} onSuccess={resolve} config={updateResetEmail(value)} />);\n        });\n        await call();\n    };\n\n    const handleChangePasswordPhoneToggle = async (value: number) => {\n        if (value && !userSettings.Phone.Value) {\n            return createNotification({ type: 'error', text: c('Error').t`Please set a recovery phone number first` });\n        }\n        await new Promise((resolve, reject) => {\n            createModal(<AuthModal onClose={reject} onSuccess={resolve} config={updateResetPhone({ Reset: value })} />);\n        });\n        await call();\n    };\n\n    const text = c('Info')\n        .t`In case you lose your login details, we’ll send you recovery instructions via email or SMS.`;\n\n    return (\n        <SettingsSection>\n            <SettingsParagraph>{text}</SettingsParagraph>\n            <SettingsLayout>\n                <SettingsLayoutLeft>\n                    <label className=\"pt0 on-mobile-mb0-5 text-semibold\" htmlFor=\"recovery-email-input\">\n                        {c('Label').t`Recovery email address`}\n                    </label>\n                </SettingsLayoutLeft>\n                <SettingsLayoutRight className=\"flex-item-fluid\">\n                    <RecoveryEmail\n                        className=\"mb0 on-mobile-mb1\"\n                        email={userSettings.Email}\n                        hasReset={!!userSettings.Email.Reset}\n                        hasNotify={!!userSettings.Email.Notify}\n                    />\n                    <div className=\"mb1 flex flex-align-items-center\">\n                        <Toggle\n                            className=\"mr0-5\"\n                            loading={loadingEmailReset}\n                            checked={!!userSettings.Email.Reset && !!userSettings.Email.Value}\n                            id=\"passwordEmailResetToggle\"\n                            onChange={({ target: { checked } }) =>\n                                withLoadingEmailReset(handleChangePasswordEmailToggle(+checked))\n                            }\n                        />\n                        <label htmlFor=\"passwordEmailResetToggle\" className=\"flex-item-fluid\">\n                            {c('Label').t`Allow recovery by email`}\n                        </label>\n                    </div>\n                </SettingsLayoutRight>\n            </SettingsLayout>\n\n            <hr className=\"mb2 mt2\" />\n\n            <SettingsLayout>\n                <SettingsLayoutLeft>\n                    <label className=\"pt0 on-mobile-mb0-5 text-semibold\" htmlFor=\"phoneInput\">\n                        {c('label').t`Recovery phone number`}\n                    </label>\n                </SettingsLayoutLeft>\n                <SettingsLayoutRight className=\"flex-item-fluid\">\n                    <RecoveryPhone\n                        className=\"mb0 on-mobile-mb1\"\n                        defaultCountry={defaultCountry}\n                        phone={userSettings.Phone.Value}\n                        hasReset={!!userSettings.Phone.Reset}\n                    />\n                    <div className=\"flex flex-align-items-center\">\n                        <Toggle\n                            className=\"mr0-5\"\n                            loading={loadingPhoneReset}\n                            checked={!!userSettings.Phone.Reset && !!userSettings.Phone.Value}\n                            id=\"passwordPhoneResetToggle\"\n                            onChange={({ target: { checked } }) =>\n                                withLoadingPhoneReset(handleChangePasswordPhoneToggle(+checked))\n                            }\n                        />\n                        <label htmlFor=\"passwordPhoneResetToggle\" className=\"flex-item-fluid\">\n                            {c('Label').t`Allow recovery by phone`}\n                        </label>\n                    </div>\n                </SettingsLayoutRight>\n            </SettingsLayout>\n        </SettingsSection>\n    );\n};\n\nexport default AccountRecoverySection;\n","import { c } from 'ttag';\nimport { NEWS } from '@proton/shared/lib/constants';\nimport { toggleBit, hasBit } from '@proton/shared/lib/helpers/bitset';\n\nimport { Toggle } from '../../components';\n\nconst { ANNOUNCEMENTS, FEATURES, NEWSLETTER, BETA, BUSINESS, OFFERS } = NEWS;\n\nexport interface EmailSubscriptionCheckboxesProps {\n    disabled: boolean;\n    News: number;\n    onChange: (News: number) => void;\n}\n\nconst EmailSubscriptionCheckboxes = ({ disabled, News, onChange }: EmailSubscriptionCheckboxesProps) => {\n    const handleChange = (mask: number) => () => {\n        onChange(toggleBit(News, mask));\n    };\n\n    const checkboxes = [\n        {\n            id: 'announcements',\n            flag: ANNOUNCEMENTS,\n            text: c('Label for news').t`Proton company announcements`,\n            frequency: c('Frequency of news').t`(1 email per quarter)`,\n        },\n        {\n            id: 'features',\n            flag: FEATURES,\n            text: c('Label for news').t`Proton product announcements`,\n            frequency: c('Frequency of news').t`(1-2 emails per month)`,\n        },\n        {\n            id: 'business',\n            flag: BUSINESS,\n            text: c('Label for news').t`Proton for Business newsletter`,\n            frequency: c('Frequency of news').t`(1 email per month)`,\n        },\n        {\n            id: 'newsletter',\n            flag: NEWSLETTER,\n            text: c('Label for news').t`Proton newsletter`,\n            frequency: c('Frequency of news').t`(1 email per month)`,\n        },\n        {\n            id: 'beta',\n            flag: BETA,\n            text: c('Label for news').t`Proton beta announcements`,\n            frequency: c('Frequency of news').t`(1-2 emails per month)`,\n        },\n        {\n            id: 'offers',\n            flag: OFFERS,\n            text: c('Label for news').t`Proton offers and promotions`,\n            frequency: c('Frequency of news').t`(1 email per quarter)`,\n        },\n    ];\n\n    return (\n        <ul className=\"unstyled relative\">\n            {checkboxes.map(({ id, flag, text, frequency }) => {\n                return (\n                    <li key={id} className=\"mb1 flex flex-align-items-center\">\n                        <Toggle\n                            id={id}\n                            className=\"mr1\"\n                            checked={hasBit(News, flag)}\n                            disabled={disabled}\n                            onChange={handleChange(flag)}\n                        />\n                        <label htmlFor={id} className=\"flex on-mobile-flex-column\">\n                            <span className=\"mr0-25\">{text}</span>\n                            {frequency}\n                        </label>\n                    </li>\n                );\n            })}\n        </ul>\n    );\n};\n\nexport default EmailSubscriptionCheckboxes;\n","import { c } from 'ttag';\nimport { updateNews } from '@proton/shared/lib/api/settings';\n\nimport { useUserSettings, useEventManager, useNotifications, useApi, useLoading } from '../../hooks';\nimport EmailSubscriptionCheckboxes from './EmailSubscriptionCheckboxes';\n\nconst EditNews = () => {\n    const [{ News } = { News: 0 }] = useUserSettings();\n    const { createNotification } = useNotifications();\n    const { call } = useEventManager();\n    const api = useApi();\n    const [loading, withLoading] = useLoading();\n\n    const update = async (News: number) => {\n        await api(updateNews(News));\n        await call();\n        createNotification({ text: c('Info').t`Emailing preference saved` });\n    };\n\n    const handleChange = (News: number) => withLoading(update(News));\n\n    return <EmailSubscriptionCheckboxes News={News} onChange={handleChange} disabled={loading} />;\n};\n\nexport default EditNews;\n","import { c } from 'ttag';\n\nimport { useSubscription } from '../../hooks';\n\nimport MozillaInfoPanel from './MozillaInfoPanel';\nimport EditEmailSubscription from './EditEmailSubscription';\nimport SettingsSection from './SettingsSection';\nimport SettingsParagraph from './SettingsParagraph';\n\nconst EmailSubscriptionSection = () => {\n    const [subscription] = useSubscription();\n\n    if (subscription?.isManagedByMozilla) {\n        return <MozillaInfoPanel />;\n    }\n\n    return (\n        <SettingsSection>\n            <SettingsParagraph>\n                {c('Info')\n                    .t`To keep up with the latest development at Proton products, you can subscribe to our various emails and visit our blog from time to time.`}\n            </SettingsParagraph>\n            <EditEmailSubscription />\n        </SettingsSection>\n    );\n};\n\nexport default EmailSubscriptionSection;\n","import { forwardRef, Ref } from 'react';\nimport Button, { ButtonProps } from './Button';\n\nexport type ErrorButtonProps = Omit<ButtonProps, 'color'>;\n\nconst ErrorButton = (props: ErrorButtonProps, ref: Ref<HTMLButtonElement>) => {\n    return <Button color=\"danger\" ref={ref} {...props} />;\n};\n\nexport default forwardRef<HTMLButtonElement, ErrorButtonProps>(ErrorButton);\n","import { useState } from 'react';\nimport { c } from 'ttag';\nimport { ACCOUNT_DELETION_REASONS } from '@proton/shared/lib/constants';\nimport { deleteUser, canDelete, unlockPasswordChanges } from '@proton/shared/lib/api/user';\nimport { reportBug } from '@proton/shared/lib/api/reports';\nimport { srpAuth } from '@proton/shared/lib/srp';\nimport { wait } from '@proton/shared/lib/helpers/promise';\nimport isTruthy from '@proton/shared/lib/helpers/isTruthy';\nimport { getHasTOTPSettingEnabled } from '@proton/shared/lib/settings/twoFactor';\nimport { omit } from '@proton/shared/lib/helpers/object';\nimport { noop } from '@proton/shared/lib/helpers/function';\nimport { getKnowledgeBaseUrl } from '@proton/shared/lib/helpers/url';\nimport { emailValidator, minLengthValidator, requiredValidator } from '@proton/shared/lib/helpers/formValidators';\n\nimport { getReportInfo, getClientName } from '../../helpers/report';\nimport {\n    Alert,\n    Button,\n    Checkbox,\n    ErrorButton,\n    Info,\n    InputFieldTwo,\n    ModalProps,\n    ModalTwo,\n    ModalTwoContent,\n    ModalTwoHeader,\n    ModalTwoFooter,\n    Option,\n    PasswordInputTwo,\n    SelectTwo,\n    TextAreaTwo,\n    useFormErrors,\n    Form,\n} from '../../components';\nimport {\n    useEventManager,\n    useUser,\n    useNotifications,\n    useUserSettings,\n    useApi,\n    useLoading,\n    useAuthentication,\n    useConfig,\n} from '../../hooks';\n\nconst { DIFFERENT_ACCOUNT, TOO_EXPENSIVE, MISSING_FEATURE, USE_OTHER_SERVICE, OTHER } = ACCOUNT_DELETION_REASONS;\n\ninterface Props extends Omit<ModalProps<'form'>, 'as'> {\n    onSuccess?: () => Promise<void>;\n    hideHeader?: boolean;\n}\n\nconst DeleteAccountModal = (props: Props) => {\n    const { createNotification } = useNotifications();\n\n    const defaultOnSuccess = async () => {\n        createNotification({ text: c('Success').t`Account deleted. Logging out...` });\n\n        // Add an artificial delay to show the notification.\n        await wait(2500);\n    };\n\n    const {\n        onSuccess = defaultOnSuccess,\n        hideHeader = false,\n        onClose,\n        disableCloseOnEscape,\n        size = 'large',\n        ...rest\n    } = props;\n    const eventManager = useEventManager();\n    const api = useApi();\n    const authentication = useAuthentication();\n    const [{ isAdmin, Name }] = useUser();\n    const [userSettings] = useUserSettings();\n    const [loading, withLoading] = useLoading();\n    const [model, setModel] = useState({\n        check: false,\n        reason: '',\n        feedback: '',\n        email: '',\n        password: '',\n        twoFa: '',\n    });\n    const { validator, onFormSubmit } = useFormErrors();\n    const { APP_NAME, APP_VERSION, CLIENT_TYPE } = useConfig();\n    const Client = getClientName(APP_NAME);\n    const hasTOTPEnabled = getHasTOTPSettingEnabled(userSettings);\n\n    const reasons = [\n        <Option\n            title={c('Option').t`I use a different Proton account`}\n            value={DIFFERENT_ACCOUNT}\n            key={DIFFERENT_ACCOUNT}\n        />,\n        isAdmin && <Option title={c('Option').t`It's too expensive`} value={TOO_EXPENSIVE} key={TOO_EXPENSIVE} />,\n        <Option\n            title={c('Option').t`It's missing a key feature that I need`}\n            value={MISSING_FEATURE}\n            key={MISSING_FEATURE}\n        />,\n        <Option\n            title={c('Option').t`I found another service that I like better`}\n            value={USE_OTHER_SERVICE}\n            key={USE_OTHER_SERVICE}\n        />,\n        <Option title={c('Option').t`My reason isn't listed`} value={OTHER} key={OTHER} />,\n    ].filter(isTruthy);\n\n    const handleSubmit = async () => {\n        if (!onFormSubmit()) {\n            return;\n        }\n\n        try {\n            eventManager.stop();\n\n            await srpAuth({\n                api,\n                credentials: { password: model.password, totp: model.twoFa },\n                config: unlockPasswordChanges(),\n            });\n\n            await api(canDelete());\n\n            if (isAdmin) {\n                await api(\n                    reportBug({\n                        ...omit(getReportInfo(), ['OSArtificial']),\n                        Client,\n                        ClientVersion: APP_VERSION,\n                        ClientType: CLIENT_TYPE,\n                        Title: `[DELETION FEEDBACK] ${Name}`,\n                        Username: Name,\n                        Email: model.email,\n                        Description: model.feedback,\n                    })\n                );\n            }\n\n            await api(\n                deleteUser({\n                    Reason: model.reason,\n                    Feedback: model.feedback,\n                    Email: model.email,\n                })\n            );\n\n            await onSuccess?.();\n            onClose?.();\n            authentication.logout();\n        } catch (error: any) {\n            eventManager.start();\n            throw error;\n        }\n    };\n\n    return (\n        <ModalTwo\n            as={Form}\n            onClose={hideHeader ? undefined : onClose}\n            disableCloseOnEscape={disableCloseOnEscape || loading}\n            size={size}\n            onSubmit={loading ? noop : () => withLoading(handleSubmit())}\n            {...rest}\n        >\n            {!hideHeader && <ModalTwoHeader title={c('Title').t`Delete account`} />}\n            <ModalTwoContent>\n                <Alert className=\"mb1\" type=\"warning\" learnMore={getKnowledgeBaseUrl('/combine-accounts')}>\n                    <div className=\"text-bold text-uppercase\">\n                        {c('Info')\n                            .t`Warning: deletion is permanent. This also removes access to all connected services and deletes all of your contacts.`}\n                    </div>\n                    <div>{c('Info').t`If you wish to combine this account with another one, do NOT delete it.`}</div>\n                </Alert>\n                <InputFieldTwo\n                    rootClassName=\"mb0-5\"\n                    as={SelectTwo}\n                    label={c('Label').t`What is the main reason you are deleting your account?`}\n                    placeholder={c('Placeholder').t`Select a reason`}\n                    id=\"reason\"\n                    autoFocus\n                    value={model.reason}\n                    onValue={(value: unknown) => setModel({ ...model, reason: value as string })}\n                    error={validator([requiredValidator(model.reason)])}\n                    disabled={loading}\n                >\n                    {reasons}\n                </InputFieldTwo>\n\n                <InputFieldTwo\n                    id=\"feedback\"\n                    as={TextAreaTwo}\n                    rootClassName=\"mt0-5\"\n                    rows={3}\n                    label={c('Label')\n                        .t`We are sorry to see you go. Please explain why you are leaving to help us improve.`}\n                    placeholder={c('Placeholder').t`Feedback`}\n                    value={model.feedback}\n                    onValue={(value: string) => setModel({ ...model, feedback: value })}\n                    error={validator([requiredValidator(model.feedback), minLengthValidator(model.feedback, 10)])}\n                    disabled={loading}\n                />\n\n                <InputFieldTwo\n                    id=\"email\"\n                    rootClassName=\"mt0-5\"\n                    label={\n                        <>\n                            {c('Label').t`Email address`}&nbsp;\n                            <Info\n                                title={c('Info').t`Please provide an email address in case we need to contact you.`}\n                            />\n                        </>\n                    }\n                    placeholder={c('Placeholder').t`Email address`}\n                    value={model.email}\n                    onValue={(value: string) => setModel({ ...model, email: value })}\n                    error={validator([requiredValidator(model.email), emailValidator(model.email)])}\n                    disabled={loading}\n                />\n\n                <InputFieldTwo\n                    id=\"password\"\n                    rootClassName=\"mt0-5\"\n                    label={\n                        <>\n                            {c('Label').t`Login password`}&nbsp;\n                            <Info title={c('Info').t`Enter your login password to confirm your identity.`} />\n                        </>\n                    }\n                    placeholder={c('Placeholder').t`Password`}\n                    error={validator([requiredValidator(model.password)])}\n                    as={PasswordInputTwo}\n                    autoComplete=\"current-password\"\n                    value={model.password}\n                    onValue={(value: string) => setModel({ ...model, password: value })}\n                    disabled={loading}\n                />\n\n                {hasTOTPEnabled && (\n                    <InputFieldTwo\n                        id=\"twoFa\"\n                        rootClassName=\"mt0-5\"\n                        label={c('Label').t`Two-factor authentication code`}\n                        placeholder={c('Placeholder').t`Two-factor authentication code`}\n                        autoCapitalize=\"off\"\n                        autoCorrect=\"off\"\n                        autoComplete=\"one-time-code\"\n                        value={model.twoFa}\n                        onValue={(value: string) => setModel({ ...model, twoFa: value })}\n                        error={validator([requiredValidator(model.twoFa)])}\n                        disabled={loading}\n                    />\n                )}\n\n                <Checkbox\n                    required\n                    id=\"check\"\n                    checked={model.check}\n                    disabled={loading}\n                    onChange={({ target }) => setModel({ ...model, check: target.checked })}\n                >\n                    {c('Label').t`Yes, I want to permanently delete this account and all its data.`}\n                </Checkbox>\n            </ModalTwoContent>\n            <ModalTwoFooter>\n                <Button onClick={onClose} disabled={loading}>{c('Action').t`Cancel`}</Button>\n                <ErrorButton loading={loading} type=\"submit\">\n                    {c('Action').t`Delete`}\n                </ErrorButton>\n            </ModalTwoFooter>\n        </ModalTwo>\n    );\n};\n\nexport default DeleteAccountModal;\n","import { APPS, MAIL_APP_NAME, VPN_APP_NAME } from '@proton/shared/lib/constants';\nimport { hasMigrationDiscount, hasNewVisionary } from '@proton/shared/lib/helpers/subscription';\nimport { c } from 'ttag';\n\nimport { DiscountWarningModal, NewVisionaryWarningModal } from '../payments/subscription/PlanLossWarningModal';\nimport { Href, Button, Loader } from '../../components';\nimport { useAddresses, useConfig, useSubscription } from '../../hooks';\nimport { useModalState } from '../../components/modalTwo';\n\nimport MozillaInfoPanel from './MozillaInfoPanel';\nimport DeleteAccountModal from './DeleteAccountModal';\nimport SettingsParagraph from './SettingsParagraph';\n\nconst DeleteSection = () => {\n    const [addresses, loadingAddresses] = useAddresses();\n    const [subscription, loadingSubscription] = useSubscription();\n    const { APP_NAME } = useConfig();\n    const [deleteAccountModalProps, setDeleteAccountModalOpen, renderDeleteAccountModal] = useModalState();\n    const [migrationDiscountModalProps, setMigrationDiscountModal, renderDiscountModal] = useModalState();\n    const [visionaryLossModalProps, setVisionaryLossModal, renderVisionaryLossModal] = useModalState();\n\n    if (loadingAddresses || loadingSubscription) {\n        return <Loader />;\n    }\n\n    if (APP_NAME === APPS.PROTONVPN_SETTINGS && addresses.length) {\n        const loginLink = (\n            <Href key=\"0\" url=\"https://account.proton.me/login?product=mail\">\n                mail.protonmail.com\n            </Href>\n        );\n\n        return (\n            <SettingsParagraph>\n                {c('Info')\n                    .jt`Your ${VPN_APP_NAME} and ${MAIL_APP_NAME} accounts are linked. To delete them both, please log in at ${loginLink} and delete your account there.`}\n            </SettingsParagraph>\n        );\n    }\n\n    if (subscription?.isManagedByMozilla) {\n        return <MozillaInfoPanel />;\n    }\n\n    return (\n        <>\n            {renderDiscountModal && (\n                <DiscountWarningModal\n                    type=\"delete\"\n                    {...migrationDiscountModalProps}\n                    onConfirm={() => {\n                        if (hasNewVisionary(subscription)) {\n                            setVisionaryLossModal(true);\n                            return;\n                        }\n                        setDeleteAccountModalOpen(true);\n                    }}\n                />\n            )}\n            {renderVisionaryLossModal && (\n                <NewVisionaryWarningModal\n                    type=\"delete\"\n                    {...visionaryLossModalProps}\n                    onConfirm={() => {\n                        setDeleteAccountModalOpen(true);\n                    }}\n                />\n            )}\n            {renderDeleteAccountModal && <DeleteAccountModal {...deleteAccountModalProps} />}\n            <SettingsParagraph>\n                {c('Info')\n                    .t`This will permanently delete your account and all of its data. You will not be able to reactivate this account.`}\n            </SettingsParagraph>\n            <Button\n                color=\"danger\"\n                shape=\"outline\"\n                id=\"deleteButton\"\n                onClick={() => {\n                    if (hasMigrationDiscount(subscription)) {\n                        setMigrationDiscountModal(true);\n                        return;\n                    }\n                    if (hasNewVisionary(subscription)) {\n                        setVisionaryLossModal(true);\n                        return;\n                    }\n                    setDeleteAccountModalOpen(true);\n                }}\n            >\n                {c('Action').t`Delete your account`}\n            </Button>\n        </>\n    );\n};\n\nexport default DeleteSection;\n","import PropTypes from 'prop-types';\nimport { classnames } from '../../helpers';\n\nconst Block = ({ children, className = '' }) => {\n    return <div className={classnames(['mb1', className])}>{children}</div>;\n};\n\nBlock.propTypes = {\n    children: PropTypes.node,\n    className: PropTypes.string,\n};\n\nexport default Block;\n","import { ReactNode } from 'react';\nimport { c } from 'ttag';\nimport {\n    Bordered,\n    Icon,\n    IconName,\n    Block,\n    Href,\n    SimpleDropdown,\n    DropdownMenu,\n    ButtonGroup,\n    ButtonLike,\n    Button,\n} from '../../../components';\n\ninterface Props {\n    title: string;\n    link: string;\n    icon: IconName;\n    items?: ReactNode[];\n}\n\nconst VPNClientCard = ({ title, link, items, icon }: Props) => {\n    return (\n        <Bordered className=\"rounded-lg flex flex-column flex-align-items-center pt2 pb2 pl3 pr3 mt1 mr1\">\n            <div>\n                <Icon size={60} name={icon} />\n            </div>\n            <Block>{title}</Block>\n            {!items ? (\n                <div className=\"pl1 pr1 flex mt1 flex-justify-center\">\n                    <ButtonLike as={Href} url={link}>\n                        {c('Action').t`Download`}\n                        <span className=\"sr-only\">{title}</span>\n                    </ButtonLike>\n                </div>\n            ) : (\n                <ButtonGroup className=\"flex pl0-25 pr0-25 mt1 flex-justify-center\">\n                    <ButtonLike as={Href} url={link}>\n                        {c('Action').t`Download`}\n                        <span className=\"sr-only\">{title}</span>\n                    </ButtonLike>\n                    <SimpleDropdown\n                        icon\n                        as={Button}\n                        originalPlacement=\"bottom-right\"\n                        title={c('Title').t`Open actions dropdown`}\n                    >\n                        <DropdownMenu>{items}</DropdownMenu>\n                    </SimpleDropdown>\n                </ButtonGroup>\n            )}\n        </Bordered>\n    );\n};\nexport default VPNClientCard;\n","import { HTMLProps, ReactNode } from 'react';\n\nexport interface Props extends HTMLProps<HTMLDivElement> {\n    description?: ReactNode;\n    children?: ReactNode;\n    img?: ReactNode;\n}\n\nconst OnboardingContent = ({ description, img, children, title, ...rest }: Props) => {\n    return (\n        <div {...rest}>\n            {img && <div className=\"pb1 text-center mauto w100 on-mobile-w100\">{img}</div>}\n            {title && <h1 className=\"mb0-5 text-2xl text-bold text-center\">{title}</h1>}\n            {description && <div className=\"mb2 text-center color-weak\">{description}</div>}\n            {children && <div className=\"mb2\">{children}</div>}\n        </div>\n    );\n};\n\nexport default OnboardingContent;\n","import { c } from 'ttag';\nimport { VPN_APP_NAME } from '@proton/shared/lib/constants';\nimport { useHistory, useLocation } from 'react-router-dom';\nimport onboardingVPNWelcome from '@proton/styles/assets/img/onboarding/vpn-welcome.svg';\nimport VPNClientCard from './VPNClientCard';\nimport { DropdownMenuLink, Copy, ModalTwo, ModalProps, Button, Href, ButtonLike } from '../../../components';\nimport { SettingsParagraph, SettingsSectionWide } from '../../account';\nimport { OnboardingContent } from '../../onboarding';\n\ninterface DownloadModalProps extends ModalProps {\n    downloadUrl: string;\n}\n\nconst DownloadModal = ({ downloadUrl, ...rest }: DownloadModalProps) => {\n    return (\n        <ModalTwo {...rest} size=\"small\">\n            <div className=\"p2 text-center\">\n                <OnboardingContent\n                    img={<img src={onboardingVPNWelcome} alt={c('Onboarding').t`Welcome to ${VPN_APP_NAME}`} />}\n                    title={c('Title').t`Download ${VPN_APP_NAME}`}\n                    description={c('Info').t`The securest way to browse, stream, and be online.`}\n                />\n                <ButtonLike\n                    as={Href}\n                    color=\"norm\"\n                    size=\"large\"\n                    target=\"_blank\"\n                    href={downloadUrl}\n                    fullWidth\n                    onClick={() => {\n                        rest.onClose?.();\n                    }}\n                    className=\"mb0-5\"\n                >{c('Action').t`Download`}</ButtonLike>\n                <Button color=\"norm\" size=\"large\" fullWidth shape=\"ghost\" onClick={rest.onClose}>\n                    {c('Action').t`Download on another platform`}\n                </Button>\n            </div>\n        </ModalTwo>\n    );\n};\n\nconst ProtonVPNClientsSection = () => {\n    const history = useHistory();\n    const location = useLocation();\n\n    const androidLinks = [\n        {\n            href: 'https://protonvpn.com/download/ProtonVPN.apk',\n            children: 'APK',\n        },\n        {\n            href: 'https://github.com/ProtonVPN/android-app/releases',\n            children: 'GitHub',\n        },\n        {\n            href: 'https://f-droid.org/en/packages/ch.protonvpn.android/',\n            children: 'F-Droid',\n        },\n    ].map(({ href, children }) => {\n        return (\n            <div className=\"flex flex-align-items-center no-scroll\" key={children}>\n                <DropdownMenuLink className=\"flex-item-fluid\" href={href}>\n                    {children}\n                </DropdownMenuLink>\n                <Copy shape=\"ghost\" value={href} className=\"flex-item-noshrink mr0-5\" />\n            </div>\n        );\n    });\n\n    return (\n        <SettingsSectionWide>\n            <DownloadModal\n                downloadUrl=\"https://protonvpn.com/download\"\n                open={location.search.includes('prompt')}\n                onClose={() => {\n                    history.replace({ ...location, search: '' });\n                }}\n            />\n            <SettingsParagraph>\n                {c('Info')\n                    .t`To secure your internet connection, download and install the ${VPN_APP_NAME} application for your device and connect to a ${VPN_APP_NAME} server.`}\n            </SettingsParagraph>\n            <div className=\"flex on-mobile-flex-column\">\n                <VPNClientCard\n                    title={c('VPNClient').t`Android`}\n                    icon=\"brand-android\"\n                    link=\"https://play.google.com/store/apps/details?id=ch.protonvpn.android&utm_campaign=ww-all-2a-vpn-int_webapp-g_eng-apps_links_dashboard&utm_source=account.protonvpn.com&utm_medium=link&utm_content=dashboard&utm_term=android\"\n                    items={androidLinks}\n                />\n                <VPNClientCard\n                    title={c('VPNClient').t`iOS`}\n                    icon=\"brand-apple\"\n                    link=\"https://apps.apple.com/app/apple-store/id1437005085?pt=106513916&ct=protonvpn.com-dashboard&mt=8\"\n                />\n                <VPNClientCard\n                    title={c('VPNClient').t`Windows`}\n                    icon=\"brand-windows\"\n                    link=\"https://protonvpn.com/download-windows/\"\n                />\n                <VPNClientCard\n                    title={c('VPNClient').t`macOS`}\n                    icon=\"brand-apple\"\n                    link=\"https://protonvpn.com/download-macos/\"\n                />\n                <VPNClientCard\n                    title={c('VPNClient').t`GNU/Linux`}\n                    icon=\"brand-linux\"\n                    link=\"https://protonvpn.com/download-linux/\"\n                />\n                <VPNClientCard\n                    title={c('VPNClient').t`Chromebook`}\n                    icon=\"brand-chrome\"\n                    link=\"https://play.google.com/store/apps/details?id=ch.protonvpn.android&utm_campaign=ww-all-2a-vpn-int_webapp-g_eng-apps_links_dashboard&utm_source=account.protonvpn.com&utm_medium=link&utm_content=dashboard&utm_term=chromebook\"\n                    items={androidLinks}\n                />\n                <VPNClientCard\n                    title={c('VPNClient').t`Android TV`}\n                    icon=\"tv\"\n                    link=\"https://play.google.com/store/apps/details?id=ch.protonvpn.android&utm_campaign=ww-all-2a-vpn-int_webapp-g_eng-apps_links_dashboard&utm_source=account.protonvpn.com&utm_medium=link&utm_content=dashboard&utm_term=androidtv\"\n                    items={androidLinks}\n                />\n            </div>\n        </SettingsSectionWide>\n    );\n};\n\nexport default ProtonVPNClientsSection;\n","import PropTypes from 'prop-types';\nimport { classnames } from '../../helpers';\nimport Radio from './Radio';\n\nconst RadioGroup = ({ name, options, onChange, value, className }) => {\n    const handleChangePlatform = (optionValue) => () => onChange(optionValue);\n\n    return options.map((option, i) => (\n        <Radio\n            key={i}\n            onChange={handleChangePlatform(option.value)}\n            checked={value === option.value}\n            name={name}\n            className={classnames(['mr2', 'mb0-5', 'flex', 'inline-flex-vcenter', className])}\n        >\n            {option.label}\n        </Radio>\n    ));\n};\n\nRadioGroup.propTypes = {\n    className: PropTypes.string,\n    name: PropTypes.string.isRequired,\n    value: PropTypes.any.isRequired,\n    onChange: PropTypes.func.isRequired,\n    options: PropTypes.arrayOf(\n        PropTypes.shape({\n            label: PropTypes.node,\n            value: PropTypes.any,\n        }).isRequired\n    ),\n};\n\nexport default RadioGroup;\n","import { useState, useCallback, useEffect, useMemo, useRef } from 'react';\nimport { queryVPNLogicalServerInfo } from '@proton/shared/lib/api/vpn';\nimport { Logical } from '../containers/vpn/Logical';\nimport useApi from './useApi';\nimport useCache from './useCache';\n\nconst useVPNLogicals = () => {\n    const api = useApi();\n    const mountedRef = useRef(true);\n    const cache = useCache();\n    const [state, setState] = useState<{\n        error?: Error;\n        result?: {\n            LogicalServers: Logical[];\n        };\n        loading: boolean;\n    }>(() => ({ result: cache.get('vpn-logicals')?.result, loading: false }));\n\n    const fetch = useCallback(async (maxAge = 0) => {\n        try {\n            const cachedValue = cache.get('vpn-logicals');\n            const time = new Date().getTime();\n\n            if (cachedValue?.time + maxAge >= time) {\n                setState({ result: cachedValue?.result, loading: false });\n\n                return;\n            }\n\n            if (cachedValue?.promise) {\n                const result = await cachedValue?.promise;\n                setState({ result, loading: false });\n\n                return;\n            }\n\n            const promise = api(queryVPNLogicalServerInfo()) as Promise<{ LogicalServers: Logical[] }>;\n            cache.set('vpn-logicals', { promise });\n            const result = await promise;\n            cache.set('vpn-logicals', {\n                result,\n                time,\n            });\n\n            if (mountedRef.current) {\n                setState({ result, loading: false });\n            }\n        } catch (e) {\n            cache.delete('vpn-logicals');\n\n            if (mountedRef.current) {\n                setState({ error: e as Error, loading: false });\n            }\n        }\n    }, []);\n\n    useEffect(() => {\n        if (!cache.has('vpn-logicals')) {\n            fetch();\n        }\n\n        return () => {\n            mountedRef.current = false;\n        };\n    }, []);\n\n    return useMemo(\n        () => ({\n            ...state,\n            fetch,\n        }),\n        [state]\n    );\n};\n\nexport default useVPNLogicals;\n","import { useState, useMemo } from 'react';\nimport { SORT_DIRECTION } from '@proton/shared/lib/constants';\n\nexport interface SortConfig<T> {\n    key: keyof T;\n    direction: SORT_DIRECTION;\n    compare?: (a: any, b: any) => number;\n}\n\n/**\n * Handles multi-parameter sorting logic for lists\n */\nexport const useMultiSortedList = <T>(list: T[], initialConfig: SortConfig<T>[] = []) => {\n    const [configs, setConfigs] = useState(initialConfig);\n\n    const sortedList = useMemo(() => {\n        if (!configs.length) {\n            return list;\n        }\n\n        const comparator = (a: T, b: T) => {\n            const defaultCompare = (a: T[keyof T], b: T[keyof T]) => {\n                if (a < b) {\n                    return -1;\n                }\n                if (a > b) {\n                    return 1;\n                }\n                return 0;\n            };\n\n            for (let i = 0; i < configs.length; i++) {\n                const config = configs[i];\n                const { key } = config;\n                const compare = ('compare' in config && config.compare) || defaultCompare;\n                const result =\n                    config.direction === SORT_DIRECTION.ASC ? compare(a[key], b[key]) : compare(b[key], a[key]);\n\n                if (result !== 0) {\n                    return result;\n                }\n            }\n            return 0;\n        };\n\n        return [...list].sort(comparator);\n    }, [configs, list]);\n\n    return { sortConfigs: configs, sortedList, setConfigs };\n};\n\n/**\n * Handles sorting logic for lists.\n */\nconst useSortedList = <T>(list: T[], initialConfig?: SortConfig<T>) => {\n    const { setConfigs, sortConfigs, sortedList } = useMultiSortedList(list, initialConfig && [initialConfig]);\n\n    const toggleSort = (key: keyof T) => {\n        if (key === sortConfigs[0]?.key) {\n            setConfigs((configs) => [\n                {\n                    key,\n                    direction: configs[0]?.direction === SORT_DIRECTION.ASC ? SORT_DIRECTION.DESC : SORT_DIRECTION.ASC,\n                },\n            ]);\n        } else {\n            setConfigs([{ key, direction: SORT_DIRECTION.ASC }]);\n        }\n    };\n\n    const setSort = (key: keyof T, direction: SORT_DIRECTION) => {\n        setConfigs([{ key, direction }]);\n    };\n\n    return { sortConfig: sortConfigs[0], sortedList, setSort, toggleSort };\n};\n\n/**\n * Handles sorting logic, when data is async.\n */\nexport const useSortedListAsync = <T>(initialConfig: SortConfig<T>) => useSortedList([], initialConfig);\n\nexport default useSortedList;\n","import { ComponentPropsWithRef, forwardRef, Ref, useRef } from 'react';\n\ntype Props = ComponentPropsWithRef<'details'>;\n\nconst Details = ({ children, className, onToggle, open, ...props }: Props, ref: Ref<HTMLDetailsElement>) => {\n    const initialToggle = useRef(true);\n\n    return (\n        <details\n            className={className}\n            ref={ref}\n            open={open}\n            onToggle={(e) => {\n                // onToggle is invoked even with the first mount if the details\n                // are opened by default. We don't want that.\n                if (initialToggle.current) {\n                    initialToggle.current = false;\n                    if (open) {\n                        return;\n                    }\n                }\n                onToggle?.(e);\n            }}\n            {...props}\n        >\n            {children}\n        </details>\n    );\n};\n\nexport default forwardRef<HTMLDetailsElement, Props>(Details);\n","import { HTMLProps, ReactNode } from 'react';\nimport Icon from '../icon/Icon';\n\ninterface Props extends HTMLProps<HTMLElement> {\n    children: ReactNode;\n}\n\nconst Summary = ({ children, ...rest }: Props) => (\n    // Safari can't set up summary tag as a flex container, tsssss... https://bugs.webkit.org/show_bug.cgi?id=190065\n    <summary {...rest}>\n        <div className=\"flex flex-nowrap\">\n            <Icon name=\"chevron-down\" className=\"summary-caret mr0-25 mt0-25 flex-item-noshrink\" />\n            <div className=\"flex-item-fluid\">{children}</div>\n        </div>\n    </summary>\n);\n\nexport default Summary;\n","import { SERVER_FEATURES } from '@proton/shared/lib/constants';\n\nexport const isFeatureOn =\n    (feature) =>\n    (features = 0) =>\n        !!(features & feature);\nexport const isSecureCoreEnabled = isFeatureOn(SERVER_FEATURES.SECURE_CORE);\nexport const isP2PEnabled = isFeatureOn(SERVER_FEATURES.P2P);\nexport const isTorEnabled = isFeatureOn(SERVER_FEATURES.TOR);\n","import { MouseEvent, ReactNode } from 'react';\nimport { c } from 'ttag';\nimport { Info } from '../link';\n\nimport ButtonGroup from '../button/ButtonGroup';\nimport Button, { ButtonProps } from '../button/Button';\nimport DropdownMenu from './DropdownMenu';\nimport DropdownMenuButton, { Props as DropdownMenuButtonProps } from './DropdownMenuButton';\nimport SimpleDropdown from './SimpleDropdown';\n\nimport { classnames } from '../../helpers';\n\nconst wrapTooltip = (text: string | ReactNode, tooltip?: string) => {\n    if (!tooltip) {\n        return text;\n    }\n    if (typeof text !== 'string') {\n        return text;\n    }\n    return (\n        <>\n            <span className=\"mr0-5\">{text}</span>\n            <Info title={tooltip} />\n        </>\n    );\n};\n\ninterface DropdownActionProps extends DropdownMenuButtonProps {\n    key?: string;\n    text: string | ReactNode;\n    tooltip?: string;\n    onClick?: (e: MouseEvent<HTMLButtonElement>) => void;\n}\n\nexport interface Props extends ButtonProps {\n    loading?: boolean;\n    disabled?: boolean;\n    list?: DropdownActionProps[];\n    className?: string;\n    autoFocus?: boolean;\n}\n\nconst DropdownActions = ({\n    loading = false,\n    disabled = false,\n    list = [],\n    className = '',\n    autoFocus = false,\n    size,\n    ...restButtonProps\n}: Props) => {\n    if (!list.length) {\n        return null;\n    }\n\n    const [{ text, tooltip, ...restProps }, ...restList] = list;\n\n    if (list.length === 1) {\n        return (\n            <Button\n                size={size}\n                loading={loading}\n                disabled={disabled}\n                className={className}\n                {...restProps}\n                {...restButtonProps}\n            >\n                {wrapTooltip(text, tooltip)}\n            </Button>\n        );\n    }\n\n    return (\n        <ButtonGroup size={size}>\n            <Button disabled={disabled || loading} className={className} {...restProps} {...restButtonProps}>\n                {wrapTooltip(text, tooltip)}\n            </Button>\n            <SimpleDropdown\n                as={Button}\n                icon\n                autoFocus={autoFocus}\n                originalPlacement=\"bottom-right\"\n                disabled={disabled}\n                loading={loading}\n                className={classnames(['flex-item-noshrink', className])}\n                title={c('Title').t`Open actions dropdown`}\n                data-test-id=\"dropdown:open\"\n            >\n                <DropdownMenu>\n                    {restList.map(({ text, tooltip, ...restProps }, index) => {\n                        return (\n                            <DropdownMenuButton className=\"text-left\" key={index} {...restProps}>\n                                {wrapTooltip(text, tooltip)}\n                            </DropdownMenuButton>\n                        );\n                    })}\n                </DropdownMenu>\n            </SimpleDropdown>\n        </ButtonGroup>\n    );\n};\n\nexport default DropdownActions;\n","import { ReactNode } from 'react';\nimport { classnames } from '../../helpers';\n\ninterface Props {\n    children?: ReactNode;\n    className?: string;\n    rootRef?: any;\n    size?: number;\n    progress: number;\n}\n\nconst CircularProgress = ({ children, className, progress, rootRef, size = 32, ...rest }: Props) => {\n    return (\n        <svg\n            ref={rootRef}\n            viewBox=\"0 0 35.83098862 35.83098862\"\n            className={classnames(['circle-chart', className])}\n            width={size}\n            height={size}\n            xmlns=\"http://www.w3.org/2000/svg\"\n            {...rest}\n        >\n            <circle\n                className=\"circle-chart-background\"\n                strokeDasharray=\"100, 100\"\n                cx=\"17.91549431\"\n                cy=\"17.91549431\"\n                r=\"15.91549431\"\n            />\n            <circle\n                className=\"circle-chart-circle\"\n                strokeDasharray={`${progress}, 100`}\n                strokeLinecap=\"butt\"\n                cx=\"17.91549431\"\n                cy=\"17.91549431\"\n                r=\"15.91549431\"\n            />\n            {children}\n        </svg>\n    );\n};\n\nexport default CircularProgress;\n","import PropTypes from 'prop-types';\nimport { c } from 'ttag';\nimport { Tooltip, CircularProgress } from '../../../components';\n\nconst LoadIndicator = ({ server: { Load = 0 } }) => {\n    // 1-49% load is GREEN color #5db039\n    // 50-89% load is YELLOW color #eac819\n    // 90-100% load is RED color #ec5858\n    const className = Load < 50 ? '' : Load < 90 ? 'circle-bar--medium' : 'circle-bar--full';\n    return (\n        <span className=\"min-w5e no-mobile\">\n            <Tooltip title={c('Info').t`Server load`}>\n                <div className=\"flex inline-flex-vcenter\">\n                    <CircularProgress progress={Load} size={22} className={className}>\n                        <g className=\"circle-chart-info\">\n                            <rect x=\"17\" y=\"14\" width=\"1.55\" height=\"9.1\" className=\"circle-chart-percent\" />\n                            <rect x=\"17\" y=\"11\" width=\"1.55\" height=\"1.53\" className=\"circle-chart-percent\" />\n                        </g>\n                    </CircularProgress>\n                    <div className=\"ml0-5\">{Load}%</div>\n                </div>\n            </Tooltip>\n        </span>\n    );\n};\n\nLoadIndicator.propTypes = {\n    server: PropTypes.shape({\n        Load: PropTypes.number,\n    }),\n};\n\nexport default LoadIndicator;\n","const flags = require.context('@proton/styles/assets/img/flags', true, /.svg$/);\n\nconst flagsMap = flags.keys().reduce((acc, key) => {\n    acc[key] = () => flags(key);\n\n    return acc;\n}, {} as Record<string, () => string>);\n\nexport const getFlagSvg = (abbreviation: string) => flagsMap[`./${abbreviation}.svg`]?.();\n","import PropTypes from 'prop-types';\nimport { c } from 'ttag';\nimport { getCountryByAbbr, correctAbbr } from '../../../helpers/countries';\nimport { getFlagSvg } from '../flag';\n\nconst Country = ({ server: { EntryCountry, ExitCountry } }) => {\n    const isRouted = EntryCountry && EntryCountry !== ExitCountry;\n    const correctEntryCountry = correctAbbr(EntryCountry);\n    const correctExitCountry = correctAbbr(ExitCountry);\n    const entryCountryName = getCountryByAbbr(correctEntryCountry);\n    const exitCountryName = getCountryByAbbr(correctExitCountry);\n\n    return (\n        <div className=\"inline-flex-vcenter\">\n            <img width={20} className=\"mr0-5 border\" src={getFlagSvg(correctExitCountry)} alt={exitCountryName} />\n            <p className=\"mr0-25 ml0-25\">{getCountryByAbbr(correctExitCountry)}</p>\n            {isRouted && <span className=\"color-weak\">{c('CountryInfo').t`(via ${entryCountryName})`}</span>}\n        </div>\n    );\n};\n\nCountry.propTypes = {\n    server: PropTypes.shape({\n        EntryCountry: PropTypes.string,\n        ExitCountry: PropTypes.string,\n    }),\n};\n\nexport default Country;\n","import PropTypes from 'prop-types';\nimport { memo } from 'react';\nimport { textToClipboard } from '@proton/shared/lib/helpers/browser';\nimport isTruthy from '@proton/shared/lib/helpers/isTruthy';\nimport downloadFile from '@proton/shared/lib/helpers/downloadFile';\nimport { getVPNServerConfig } from '@proton/shared/lib/api/vpn';\nimport { c } from 'ttag';\nimport {\n    Table,\n    TableBody,\n    TableRow,\n    DropdownActions,\n    Tooltip,\n    TableCell,\n    Icon,\n    Button,\n    ButtonLike,\n    SettingsLink,\n} from '../../../components';\nimport { useApi, useNotifications, useUser } from '../../../hooks';\nimport { classnames } from '../../../helpers';\n\nimport LoadIndicator from './LoadIndicator';\nimport Country from './Country';\nimport { isP2PEnabled, isTorEnabled } from './utils';\n\nexport const CATEGORY = {\n    SECURE_CORE: 'SecureCore',\n    COUNTRY: 'Country',\n    SERVER: 'Server',\n    FREE: 'Free',\n};\n\nconst PlusBadge = () => (\n    <span className=\"ml0-5\">\n        <Tooltip title=\"Plus\">\n            <div className=\"text-center rounded\">P</div>\n        </Tooltip>\n    </span>\n);\n\nconst ServerDown = () => (\n    <span className=\"ml0-5\">\n        <Tooltip title={c('Info').t`Server is currently down`}>\n            <div className=\"flex inline-flex-vcenter\">\n                <Icon className=\"color-danger\" size={20} name=\"exclamation-circle\" />\n            </div>\n        </Tooltip>\n    </span>\n);\n\nexport const P2PIcon = () => (\n    <span className=\"ml0-5 mr0-5\">\n        <Tooltip title={c('Info').t`P2P`}>\n            <Icon name=\"arrow-right-arrow-left\" size={18} className=\"rounded bg-strong p0-25\" />\n        </Tooltip>\n    </span>\n);\n\nexport const TorIcon = () => (\n    <span className=\"ml0-5 mr0-5\">\n        <Tooltip title={c('Info').t`Tor`}>\n            <Icon name=\"brand-tor\" size={18} className=\"rounded bg-strong p0-25\" />\n        </Tooltip>\n    </span>\n);\n\n// TODO: Add icons instead of text for p2p and tor when they are ready\nconst ConfigsTable = ({ loading, servers = [], platform, protocol, category, onSelect, selecting }) => {\n    const api = useApi();\n    const { createNotification } = useNotifications();\n    const [{ hasPaidVpn }] = useUser();\n\n    const handleClickDownload =\n        ({ ID, ExitCountry, Domain }) =>\n        async () => {\n            const buffer = await api(\n                getVPNServerConfig({\n                    LogicalID: category === CATEGORY.COUNTRY ? undefined : ID,\n                    Platform: platform,\n                    Protocol: protocol,\n                    Country: ExitCountry,\n                })\n            );\n            const blob = new Blob([buffer], { type: 'application/x-openvpn-profile' });\n            const [country, ...rest] = Domain.split('.');\n            const domain = category === CATEGORY.COUNTRY ? [country.substring(0, 2), ...rest].join('.') : Domain;\n            downloadFile(blob, `${domain}.${protocol}.ovpn`);\n        };\n\n    return (\n        <Table className=\"simple-table--has-actions\">\n            <thead>\n                <tr>\n                    <TableCell\n                        className={classnames(['on-mobile-wauto', category === CATEGORY.SERVER ? 'w25' : 'w33'])}\n                        type=\"header\"\n                    >\n                        {[CATEGORY.SERVER, CATEGORY.FREE].includes(category)\n                            ? c('TableHeader').t`Name`\n                            : c('TableHeader').t`Country`}\n                    </TableCell>\n                    {category === CATEGORY.SERVER ? (\n                        <TableCell className=\"on-mobile-wauto w25\" type=\"header\">{c('TableHeader').t`City`}</TableCell>\n                    ) : null}\n                    <TableCell\n                        className={classnames(['on-mobile-wauto', category === CATEGORY.SERVER ? 'w25' : 'w33'])}\n                        type=\"header\"\n                    >{c('TableHeader').t`Status`}</TableCell>\n                    <TableCell\n                        className={classnames(['on-mobile-wauto', category === CATEGORY.SERVER ? 'w25' : 'w33'])}\n                        type=\"header\"\n                    >{c('TableHeader').t`Action`}</TableCell>\n                </tr>\n            </thead>\n            <TableBody loading={loading} colSpan={4}>\n                {servers.map((server) => (\n                    <TableRow\n                        key={server.ID}\n                        cells={[\n                            [CATEGORY.SERVER, CATEGORY.FREE].includes(category) ? (\n                                server.Name\n                            ) : (\n                                <Country key=\"country\" server={server} />\n                            ),\n                            category === CATEGORY.SERVER ? (\n                                <div className=\"inline-flex-vcenter\" key=\"city\">\n                                    {server.City}\n                                </div>\n                            ) : null,\n                            <div className=\"inline-flex-vcenter\" key=\"status\">\n                                <LoadIndicator server={server} />\n                                {server.Tier === 2 && <PlusBadge />}\n                                {server.Servers.every(({ Status }) => !Status) && <ServerDown />}\n                                {isP2PEnabled(server.Features) && <P2PIcon />}\n                                {isTorEnabled(server.Features) && <TorIcon />}\n                            </div>,\n                            server.isUpgradeRequired ? (\n                                <Tooltip\n                                    key=\"download\"\n                                    title={\n                                        server.Tier === 2\n                                            ? c('Info').t`Plus or Visionary subscription required`\n                                            : c('Info').t`Basic, Plus or Visionary subscription required`\n                                    }\n                                >\n                                    <ButtonLike\n                                        as={SettingsLink}\n                                        color=\"norm\"\n                                        size=\"small\"\n                                        path={hasPaidVpn ? `/dashboard?plan=${PLANS.VPN}` : '/upgrade'}\n                                    >{c('Action').t`Upgrade`}</ButtonLike>\n                                </Tooltip>\n                            ) : onSelect ? (\n                                <Button size=\"small\" onClick={() => onSelect(server)} loading={selecting}>{c('Action')\n                                    .t`Create`}</Button>\n                            ) : (\n                                <DropdownActions\n                                    key=\"dropdown\"\n                                    size=\"small\"\n                                    list={[\n                                        {\n                                            text: c('Action').t`Download`,\n                                            onClick: handleClickDownload(server),\n                                        },\n                                        category !== CATEGORY.SECURE_CORE && {\n                                            text: (\n                                                <div className=\"flex flex-nowrap flex-align-items-center flex-justify-space-between\">\n                                                    <span className=\"mr0-5\">{server.Domain}</span>\n                                                    <Icon name=\"squares\" title={c('Action').t`Copy`} />\n                                                </div>\n                                            ),\n                                            onClick(event) {\n                                                textToClipboard(server.Domain, event.currentTarget);\n                                                createNotification({\n                                                    text: c('Success').t`${server.Domain} copied to your clipboard`,\n                                                });\n                                            },\n                                        },\n                                    ].filter(isTruthy)}\n                                />\n                            ),\n                        ].filter(isTruthy)}\n                    />\n                ))}\n            </TableBody>\n        </Table>\n    );\n};\n\nConfigsTable.propTypes = {\n    onSelect: PropTypes.func,\n    selecting: PropTypes.bool,\n    category: PropTypes.oneOf([CATEGORY.SECURE_CORE, CATEGORY.COUNTRY, CATEGORY.SERVER, CATEGORY.FREE]),\n    platform: PropTypes.string,\n    protocol: PropTypes.string,\n    loading: PropTypes.bool,\n    servers: PropTypes.arrayOf(\n        PropTypes.shape({\n            ID: PropTypes.string,\n            Country: PropTypes.string,\n            EntryCountry: PropTypes.string,\n            ExitCountry: PropTypes.string,\n            Domain: PropTypes.string,\n            Features: PropTypes.number,\n            Load: PropTypes.number,\n            Tier: PropTypes.number,\n        })\n    ),\n};\n\nexport default memo(ConfigsTable);\n","import { c, msgid } from 'ttag';\nimport { VPNServer } from '@proton/shared/lib/interfaces/VPNServer';\n\ninterface Props {\n    group: VPNServer[];\n}\n\nconst ServerNumber = ({ group }: Props) => {\n    const number = group.reduce((acc, { Servers }) => acc + Servers.length, 0);\n    return (\n        <div className=\"inline-flex-vcenter\">\n            {c('Info').ngettext(msgid`${number} server`, `${number} servers`, number)}\n        </div>\n    );\n};\n\nexport default ServerNumber;\n","import { c, msgid } from 'ttag';\nimport { VPNServer } from '@proton/shared/lib/interfaces/VPNServer';\nimport { uniqueBy } from '@proton/shared/lib/helpers/array';\n\ninterface Props {\n    group: VPNServer[];\n}\n\nconst CityNumber = ({ group }: Props) => {\n    const number = uniqueBy(group, ({ City }) => City).length;\n    return (\n        <div className=\"inline-flex-vcenter\">\n            {c('Info').ngettext(msgid`${number} city`, `${number} cities`, number)}\n        </div>\n    );\n};\n\nexport default CityNumber;\n","import { useMemo, useEffect, useCallback } from 'react';\nimport PropTypes from 'prop-types';\nimport { PLANS } from '@proton/shared/lib/constants';\nimport { groupWith, compare } from '@proton/shared/lib/helpers/array';\nimport { Details, Summary } from '../../../components';\nimport { useUser, useUserVPN } from '../../../hooks';\nimport { classnames } from '../../../helpers';\nimport { isSecureCoreEnabled, isP2PEnabled, isTorEnabled } from './utils';\nimport ConfigsTable, { CATEGORY, P2PIcon, TorIcon } from './ConfigsTable';\nimport Country from './Country';\nimport ServerNumber from './ServerNumber';\nimport CityNumber from './CityNumber';\n\nconst getServerNum = (server) => Number(server.Name.replace('-TOR', '').split('#')[1]);\nconst getServerRegion = (server) => server.Name.split('#')[0];\nconst serverRegionAsc = (a, b) => compare(getServerRegion(a), getServerRegion(b));\nconst serverNumAsc = (a, b) => compare(getServerNum(a), getServerNum(b));\nconst serverNameAsc = (a, b) => serverRegionAsc(a, b) || serverNumAsc(a, b);\n\nconst ServerConfigs = ({ servers, category, select, selecting, ...rest }) => {\n    const [{ hasPaidVpn }] = useUser();\n    const { result, fetch: fetchUserVPN } = useUserVPN();\n    const userVPN = result?.VPN || {};\n    const isBasicVPN = userVPN && userVPN.PlanName === PLANS.VPNBASIC;\n    const isUpgradeRequired = useCallback(\n        (server) => {\n            return !userVPN || (!hasPaidVpn && server.Tier > 0) || (isBasicVPN && server.Tier === 2);\n        },\n        [userVPN, hasPaidVpn, isBasicVPN]\n    );\n\n    useEffect(() => {\n        fetchUserVPN(30_000);\n    }, [hasPaidVpn]);\n\n    // Free servers at the top, then sorted by Name#ID\n    const sortedGroups = useMemo(() => {\n        const groupedServers = groupWith(\n            (a, b) => a.Country === b.Country,\n            servers.filter(({ Features = 0 }) => !isSecureCoreEnabled(Features))\n        );\n\n        return groupedServers.map((group) => {\n            const freeServers = group.filter(({ Name }) => Name.includes('FREE')).sort(serverNameAsc);\n            const otherServers = group.filter(({ Name }) => !Name.includes('FREE')).sort(serverNameAsc);\n            return [...freeServers, ...otherServers].map((server) => {\n                return {\n                    ...server,\n                    isUpgradeRequired: isUpgradeRequired(server),\n                };\n            });\n        });\n    }, [servers, isUpgradeRequired]);\n\n    return (\n        <div className=\"mb1-5\">\n            {sortedGroups.map((group) => {\n                const server = group[0];\n                return (\n                    <Details key={server.Country || 'XX'} open={server.open}>\n                        <Summary>\n                            <div className=\"ml0-5 flex flex-nowrap flex-align-items-center\">\n                                <div className={classnames([category === CATEGORY.SERVER ? 'w33' : ''])}>\n                                    <Country server={server} />\n                                </div>\n                                {category === CATEGORY.SERVER && (\n                                    <>\n                                        <div className=\"w33\">\n                                            <ServerNumber group={group} />\n                                        </div>\n                                        <div className=\"w33 flex flex-justify-space-between\">\n                                            <CityNumber group={group} />\n                                            <div className={classnames(['flex'])}>\n                                                {group.some(({ Features }) => isP2PEnabled(Features)) ? (\n                                                    <P2PIcon />\n                                                ) : null}\n                                                {group.some(({ Features }) => isTorEnabled(Features)) ? (\n                                                    <TorIcon />\n                                                ) : null}\n                                            </div>\n                                        </div>\n                                    </>\n                                )}\n                            </div>\n                        </Summary>\n                        <div className=\"p1\">\n                            <ConfigsTable\n                                {...rest}\n                                category={category}\n                                servers={group}\n                                onSelect={select}\n                                selecting={selecting}\n                            />\n                        </div>\n                    </Details>\n                );\n            })}\n        </div>\n    );\n};\n\nServerConfigs.propTypes = {\n    servers: PropTypes.arrayOf(\n        PropTypes.shape({\n            ID: PropTypes.string,\n            Country: PropTypes.string,\n            EntryCountry: PropTypes.string,\n            ExitCountry: PropTypes.string,\n            Domain: PropTypes.string,\n            Features: PropTypes.number,\n            Load: PropTypes.number,\n            Tier: PropTypes.number,\n        })\n    ),\n    category: PropTypes.oneOf([CATEGORY.SECURE_CORE, CATEGORY.COUNTRY, CATEGORY.SERVER, CATEGORY.FREE]),\n    select: PropTypes.func,\n    isSelected: PropTypes.func,\n};\n\nexport default ServerConfigs;\n","import { useState, useMemo, useEffect } from 'react';\nimport PropTypes from 'prop-types';\nimport { c, msgid } from 'ttag';\nimport { getVPNServerConfig } from '@proton/shared/lib/api/vpn';\nimport { groupWith } from '@proton/shared/lib/helpers/array';\nimport downloadFile from '@proton/shared/lib/helpers/downloadFile';\nimport { PLANS, SORT_DIRECTION, VPN_APP_NAME, VPN_CONNECTIONS, VPN_HOSTNAME } from '@proton/shared/lib/constants';\n\nimport {\n    Href,\n    Button,\n    ButtonLike,\n    Icon,\n    Info,\n    Block,\n    Tooltip,\n    Radio,\n    RadioGroup,\n    SettingsLink,\n} from '../../../components';\nimport { useApiWithoutResult, useUser, useSortedList, useUserVPN, usePlans, useVPNLogicals } from '../../../hooks';\nimport { getCountryByAbbr, correctAbbr } from '../../../helpers/countries';\nimport ServerConfigs from './ServerConfigs';\nimport { isSecureCoreEnabled } from './utils';\nimport ConfigsTable, { CATEGORY } from './ConfigsTable';\nimport { SettingsParagraph } from '../../account';\n\nconst PLATFORM = {\n    MACOS: 'macOS',\n    LINUX: 'Linux',\n    WINDOWS: 'Windows',\n    ANDROID: 'Android',\n    IOS: 'iOS',\n    ROUTER: 'Router',\n};\n\nconst PROTOCOL = {\n    TCP: 'tcp',\n    UDP: 'udp',\n};\n\nconst OpenVPNConfigurationSection = ({ onSelect, selecting, listOnly = false, excludedCategories = [] }) => {\n    const [platform, setPlatform] = useState(PLATFORM.ANDROID);\n    const [protocol, setProtocol] = useState(PROTOCOL.UDP);\n    const { request } = useApiWithoutResult(getVPNServerConfig);\n    const [plans, loadingPlans] = usePlans();\n    const { loading, result = {}, fetch: fetchLogicals } = useVPNLogicals();\n    const { result: vpnResult, loading: vpnLoading, fetch: fetchUserVPN } = useUserVPN();\n    const [{ hasPaidVpn }] = useUser();\n    const userVPN = vpnResult?.VPN || {};\n    const isBasicVPN = userVPN?.PlanName === PLANS.VPNBASIC;\n    const maxTier = userVPN?.MaxTier || 0;\n    const [category, setCategory] = useState(CATEGORY.FREE);\n    const excludeCategoryMap = excludedCategories.reduce((map, excludedCategory) => {\n        map[excludedCategory] = true;\n\n        return map;\n    }, {});\n\n    if (maxTier) {\n        excludeCategoryMap[CATEGORY.FREE] = true;\n    }\n\n    const selectedCategory = maxTier && category === CATEGORY.FREE ? CATEGORY.SERVER : category;\n\n    const downloadAllConfigs = async () => {\n        const freeSelected = selectedCategory === CATEGORY.FREE;\n        const buffer = await request({\n            Category: freeSelected ? CATEGORY.SERVER : selectedCategory,\n            Platform: platform,\n            Protocol: protocol,\n            Tier: freeSelected ? 0 : maxTier,\n        });\n        const blob = new Blob([buffer], { type: 'application/zip' });\n        downloadFile(blob, 'ProtonVPN_server_configs.zip');\n    };\n\n    const servers = useMemo(\n        () =>\n            (result.LogicalServers || []).map((server) => ({\n                ...server,\n                Country: getCountryByAbbr(correctAbbr(server.ExitCountry)),\n            })),\n        [result.LogicalServers]\n    );\n\n    const { sortedList: allServers } = useSortedList(servers, { key: 'Country', direction: SORT_DIRECTION.ASC });\n\n    const isUpgradeRequiredForSecureCore = !Object.keys(userVPN).length || !hasPaidVpn || isBasicVPN;\n    const isUpgradeRequiredForCountries = !Object.keys(userVPN).length || !hasPaidVpn;\n    const isUpgradeRequiredForDownloadAll =\n        !Object.keys(userVPN).length ||\n        (!hasPaidVpn && ![CATEGORY.SERVER, CATEGORY.FREE].includes(selectedCategory)) ||\n        (isBasicVPN && selectedCategory === CATEGORY.SECURE_CORE);\n\n    const secureCoreServers = useMemo(() => {\n        return allServers\n            .filter(({ Features }) => isSecureCoreEnabled(Features))\n            .map((server) => {\n                return {\n                    ...server,\n                    isUpgradeRequired: isUpgradeRequiredForSecureCore,\n                };\n            });\n    }, [allServers, isUpgradeRequiredForSecureCore]);\n\n    const countryServers = groupWith(\n        (a, b) => a.ExitCountry === b.ExitCountry,\n        allServers.filter(({ Tier }) => Tier === 1)\n    ).map((groups) => {\n        const [first] = groups;\n        const activeServers = groups.filter(({ Status }) => Status === 1);\n        const load = activeServers.reduce((acc, { Load }) => acc + Load, 0) / activeServers.length;\n        return {\n            ...first,\n            isUpgradeRequired: isUpgradeRequiredForCountries,\n            Load: Number.isNaN(load) ? 0 : Math.round(load),\n            Domain: `${first.EntryCountry.toLowerCase()}.protonvpn.net`, // Forging domain\n            Servers: groups.reduce((acc, { Servers = [] }) => {\n                acc.push(...Servers);\n                return acc;\n            }, []),\n        };\n    });\n\n    const freeServers = useMemo(() => {\n        return allServers.filter(({ Tier }) => Tier === 0).map((server) => ({ ...server, open: true }));\n    }, [allServers]);\n\n    useEffect(() => {\n        if (!hasPaidVpn || userVPN.PlanName === 'trial') {\n            setCategory(CATEGORY.FREE);\n        }\n    }, [vpnLoading]);\n\n    useEffect(() => {\n        fetchUserVPN(30_000);\n    }, [hasPaidVpn]);\n\n    useEffect(() => {\n        fetchLogicals(30_000);\n    }, []);\n\n    const vpnPlan = plans?.find(({ Name }) => Name === PLANS.VPN);\n    const plusVpnConnections = vpnPlan?.MaxVPN || VPN_CONNECTIONS;\n\n    const vpnPlus = vpnPlan?.Title;\n    const vpnBasic = `${VPN_APP_NAME} Basic`;\n    const visionary = 'Visionary';\n\n    return (\n        <>\n            {!vpnLoading && (\n                <>\n                    {!listOnly && (\n                        <>\n                            <SettingsParagraph>\n                                {c('Info')\n                                    .t`These configuration files let you choose which ${VPN_APP_NAME} server you connect to when using a third-party VPN app or setting up a VPN connection on a router.\n                        `}\n                            </SettingsParagraph>\n                            <h3 className=\"mt2\">{c('Title').t`1. Select platform`}</h3>\n                            <div className=\"flex on-mobile-flex-column\">\n                                {[\n                                    {\n                                        value: PLATFORM.ANDROID,\n                                        link: 'https://protonvpn.com/support/android-vpn-setup/',\n                                        label: c('Option').t`Android`,\n                                    },\n                                    {\n                                        value: PLATFORM.IOS,\n                                        link: 'https://protonvpn.com/support/ios-vpn-setup/',\n                                        label: c('Option').t`iOS`,\n                                    },\n                                    {\n                                        value: PLATFORM.WINDOWS,\n                                        link: 'https://protonvpn.com/support/openvpn-windows-setup/',\n                                        label: c('Option').t`Windows`,\n                                    },\n                                    {\n                                        value: PLATFORM.MACOS,\n                                        link: 'https://protonvpn.com/support/mac-vpn-setup/',\n                                        label: c('Option').t`macOS`,\n                                    },\n                                    {\n                                        value: PLATFORM.LINUX,\n                                        link: 'https://protonvpn.com/support/linux-vpn-setup/',\n                                        label: c('Option').t`GNU/Linux`,\n                                    },\n                                    {\n                                        value: PLATFORM.ROUTER,\n                                        link: 'https://protonvpn.com/support/installing-protonvpn-on-a-router/',\n                                        label: c('Option').t`Router`,\n                                    },\n                                ].map(({ value, label, link }) => {\n                                    return (\n                                        <div key={value} className=\"mr2 mb1\">\n                                            <Radio\n                                                onChange={() => setPlatform(value)}\n                                                checked={platform === value}\n                                                name=\"platform\"\n                                                className=\"flex inline-flex-vcenter mb0-5\"\n                                            >\n                                                {label}\n                                            </Radio>\n                                            <Href\n                                                url={link}\n                                                className=\"text-sm m0 block ml-custom\"\n                                                style={{ '--padding-left-custom': `1.312rem` }}\n                                            >{c('Link').t`View guide`}</Href>\n                                        </div>\n                                    );\n                                })}\n                            </div>\n\n                            <h3 className=\"mt2\">{c('Title').t`2. Select protocol`}</h3>\n                            <div className=\"flex on-mobile-flex-column mb0-5\">\n                                <RadioGroup\n                                    name=\"protocol\"\n                                    value={protocol}\n                                    onChange={setProtocol}\n                                    options={[\n                                        { value: PROTOCOL.UDP, label: