useNotifications, useApi, useLoading, useModals, useEventManager } from '../../hooks';\n\nimport CreditCard from './CreditCard';\nimport useCard from './useCard';\nimport toDetails from './toDetails';\nimport { handlePaymentToken } from './paymentTokenHelper';\nimport { CardModel } from './interface';\n\ninterface Props extends Omit<ModalProps<'form'>, 'as' | 'children' | 'size'> {\n    card: CardModel;\n}\n\nconst EditCardModal = ({ card: existingCard, ...rest }: Props) => {\n    const api = useApi();\n    const { call } = useEventManager();\n    const [loading, withLoading] = useLoading();\n    const { createNotification } = useNotifications();\n    const { createModal } = useModals();\n    const title = existingCard ? c('Title').t`Edit credit/debit card` : c('Title').t`Add credit/debit card`;\n    const { card, setCard, errors, isValid } = useCard(existingCard);\n    const [submitted, setSubmitted] = useState(false);\n\n    const handleSubmit = async () => {\n        const { Payment } = await handlePaymentToken({\n            // @ts-expect-error TODO: Fix these types\n            params: {\n                Payment: {\n                    Type: PAYMENT_METHOD_TYPES.CARD,\n                    Details: toDetails(card),\n                },\n            },\n            mode: ADD_CARD_MODE,\n            api,\n            createModal,\n        });\n        await api(setPaymentMethod(Payment));\n        await call();\n        rest.onClose?.();\n        createNotification({ text: c('Success').t`Payment method updated` });\n    };\n\n    return (\n        <ModalTwo\n            size=\"small\"\n            as=\"form\"\n            onSubmit={(event: FormEvent) => {\n                event.preventDefault();\n                setSubmitted(true);\n                if (!isValid) {\n                    return;\n                }\n                withLoading(handleSubmit());\n            }}\n            {...rest}\n        >\n            <ModalTwoHeader title={title} />\n            <ModalTwoContent>\n                <CreditCard card={card} errors={submitted ? errors : {}} onChange={setCard} loading={loading} />\n            </ModalTwoContent>\n            <ModalTwoFooter>\n                <Button disabled={loading} onClick={rest.onClose}>{c('Action').t`Cancel`}</Button>\n                <Button loading={loading} color=\"norm\" type=\"submit\">{c('Action').t`Save`}</Button>\n            </ModalTwoFooter>\n        </ModalTwo>\n    );\n};\n\nexport default EditCardModal;\n","import { useEffect, useRef } from 'react';\nimport { c } from 'ttag';\nimport { createToken, setPaymentMethod } from '@proton/shared/lib/api/payments';\nimport { PAYMENT_METHOD_TYPES } from '@proton/shared/lib/constants';\n\nimport { useApi, useEventManager, useLoading, useNotifications } from '../../hooks';\nimport { AlertModal, ModalProps, Button } from '../../components';\nimport { process } from './paymentTokenHelper';\nimport { PaymentTokenResult } from './interface';\n\nconst PAYMENT_AUTHORIZATION_AMOUNT = 100;\nconst PAYMENT_AUTHORIZATION_CURRENCY = 'CHF';\n\nconst PayPalModal = ({ onClose, ...rest }: ModalProps) => {\n    const api = useApi();\n    const { call } = useEventManager();\n    const { createNotification } = useNotifications();\n    const [loadingToken, withLoadingToken] = useLoading();\n    const [loading, withLoading] = useLoading();\n    const abortRef = useRef<AbortController>();\n    const paypalRef = useRef<PaymentTokenResult | undefined>();\n    const paymentMethodType = PAYMENT_METHOD_TYPES.PAYPAL;\n\n    useEffect(() => {\n        const run = async () => {\n            const result = await api<PaymentTokenResult>(\n                createToken({\n                    Amount: PAYMENT_AUTHORIZATION_AMOUNT,\n                    Currency: PAYMENT_AUTHORIZATION_CURRENCY,\n                    Payment: {\n                        Type: paymentMethodType,\n                    },\n                })\n            );\n            paypalRef.current = result;\n        };\n        void withLoadingToken(run());\n        return () => {\n            abortRef.current?.abort();\n        };\n    }, []);\n\n    const handleSubmit = async (data: PaymentTokenResult) => {\n        abortRef.current = new AbortController();\n        await process({\n            Token: data.Token,\n            api,\n            ApprovalURL: data.ApprovalURL,\n            ReturnHost: data.ReturnHost,\n            signal: abortRef.current.signal,\n        });\n        await api(\n            setPaymentMethod({\n                Type: PAYMENT_METHOD_TYPES.TOKEN,\n                Details: {\n                    Token: data.Token,\n                },\n            })\n        );\n        await call();\n        onClose?.();\n        createNotification({ text: c('Success').t`Payment method added` });\n    };\n\n    return (\n        <AlertModal\n            title={c('Title').t`Add PayPal payment method`}\n            onClose={onClose}\n            buttons={[\n                <Button\n                    color=\"norm\"\n                    loading={loading}\n                    disabled={loadingToken}\n                    onClick={() => {\n                        if (!paypalRef.current) {\n                            return;\n                        }\n                        void withLoading(handleSubmit(paypalRef.current));\n                    }}\n                >{c('Action').t`Add PayPal`}</Button>,\n                <Button onClick={onClose}>{c('Action').t`Cancel`}</Button>,\n            ]}\n            {...rest}\n        >\n            {loading ? (\n                <>\n                    <div className=\"mb1\">{c('Info').t`Please verify payment at the new tab which was opened.`}</div>\n                    <div>{c('Info').t`Verification can take a few minutes.`}</div>\n                </>\n            ) : (\n                <>\n                    <div className=\"mb1\">\n                        {c('Info')\n                            .t`This will enable PayPal to be used to pay for your Proton subscription. We will redirect you to PayPal in a new browser tab. If you use any pop-up blockers, please disable them to continue.`}\n                    </div>\n                    <div>\n                        {c('Info')\n                            .t`You must have a credit card or bank account linked with your PayPal account in order to add it as a payment method.`}\n                    </div>\n                </>\n            )}\n        </AlertModal>\n    );\n};\n\nexport default PayPalModal;\n","import { HTMLAttributes, ReactNode } from 'react';\nimport TableCell from './TableCell';\n\ninterface Props extends HTMLAttributes<HTMLTableSectionElement> {\n    cells?: ReactNode[];\n    children?: ReactNode;\n}\n\nconst TableHeader = ({ cells = [], children, ...rest }: Props) => {\n    return (\n        <thead {...rest}>\n            {children || (\n                <tr>\n                    {cells.map((cell, index) => (\n                        <TableCell key={index.toString()} type=\"header\">\n                            {cell}\n                        </TableCell>\n                    ))}\n                </tr>\n            )}\n        </thead>\n    );\n};\n\nexport default TableHeader;\n","import { c } from 'ttag';\nimport PropTypes from 'prop-types';\nimport { deletePaymentMethod, orderPaymentMethods } from '@proton/shared/lib/api/payments';\nimport { isExpired } from '@proton/shared/lib/helpers/card';\nimport { PAYMENT_METHOD_TYPES } from '@proton/shared/lib/constants';\nimport { DropdownActions, ConfirmModal, Alert, ErrorButton } from '../../components';\nimport { useModals, useApi, useNotifications, useEventManager } from '../../hooks';\nimport EditCardModal from '../payments/EditCardModal';\n\nconst toCard = ({ Details = {}, Type }) => {\n    if (Type === 'card') {\n        return {\n            fullname: Details.Name,\n            month: `${Details.ExpMonth}`, // ExpMonth is a number\n            number: '',\n            year: `${Details.ExpYear}`.slice(-2), // ExpYear is a number\n            cvc: '',\n            zip: Details.ZIP,\n            country: Details.Country,\n        };\n    }\n    return Details;\n};\n\nconst PaymentMethodActions = ({ method, methods, index }) => {\n    const card = toCard(method);\n    const { createNotification } = useNotifications();\n    const { createModal } = useModals();\n    const api = useApi();\n    const { call } = useEventManager();\n\n    const deleteMethod = async () => {\n        await api(deletePaymentMethod(method.ID));\n        await call();\n        createNotification({ text: c('Success').t`Payment method deleted` });\n    };\n\n    const markAsDefault = async () => {\n        const IDs = methods.map(({ ID }) => ID);\n\n        IDs.splice(index, 1);\n        IDs.unshift(method.ID);\n        await api(orderPaymentMethods(IDs));\n        await call();\n        createNotification({ text: c('Success').t`Payment method updated` });\n    };\n\n    const list = [\n        method.Type === PAYMENT_METHOD_TYPES.CARD && {\n            text: c('Action').t`Edit`,\n            onClick: () => createModal(<EditCardModal card={card} />),\n        },\n        index > 0 &&\n            !isExpired(method.Details) && {\n                text: c('Action').t`Mark as default`,\n                onClick: markAsDefault,\n            },\n        {\n            text: c('Action').t`Delete`,\n            actionType: 'delete',\n            onClick: () => {\n                createModal(\n                    <ConfirmModal\n                        onConfirm={deleteMethod}\n                        title={c('Confirmation title').t`Delete payment method`}\n                        confirm={<ErrorButton type=\"submit\">{c('Action').t`Delete`}</ErrorButton>}\n                    >\n                        <Alert className=\"mb1\">{c('Info when deleting payment method')\n                            .t`To avoid any service interruption due to unpaid invoices, please make sure that you have at least 1 valid payment method saved at any point in time.`}</Alert>\n                        <Alert className=\"mb1\" type=\"error\">{c('Confirmation message to delete payment method')\n                            .t`Are you sure you want to delete this payment method?`}</Alert>\n                    </ConfirmModal>\n                );\n            },\n        },\n    ].filter(Boolean);\n\n    return <DropdownActions size=\"small\" list={list} />;\n};\n\nPaymentMethodActions.propTypes = {\n    method: PropTypes.object.isRequired,\n    methods: PropTypes.array.isRequired,\n    index: PropTypes.number.isRequired,\n};\n\nexport default PaymentMethodActions;\n","import { c } from 'ttag';\nimport { PaymentMethod } from '@proton/shared/lib/interfaces';\nimport { isExpired } from '@proton/shared/lib/helpers/card';\nimport { PAYMENT_METHOD_TYPES } from '@proton/shared/lib/constants';\nimport { Badge } from '../../components';\n\ninterface Props {\n    method: PaymentMethod;\n    index?: number;\n}\n\nconst PaymentMethodState = ({ method, index }: Props) => {\n    if (method.Type === PAYMENT_METHOD_TYPES.CARD && isExpired(method.Details)) {\n        return (\n            <Badge type=\"error\">{`${c('Label on payment method').t`Expired`} ${method.Details.ExpMonth}/${\n                method.Details.ExpYear\n            }`}</Badge>\n        );\n    }\n\n    if (!index) {\n        return <Badge type=\"primary\">{c('Label on payment method').t`Default`}</Badge>;\n    }\n\n    return null;\n};\n\nexport default PaymentMethodState;\n","import { c } from 'ttag';\nimport PropTypes from 'prop-types';\nimport { PAYMENT_METHOD_TYPES } from '@proton/shared/lib/constants';\nimport { orderBy } from '@proton/shared/lib/helpers/array';\n\nimport { Table, TableHeader, TableBody, TableRow } from '../../components';\nimport PaymentMethodActions from './PaymentMethodActions';\nimport PaymentMethodState from './PaymentMethodState';\n\nconst PaymentMethodsTable = ({ methods, loading }) => {\n    if (!loading && !methods.length) {\n        return <p>{c('Info').t`You have no saved payment methods.`}</p>;\n    }\n\n    const getMethod = (method) => {\n        switch (method.Type) {\n            case PAYMENT_METHOD_TYPES.CARD:\n                return `${method.Details.Brand} (•••• ${method.Details.Last4})`;\n            case PAYMENT_METHOD_TYPES.PAYPAL:\n                return (\n                    <>\n                        <span className=\"mr0-5\">PayPal</span>\n                        <span className=\"auto-tablet text-ellipsis max-w100\" title={method.Details.Payer}>\n                            {method.Details.Payer}\n                        </span>\n                    </>\n                );\n            default:\n                return '';\n        }\n    };\n\n    const orderedMethods = orderBy(methods, 'Order');\n\n    return (\n        <Table className=\"simple-table--has-actions\">\n            <TableHeader\n                cells={[\n                    c('Title for payment methods table').t`Method`,\n                    c('Title for payment methods table').t`Status`,\n                    c('Title for payment methods table').t`Actions`,\n                ]}\n            />\n            <TableBody loading={loading} colSpan={5}>\n                {orderedMethods.map((method, index) => {\n                    return (\n                        <TableRow\n                            key={method.ID}\n                            cells={[\n                                getMethod(method),\n                                <PaymentMethodState key={method.ID} method={method} index={index} />,\n                                <PaymentMethodActions\n                                    key={method.ID}\n                                    index={index}\n                                    methods={orderedMethods}\n                                    method={method}\n                                />,\n                            ]}\n                        />\n                    );\n                })}\n            </TableBody>\n        </Table>\n    );\n};\n\nPaymentMethodsTable.propTypes = {\n    methods: PropTypes.array.isRequired,\n    loading: PropTypes.bool.isRequired,\n};\n\nexport default PaymentMethodsTable;\n","import { c } from 'ttag';\nimport { APPS, PAYMENT_METHOD_TYPES } from '@proton/shared/lib/constants';\nimport { getKnowledgeBaseUrl } from '@proton/shared/lib/helpers/url';\nimport { useModals, useSubscription, useConfig, usePaymentMethods } from '../../hooks';\nimport { Button, Loader } from '../../components';\n\nimport MozillaInfoPanel from '../account/MozillaInfoPanel';\nimport EditCardModal from '../payments/EditCardModal';\nimport PayPalModal from '../payments/PayPalModal';\nimport PaymentMethodsTable from './PaymentMethodsTable';\nimport { SettingsParagraph, SettingsSection } from '../account';\n\nconst PaymentMethodsSection = () => {\n    const { APP_NAME } = useConfig();\n    const [paymentMethods = [], loadingPaymentMethods] = usePaymentMethods();\n    const [{ isManagedByMozilla } = {}, loadingSubscription] = useSubscription();\n    const { createModal } = useModals();\n\n    if (loadingPaymentMethods || loadingSubscription) {\n        return <Loader />;\n    }\n\n    if (isManagedByMozilla) {\n        return <MozillaInfoPanel />;\n    }\n\n    const handleCard = () => {\n        createModal(<EditCardModal />);\n    };\n\n    const handlePayPal = () => {\n        createModal(<PayPalModal />);\n    };\n\n    const hasPayPal = paymentMethods.some((method) => method.Type === PAYMENT_METHOD_TYPES.PAYPAL);\n\n    const learnMoreUrl =\n        APP_NAME === APPS.PROTONVPN_SETTINGS\n            ? 'https://protonvpn.com/support/payment-options/'\n            : getKnowledgeBaseUrl('/payment-options');\n\n    return (\n        <SettingsSection>\n            <SettingsParagraph learnMoreUrl={learnMoreUrl}>\n                {c('Info for payment methods')\n                    .t`You can add a payment method to have your subscription renewed automatically. Other payment methods are also available.`}\n            </SettingsParagraph>\n            <div className=\"mb1\">\n                <Button shape=\"outline\" className=\"mr1\" onClick={handleCard}>\n                    {c('Action').t`Add credit / debit card`}\n                </Button>\n\n                {hasPayPal ? null : (\n                    <Button shape=\"outline\" onClick={handlePayPal}>\n                        {c('Action').t`Add PayPal`}\n                    </Button>\n                )}\n            </div>\n            <PaymentMethodsTable loading={loadingPaymentMethods || loadingSubscription} methods={paymentMethods} />\n        </SettingsSection>\n    );\n};\n\nexport default PaymentMethodsSection;\n","import { useState } from 'react';\n\nconst usePaginationAsync = (initialPage = 1) => {\n    const [page, setPage] = useState(initialPage);\n    const onNext = () => setPage(page + 1);\n    const onPrevious = () => setPage(page - 1);\n    const onSelect = (p: number) => setPage(p);\n\n    return {\n        page,\n        onNext,\n        onPrevious,\n        onSelect,\n    };\n};\n\nexport default usePaginationAsync;\n","import { c } from 'ttag';\nimport { ButtonGroup, Button } from '../button';\nimport DropdownMenuButton from '../dropdown/DropdownMenuButton';\nimport DropdownMenu from '../dropdown/DropdownMenu';\nimport SimpleDropdown from '../dropdown/SimpleDropdown';\nimport { Icon } from '../icon';\n\ninterface Props {\n    total: number;\n    limit: number;\n    onSelect: (index: number) => void;\n    page?: number;\n    onNext?: () => void;\n    onPrevious?: () => void;\n    hasNext?: boolean;\n    hasPrevious?: boolean;\n}\n\nconst Pagination = ({\n    onNext,\n    onPrevious,\n    onSelect,\n    hasNext = true,\n    hasPrevious = true,\n    page = 1,\n    total,\n    limit,\n}: Props) => {\n    if (!total) {\n        return null;\n    }\n\n    const pages = Math.ceil(total / limit);\n\n    if (pages === 1) {\n        return null;\n    }\n\n    const actions = Array.from({ length: pages }, (a, i) => {\n        const index = i + 1;\n        return (\n            <DropdownMenuButton\n                key={index}\n                onClick={() => onSelect(index)}\n                aria-current={index === page}\n                className={index === page ? 'is-active text-center' : 'text-center'}\n            >\n                {index.toString()}\n            </DropdownMenuButton>\n        );\n    });\n\n    const disablePrevious = page === 1;\n    const disableNext = page === pages;\n\n    return (\n        <ButtonGroup>\n            {hasPrevious ? (\n                <Button\n                    icon\n                    className=\"previous-button on-rtl-mirror\"\n                    disabled={disablePrevious}\n                    onClick={onPrevious}\n                    title={c('Title').t`Previous`}\n                >\n                    <Icon name=\"arrow-left\" />\n                </Button>\n            ) : null}\n            <SimpleDropdown as={Button} title={c('Title').t`Open pagination`} content={page}>\n                <DropdownMenu>{actions}</DropdownMenu>\n            </SimpleDropdown>\n            {hasNext ? (\n                <Button\n                    icon\n                    className=\"next-button on-rtl-mirror\"\n                    disabled={disableNext}\n                    onClick={onNext}\n                    title={c('Title').t`Next`}\n                >\n                    <Icon name=\"arrow-right\" />\n                </Button>\n            ) : null}\n        </ButtonGroup>\n    );\n};\n\nexport default Pagination;\n","import { INVOICE_STATE } from '@proton/shared/lib/constants';\nimport { Price } from '../../components';\nimport { Invoice } from './interface';\n\ninterface Props {\n    invoice: Invoice;\n}\n\nconst format = ({ State, AmountCharged = 0, AmountDue = 0 }: Invoice) => {\n    return State === INVOICE_STATE.UNPAID ? AmountDue : AmountCharged;\n};\n\nconst InvoiceAmount = ({ invoice }: Props) => {\n    return <Price currency={invoice.Currency}>{format(invoice)}</Price>;\n};\n\nexport default InvoiceAmount;\n","import { c } from 'ttag';\nimport { INVOICE_TYPE } from '@proton/shared/lib/constants';\nimport { Invoice } from './interface';\n\nconst getType = (type: INVOICE_TYPE) => {\n    switch (type) {\n        case INVOICE_TYPE.OTHER:\n            return c('Invoice type display as badge').t`Other`;\n        case INVOICE_TYPE.SUBSCRIPTION:\n            return c('Invoice type display as badge').t`Subscription`;\n        case INVOICE_TYPE.CANCELLATION:\n            return c('Invoice type display as badge').t`Cancellation`;\n        case INVOICE_TYPE.CREDIT:\n            return c('Invoice type display as badge').t`Credit`;\n        case INVOICE_TYPE.DONATION:\n            return c('Invoice type display as badge').t`Donation`;\n        case INVOICE_TYPE.CHARGEBACK:\n            return c('Invoice type display as badge').t`Chargeback`;\n        case INVOICE_TYPE.RENEWAL:\n            return c('Invoice type display as badge').t`Renewal`;\n        case INVOICE_TYPE.REFUND:\n            return c('Invoice type display as badge').t`Refund`;\n        case INVOICE_TYPE.MODIFICATION:\n            return c('Invoice type display as badge').t`Modification`;\n        case INVOICE_TYPE.ADDITION:\n            return c('Invoice type display as badge').t`Addition`;\n        default:\n            return '';\n    }\n};\n\ninterface Props {\n    invoice: Invoice;\n}\n\nconst InvoiceType = ({ invoice }: Props) => {\n    return getType(invoice.Type);\n};\n\nexport default InvoiceType;\n","import { c } from 'ttag';\nimport { INVOICE_STATE } from '@proton/shared/lib/constants';\nimport { Badge } from '../../components';\nimport { Invoice } from './interface';\n\nconst TYPES = {\n    [INVOICE_STATE.UNPAID]: 'error',\n    [INVOICE_STATE.PAID]: 'success',\n    [INVOICE_STATE.VOID]: 'default',\n    [INVOICE_STATE.BILLED]: 'default',\n    [INVOICE_STATE.WRITEOFF]: 'default',\n} as const;\n\nconst getStatesI18N = (invoiceState: INVOICE_STATE) => {\n    switch (invoiceState) {\n        case INVOICE_STATE.UNPAID:\n            return c('Invoice state display as badge').t`Unpaid`;\n        case INVOICE_STATE.PAID:\n            return c('Invoice state display as badge').t`Paid`;\n        case INVOICE_STATE.VOID:\n            return c('Invoice state display as badge').t`Void`;\n        case INVOICE_STATE.BILLED:\n            return c('Invoice state display as badge').t`Billed`;\n        case INVOICE_STATE.WRITEOFF:\n            return c('Invoice state display as badge').t`Gifted`;\n        default:\n            return '';\n    }\n};\n\ninterface Props {\n    invoice: Invoice;\n}\n\nconst InvoiceState = ({ invoice }: Props) => {\n    return <Badge type={TYPES[invoice.State] || 'default'}>{getStatesI18N(invoice.State)}</Badge>;\n};\n\nexport default InvoiceState;\n","import PropTypes from 'prop-types';\nimport { c } from 'ttag';\nimport { checkInvoice, payInvoice } from '@proton/shared/lib/api/payments';\nimport { toPrice } from '@proton/shared/lib/helpers/string';\nimport { PAYMENT_METHOD_TYPES } from '@proton/shared/lib/constants';\nimport { Input, FormModal, PrimaryButton, Row, Label, Field, Price } from '../../components';\nimport { useApiResult, useModals, useNotifications, useApi, useLoading, useEventManager } from '../../hooks';\n\nimport StyledPayPalButton from '../payments/StyledPayPalButton';\nimport Payment from '../payments/Payment';\nimport usePayment from '../payments/usePayment';\nimport { handlePaymentToken } from '../payments/paymentTokenHelper';\n\nconst PayInvoiceModal = ({ invoice, fetchInvoices, ...rest }) => {\n    const { createModal } = useModals();\n    const { createNotification } = useNotifications();\n    const [loading, withLoading] = useLoading();\n    const { call } = useEventManager();\n    const api = useApi();\n    const { result = {}, loading: loadingCheck } = useApiResult(() => checkInvoice(invoice.ID), []);\n    const { AmountDue, Amount, Currency, Credit } = result;\n\n    const handleSubmit = async (params) => {\n        const requestBody = await handlePaymentToken({\n            params: { ...params, Amount: AmountDue, Currency },\n            api,\n            createModal,\n        });\n        await api(payInvoice(invoice.ID, requestBody));\n        await Promise.all([\n            call(), // Update user.Delinquent to hide TopBanner\n            fetchInvoices(),\n        ]);\n        rest.onClose();\n        createNotification({ text: c('Success').t`Invoice paid` });\n    };\n\n    const { card, setCard, cardErrors, handleCardSubmit, method, setMethod, parameters, canPay, paypal, paypalCredit } =\n        usePayment({\n            amount: AmountDue,\n            currency: Currency,\n            onPay: handleSubmit,\n        });\n\n    const submit =\n        method === PAYMENT_METHOD_TYPES.PAYPAL ? (\n            <StyledPayPalButton paypal={paypal} flow=\"invoice\" amount={AmountDue} />\n        ) : (\n            <PrimaryButton loading={loading} disabled={!canPay} type=\"submit\">{c('Action').t`Pay`}</PrimaryButton>\n        );\n\n    return (\n        <FormModal\n            onSubmit={() => {\n                if (!handleCardSubmit()) {\n                    return;\n                }\n                withLoading(handleSubmit(parameters));\n            }}\n            loading={loading}\n            close={c('Action').t`Close`}\n            submit={submit}\n            title={c('Title').t`Pay invoice`}\n            {...rest}\n        >\n            {loadingCheck ? null : (\n                <>\n                    {Credit ? (\n                        <>\n                            <Row>\n                                <Label>{c('Label').t`Amount`}</Label>\n                                <Field className=\"text-right\">\n                                    <Price className=\"label\" currency={Currency}>\n                                        {Amount}\n                                    </Price>\n                                </Field>\n                            </Row>\n                            <Row>\n                                <Label>{c('Label').t`Credits used`}</Label>\n                                <Field className=\"text-right\">\n                                    <Price className=\"label\" currency={Currency}>\n                                        {Credit}\n                                    </Price>\n                                </Field>\n                            </Row>\n                        </>\n                    ) : null}\n                    <Row>\n                        <Label>{c('Label').t`Amount due`}</Label>\n                        <Field>\n                            <Input\n                                className=\"field--highlight no-pointer-events text-strong text-right\"\n                                readOnly\n                                value={toPrice(AmountDue, Currency)}\n                            />\n                        </Field>\n                    </Row>\n                    {AmountDue > 0 ? (\n                        <Payment\n                            type=\"invoice\"\n                            paypal={paypal}\n                            paypalCredit={paypalCredit}\n                            method={method}\n                            amount={AmountDue}\n                            currency={Currency}\n                            card={card}\n                            onMethod={setMethod}\n                            onCard={setCard}\n                            cardErrors={cardErrors}\n                        />\n                    ) : null}\n                </>\n            )}\n        </FormModal>\n    );\n};\n\nPayInvoiceModal.propTypes = {\n    invoice: PropTypes.object.isRequired,\n    fetchInvoices: PropTypes.func.isRequired,\n};\n\nexport default PayInvoiceModal;\n","import { c } from 'ttag';\nimport { INVOICE_STATE } from '@proton/shared/lib/constants';\nimport { getPaymentMethodStatus } from '@proton/shared/lib/api/payments';\nimport isTruthy from '@proton/shared/lib/helpers/isTruthy';\n\nimport { DropdownActions } from '../../components';\nimport { useApi, useLoading, useModals, useNotifications } from '../../hooks';\nimport PayInvoiceModal from './PayInvoiceModal';\nimport { Invoice } from './interface';\n\ninterface Props {\n    invoice: Invoice;\n    fetchInvoices: () => void;\n    onPreview: (invoice: Invoice) => void;\n    onDownload: (invoice: Invoice) => void;\n}\n\nconst InvoiceActions = ({ invoice, fetchInvoices, onPreview, onDownload }: Props) => {\n    const { createModal } = useModals();\n    const { createNotification } = useNotifications();\n    const api = useApi();\n    const [downloadLoading, withDownloadLoading] = useLoading();\n    const [viewLoading, withViewLoading] = useLoading();\n\n    const list = [\n        invoice.State === INVOICE_STATE.UNPAID && {\n            text: c('Action').t`Pay`,\n            async onClick() {\n                const { Stripe, Paymentwall } = await api(getPaymentMethodStatus());\n                const canPay = Stripe || Paymentwall;\n\n                if (!canPay) {\n                    createNotification({\n                        type: 'error',\n                        text: c('Error').t`Payments are currently not available, please try again later`,\n                    });\n                }\n\n                createModal(<PayInvoiceModal invoice={invoice} fetchInvoices={fetchInvoices} />);\n            },\n        },\n        {\n            text: c('Action').t`View`,\n            onClick: async () => {\n                const handler = async () => {\n                    onPreview(invoice);\n                };\n                await withViewLoading(handler());\n            },\n            loading: viewLoading,\n        },\n        {\n            text: c('Action').t`Download`,\n            onClick: async () => {\n                const handler = async () => {\n                    onDownload(invoice);\n                };\n                await withDownloadLoading(handler());\n            },\n            loading: downloadLoading,\n        },\n    ].filter(isTruthy);\n\n    return <DropdownActions loading={Boolean(downloadLoading || viewLoading)} list={list} size=\"small\" />;\n};\n\nexport default InvoiceActions;\n","import { useState } from 'react';\nimport { c } from 'ttag';\nimport PropTypes from 'prop-types';\nimport { updateInvoiceText } from '@proton/shared/lib/api/settings';\nimport { FormModal, Alert, Label, TextArea, Block } from '../../components';\nimport { useApiWithoutResult, useUserSettings, useEventManager, useNotifications } from '../../hooks';\n\nconst InvoiceTextModal = ({ onClose, ...rest }) => {\n    const [{ InvoiceText }] = useUserSettings();\n    const { createNotification } = useNotifications();\n    const { call } = useEventManager();\n    const [invoiceText, setInvoiceText] = useState(InvoiceText);\n    const handleChange = ({ target }) => setInvoiceText(target.value);\n    const { request, loading } = useApiWithoutResult(() => updateInvoiceText(invoiceText));\n\n    const handleSubmit = async () => {\n        await request();\n        await call();\n        onClose();\n        createNotification({ text: c('Success').t`Invoice customized` });\n    };\n\n    return (\n        <FormModal\n            small\n            onClose={onClose}\n            onSubmit={handleSubmit}\n            loading={loading}\n            close={c('Action').t`Close`}\n            submit={c('Action').t`Save`}\n            title={c('Title').t`Add invoice details`}\n            {...rest}\n        >\n            <Alert className=\"mb1\">{c('Info message for custom invoice modal')\n                .t`Add your name (or company name) and address to your invoices.`}</Alert>\n            <Block>\n                <Label htmlFor=\"invoiceTextarea\">{c('Label').t`Customize invoices`}</Label>\n            </Block>\n            <TextArea\n                id=\"invoiceTextarea\"\n                autoFocus\n                value={invoiceText}\n                placeholder={c('Placeholder for custom invoice text')\n                    .t`Add your name (or company name) and address to your invoices`}\n                onChange={handleChange}\n                disabled={loading}\n            />\n        </FormModal>\n    );\n};\n\nInvoiceTextModal.propTypes = {\n    onClose: PropTypes.func,\n};\n\nexport default InvoiceTextModal;\n","export enum SortSetting {\n    NameAsc = 1,\n    SizeAsc = 2,\n    TypeAsc = 3,\n    ModifiedAsc = 4,\n    NameDesc = -1,\n    SizeDesc = -2,\n    TypeDesc = -3,\n    ModifiedDesc = -4,\n}\n\nexport enum LayoutSetting {\n    List = 0,\n    Grid = 1,\n}\n\nexport interface UserSettings {\n    Sort: SortSetting;\n    Layout: LayoutSetting;\n}\n","import { isMobile } from '../helpers/browser';\nimport { SORT_DIRECTION } from '../constants';\nimport { LayoutSetting, SortSetting, UserSettings } from '../interfaces/drive/userSettings';\nimport { DriveSectionSortKeys, SharedLinksSectionSortKeys, SortParams } from '../interfaces/drive/link';\n\nexport const MB = 1024 * 1024;\nexport const FOLDER_PAGE_SIZE = 150;\nexport const BATCH_REQUEST_SIZE = 50;\nexport const FILE_CHUNK_SIZE = 4 * MB;\nexport const MEMORY_DOWNLOAD_LIMIT = (isMobile() ? 100 : 500) * MB;\nexport const HARDWARE_CONCURRENCY = (typeof window !== 'undefined' && window.navigator?.hardwareConcurrency) || 1;\n// openpgp.js creates hardwareConcurrency of web workers to do decryption.\n// Using less threads for download means we don't use available potential.\n// Using more threads will not speed things up much because thread in this\n// context is not real thread but concurrently running downloads in the main\n// thread.\n// In the future, with the openpgp.js v5, we will create web workers manually.\n// That will allow us to create more workers and keep download and decryption\n// part in the same thread to save some data exchanges between threads.\n// We could really allow more workers than available CPUs, because decryption\n// is done on the stream as data comes in, i.e., not that heavy operation.\n// Of course, we cannot allow, lets say, twice as many workers per download\n// of one file but for all downloads to not kill user's device. Ideally, we\n// want to make download of one file as fast as possible, but limit it to the\n// same speed with more ongoing downloads or uploads.\nexport const MAX_THREADS_PER_DOWNLOAD = HARDWARE_CONCURRENCY;\nexport const MAX_THREADS_PER_REQUEST = 5;\nexport const DEFAULT_SORT_FIELD = 'ModifyTime';\nexport const DEFAULT_SORT_ORDER = SORT_DIRECTION.DESC;\nexport const DEFAULT_SORT_PARAMS_DRIVE: SortParams<DriveSectionSortKeys> = {\n    sortField: DEFAULT_SORT_FIELD,\n    sortOrder: DEFAULT_SORT_ORDER,\n};\nexport const DEFAULT_SORT_PARAMS_SHARED_LINKS: SortParams<SharedLinksSectionSortKeys> = {\n    sortField: 'CreateTime',\n    sortOrder: DEFAULT_SORT_ORDER,\n};\nexport const DEFAULT_USER_SETTINGS: UserSettings = {\n    Layout: LayoutSetting.List,\n    Sort: SortSetting.ModifiedDesc,\n};\nexport const UPLOAD_TIMEOUT = 90000;\nexport const DOWNLOAD_TIMEOUT = 90000;\nexport const DOWNLOAD_RETRIES_ON_TIMEOUT = 3;\nexport const EXPENSIVE_REQUEST_TIMEOUT = 60000;\nexport const MAX_NAME_LENGTH = 255;\nexport const MIN_SHARED_URL_PASSWORD_LENGTH = 8;\n\nexport const SHARE_GENERATED_PASSWORD_LENGTH = 12;\nexport const DEFAULT_SHARE_MAX_ACCESSES = 10000;\n\nexport const MAX_SAFE_UPLOADING_FILE_COUNT = 500;\n\nexport const CUSTOM_DATA_FORMAT = 'pd-custom';\n\nexport const THUMBNAIL_MAX_SIDE = 256; // in pixels\nexport const THUMBNAIL_MAX_SIZE = 16 * 1024; // in bytes, 16kB\nexport const THUMBNAIL_QUALITIES = [0.7, 0.5, 0.3, 0.1, 0]; // Used qualities to stick under THUMBNAIL_MAX_SIZE.\n\nexport enum LinkURLType {\n    FOLDER = 'folder',\n    FILE = 'file',\n}\n\nexport en