ent Digital Interface (MIDI)',\n    [SupportedMimeTypes.vdnMicrosoftIcon]: 'Icon format',\n    'text/calendar': 'iCalendar format',\n    'text/css': 'Cascading Style Sheets (CSS)',\n    'text/csv': 'Comma-separated values (CSV)',\n    'text/html': 'HyperText Markup Language (HTML)',\n    'text/javascript': 'JavaScript',\n    'text/plain': 'Text',\n    'text/x-csh': 'C-Shell script',\n    'text/x-python': 'Python',\n    'video/webm': 'WEBM video',\n    [SupportedMimeTypes.aac]: 'AAC audio',\n    [SupportedMimeTypes.apng]: 'Animated Portable Network Graphics',\n    [SupportedMimeTypes.apk]: 'Android Package',\n    [SupportedMimeTypes.avi]: 'AVI: Audio Video Interleave',\n    [SupportedMimeTypes.bmp]: 'Windows OS/2 Bitmap Graphics',\n    [SupportedMimeTypes.bzip2]: 'BZip2 archive',\n    [SupportedMimeTypes.docx]: 'Microsoft Word (OpenXML)',\n    [SupportedMimeTypes.eot]: 'MS Embedded OpenType fonts',\n    [SupportedMimeTypes.epub]: 'Electronic publication (EPUB)',\n    [SupportedMimeTypes.flv]: 'Flash Video',\n    [SupportedMimeTypes.gif]: 'Graphics Interchange Format (GIF)',\n    [SupportedMimeTypes.gzip]: 'GZip Compressed Archive',\n    [SupportedMimeTypes.ico]: 'Icon format',\n    [SupportedMimeTypes.jpg]: 'JPEG images',\n    [SupportedMimeTypes.midi]: 'Musical Instrument Digital Interface (MIDI)',\n    [SupportedMimeTypes.mp2t]: 'MPEG transport stream',\n    [SupportedMimeTypes.mpeg]: 'MP3 audio',\n    [SupportedMimeTypes.mpg]: 'MPEG Video',\n    [SupportedMimeTypes.odp]: 'OpenDocument presentation document',\n    [SupportedMimeTypes.ods]: 'OpenDocument spreadsheet document',\n    [SupportedMimeTypes.odt]: 'OpenDocument text document',\n    [SupportedMimeTypes.oga]: 'OGG audio',\n    [SupportedMimeTypes.ogg]: 'OGG',\n    [SupportedMimeTypes.ogv]: 'OGG video',\n    [SupportedMimeTypes.opus]: 'Opus audio',\n    [SupportedMimeTypes.otf]: 'OpenType font',\n    [SupportedMimeTypes.pdf]: 'Adobe Portable Document Format (PDF)',\n    [SupportedMimeTypes.png]: 'Portable Network Graphics',\n    [SupportedMimeTypes.pptx]: 'Microsoft PowerPoint (OpenXML)',\n    [SupportedMimeTypes.rar]: 'RAR archive',\n    [SupportedMimeTypes.rtf]: 'Rich Text Format (RTF)',\n    [SupportedMimeTypes.svg]: 'Scalable Vector Graphics (SVG)',\n    [SupportedMimeTypes.swf]: 'Small web format (SWF)',\n    [SupportedMimeTypes.tar]: 'Tape Archive (TAR)',\n    [SupportedMimeTypes.tiff]: 'Tagged Image File Format (TIFF)',\n    [SupportedMimeTypes.ttf]: 'TrueType Font',\n    [SupportedMimeTypes.v3g2]: '3GPP2 audio/video container',\n    [SupportedMimeTypes.v3gp]: '3GPP audio/video container',\n    [SupportedMimeTypes.wav]: 'Waveform Audio Format',\n    [SupportedMimeTypes.webp]: 'WEBP image',\n    [SupportedMimeTypes.woff]: 'Web Open Font Format (WOFF)',\n    [SupportedMimeTypes.woff2]: 'Web Open Font Format (WOFF)',\n    [SupportedMimeTypes.x7zip]: '7-zip archive',\n    [SupportedMimeTypes.xlsx]: 'Microsoft Excel (OpenXML)',\n    [SupportedMimeTypes.xml]: 'XML',\n    [SupportedMimeTypes.zip]: 'ZIP archive',\n};\n\n// Delete once sharing between members is fully implemented.\nexport const MEMBER_SHARING_ENABLED = false;\n","import { getBrowser } from '@proton/shared/lib/helpers/browser';\nimport { MIME_TYPES } from '../constants';\nimport { SupportedMimeTypes } from '../drive/constants';\n\nconst isWebpSupported = () => {\n    const { name, version } = getBrowser();\n\n    if (name === 'Safari') {\n        /*\n         * The support for WebP image format became available in Safari 14.\n         * It is not possible to support webp images in older Safari versions.\n         * https://developer.apple.com/documentation/safari-release-notes/safari-14-release-notes\n         */\n        return Number(version?.split('.')[0]) >= 14;\n    }\n\n    return true;\n};\n\nexport const isImage = (mimeType: string) => mimeType.startsWith('image/');\n\nexport const isExcel = (mimeType: string) => mimeType.startsWith('application/vnd.ms-excel');\n\nexport const isFont = (mimeType: string) => mimeType.startsWith('font/');\n\nexport const isSupportedImage = (mimeType: string) =>\n    [\n        SupportedMimeTypes.apng,\n        SupportedMimeTypes.bmp,\n        SupportedMimeTypes.gif,\n        SupportedMimeTypes.ico,\n        SupportedMimeTypes.vdnMicrosoftIcon,\n        SupportedMimeTypes.jpg,\n        SupportedMimeTypes.png,\n        SupportedMimeTypes.svg,\n        isWebpSupported() && SupportedMimeTypes.webp,\n    ]\n        .filter(Boolean)\n        .includes(mimeType as SupportedMimeTypes);\n\nexport const isSVG = (mimeType: string) => mimeType === SupportedMimeTypes.svg;\n\nexport const isICS = (mimeType: string) =>\n    mimeType.startsWith(MIME_TYPES.ICS) || mimeType.includes(MIME_TYPES.APPLICATION_ICS);\n\nexport const isSupportedText = (mimeType: string) =>\n    mimeType.startsWith('text/') || ['application/javascript', 'application/typescript'].includes(mimeType);\nexport const isVideo = (mimeType: string) => mimeType.startsWith('video/');\nexport const isPDF = (mimeType: string) => mimeType === 'application/pdf' || mimeType === 'x-pdf';\n\n/**\n * isSupportedVideo returns true for any video smaller than 100 MB.\n * The reason is currently we don't support streaming and thus the whole\n * video content has to be buffered and fit memory.\n */\nexport const isSupportedVideo = (mimeType: string, fileSize?: number) =>\n    isVideo(mimeType) && fileSize && fileSize < 1024 * 1024 * 100;\n","import { forwardRef, ComponentPropsWithRef } from 'react';\n\nimport { classnames } from '../../helpers';\nimport { IconSize } from './Icon';\n\nexport type MimeName =\n    | 'attachments'\n    | 'calendar'\n    | 'doc'\n    | 'folder'\n    | 'font'\n    | 'image'\n    | 'keynote'\n    | 'keytrust'\n    | 'numbers'\n    | 'pages'\n    | 'pdf'\n    | 'ppt'\n    | 'sound'\n    | 'text'\n    | 'unknown'\n    | 'video'\n    | 'xls'\n    | 'xml'\n    | 'zip';\n\nconst viewboxMap = {\n    sm: 16,\n    md: 24,\n    lg: 48,\n};\n\nconst getIconAsset = (size: IconSize) => {\n    if (size < 20) {\n        return 'sm';\n    }\n    if (size < 40) {\n        return 'md';\n    }\n    return 'lg';\n};\n\nexport interface MimeIconProps extends ComponentPropsWithRef<'svg'> {\n    name: MimeName;\n    size?: IconSize;\n    /** If specified, renders an sr-only element for screenreaders */\n    alt?: string;\n    /** If specified, renders an inline title element */\n    title?: string;\n}\n\n/**\n * Component to render SVG file icons.\n * Use it the same way as Icon, just without need to specify name space\n * (automatically mime is used), and proper asset is chosen based on the\n * passed size parameter: mime icons have three different shapes to fit\n * any space the best way.\n */\nconst MimeIcon = forwardRef<SVGSVGElement, MimeIconProps>(\n    ({ name, size = 16, alt, title, className, ...rest }, ref) => {\n        const iconAsset = getIconAsset(size);\n        const viewBox = `0 0 ${viewboxMap[iconAsset]} ${viewboxMap[iconAsset]}`;\n        const xlinkHref = `#mime-${iconAsset}-${name}`;\n\n        return (\n            <>\n                <svg\n                    role=\"img\"\n                    viewBox={viewBox}\n                    focusable=\"false\"\n                    className={classnames([`icon-${size}p`, className])}\n                    ref={ref}\n                    {...rest}\n                >\n                    {title && <title>{title}</title>}\n                    <use xlinkHref={xlinkHref} />\n                </svg>\n\n                {alt ? <span className=\"sr-only\">{alt}</span> : null}\n            </>\n        );\n    }\n);\n\nexport default MimeIcon;\n","import { isImage, isSupportedText, isPDF, isVideo, isFont, isExcel, isICS } from '@proton/shared/lib/helpers/mimetype';\n\nimport { classnames } from '../../helpers/component';\nimport MimeIcon, { MimeIconProps, MimeName } from '../icon/MimeIcon';\n\nconst iconsMap: { [mimeType: string]: MimeName } = {\n    Folder: 'folder',\n\n    'application/x-rar-compressed': 'zip',\n    'application/x-zip-compressed': 'zip',\n    'application/zip': 'zip',\n    'application/x-7z-compressed': 'zip', // .7z — 7-Zip compressed file\n    'application/x-arj': 'zip', // .arj — ARJ compressed file\n    'application/x-debian-package': 'zip', // .deb — Debian software package file\n    'application/octet-stream': 'zip', // .pkg\n    'application/x-redhat-package-manager': 'zip', // .rpm\n    'application/x-rpm': 'zip', // .rpm\n    'application/vnd.rar': 'zip', // .rar – RAR file\n    'application/gzip': 'zip', // .tar.gz — Tarball compressed file\n    'application/x-gzip': 'zip', // .tar.gz — Tarball compressed file\n    'application/x-compress': 'zip', // .z — Z compressed file\n    'application/vnd.apple.installer+xml': 'zip', // .pkg\n\n    'application/msword': 'doc',\n    'application/vnd.openxmlformats-officedocument.wordprocessingml.document': 'doc',\n\n    'application/vnd.ms-powerpoint': 'ppt', // .ppt/.pps\n    'application/vnd.openxmlformats-officedocument.presentationml.presentation': 'ppt',\n\n    'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet': 'xls', // .xlsm - Microsoft Excel file\n    'application/vnd.oasis.opendocument.spreadsheet': 'xls', // .ods — OpenOffice Calc spreadsheet file\n    'application/vnd.oasis.opendocument.presentation': 'ppt', // .ods — OpenOffice Calc presentation file\n\n    'application/xliff+xml': 'xml',\n    'application/xml': 'xml',\n    'text/html': 'xml', // .html/.htm\n    'application/xhtml+xml': 'xml', // .xhtml\n\n    'application/pgp-keys': 'keytrust',\n\n    'application/rtf': 'text',\n    'application/x-tex': 'text',\n    'application/vnd.oasis.opendocument.text': 'text',\n    'application/vnd.wordperfect': 'text',\n\n    'application/vnd.ms-fontobject': 'font',\n    'application/font-sfnt': 'font', // ttf\n    'application/vnd.oasis.opendocument.formula-template': 'font', // otf\n};\n\nconst getIconName = (mimeType: string) => {\n    let name: MimeName = 'unknown';\n\n    if (iconsMap[mimeType]) {\n        name = iconsMap[mimeType];\n    } else if (isImage(mimeType)) {\n        name = 'image';\n    } else if (mimeType === 'text/xml') {\n        // Exception for XML to use it's own icon and not fallback as text\n        name = 'xml';\n    } else if (isICS(mimeType)) {\n        name = 'calendar';\n    } else if (isSupportedText(mimeType)) {\n        name = 'text';\n    } else if (isPDF(mimeType)) {\n        name = 'pdf';\n    } else if (isVideo(mimeType)) {\n        name = 'video';\n    } else if (isFont(mimeType)) {\n        name = 'font';\n    } else if (isExcel(mimeType)) {\n        name = 'xls';\n    }\n\n    return name;\n};\n\ninterface Props extends Omit<MimeIconProps, 'name'> {\n    mimeType: string;\n}\n\n/**\n * Component to render SVG file icons.\n * It's wrapper around MimeIcon component which finds the proper icon\n * name based on the mime type.\n */\nconst FileIcon = ({ mimeType, className, ...rest }: Props) => {\n    const name = getIconName(mimeType);\n\n    return <MimeIcon name={name} className={classnames(['flex-item-noshrink', className])} {...rest} />;\n};\n\nexport default FileIcon;\n","import { HTMLProps, useMemo, useEffect, useRef, useState } from 'react';\nimport { classnames } from '../../helpers';\nimport { Tooltip } from '../tooltip';\n\ninterface Props extends HTMLProps<HTMLSpanElement> {\n    text: string;\n    /**\n     * number of characters you want to keep at the end: 6 will give “blablabla…bla.bla’”\n     */\n    charsToDisplayEnd?: number;\n    className?: string;\n    /**\n     * when you embed it into something with title/tooltip, you might not want to display it\n     */\n    displayTitle?: Boolean;\n    /**\n     * When text is too long, tooltip can be used to show the full text.\n     */\n    displayTooltip?: Boolean;\n    /**\n     * Unless you REALLY know what you are doing (if you're using this component on RTL content ONLY for example)\n     * leave this value to ltr, otherwise you can