row-down-line\" size={20} alt={c('Action').t`Download`} />\n                    </Button>\n                )}\n                {onDetail && (\n                    <Button\n                        icon\n                        shape=\"ghost\"\n                        title={c('Action').t`Details`}\n                        onClick={onDetail}\n                        className=\"ml0-5 no-mobile\"\n                    >\n                        <Icon name=\"info-circle\" size={20} alt={c('Action').t`Details`} />\n                    </Button>\n                )}\n                {onShare && (\n                    <Button\n                        icon\n                        shape=\"ghost\"\n                        title={sharedStatus === '' ? c('Action').t`Share via link` : c('Action').t`Sharing options`}\n                        onClick={onShare}\n                        className=\"ml0-5 no-mobile\"\n                    >\n                        <Icon\n                            name=\"link\"\n                            size={20}\n                            alt={sharedStatus === '' ? c('Action').t`Share via link` : c('Action').t`Sharing options`}\n                            className={SHARED_STATUS_TO_COLOR[sharedStatus || '']}\n                        />\n                    </Button>\n                )}\n                {onClose && (\n                    <Button icon shape=\"ghost\" title={c('Action').t`Close`} onClick={onClose} className=\"ml0-5\">\n                        <Icon name=\"cross\" size={20} alt={c('Action').t`Close`} />\n                    </Button>\n                )}\n            </div>\n        </div>\n    );\n};\n\nexport default Header;\n","import { c } from 'ttag';\nimport Icon from '../../components/icon/Icon';\nimport { Button } from '../../components';\n\ninterface Props {\n    scale: number;\n    onZoomIn: () => void;\n    onZoomOut: () => void;\n    onReset: () => void;\n}\n\nconst ZoomControl = ({ scale, onZoomIn, onZoomOut, onReset }: Props) => {\n    const isZoomOutDisabled = scale <= 0.005;\n    const isZoomInDisabled = scale >= 10;\n\n    return (\n        <div className=\"w100 p2 flex\">\n            <div className=\"center flex flex-align-items-center\">\n                <Button\n                    icon\n                    shape=\"ghost\"\n                    disabled={isZoomOutDisabled}\n                    onClick={onZoomOut}\n                    title={c('Action').t`Zoom out`}\n                >\n                    <Icon name=\"minus\" size={12} alt={c('Action').t`Zoom out`} />\n                </Button>\n                <Button shape=\"ghost\" title={c('Action').t`Reset zoom`} className=\"ml0-5 mr0-5\" onClick={onReset}>\n                    <span>{Math.round(scale * 100)}%</span>\n                </Button>\n                <Button\n                    icon\n                    shape=\"ghost\"\n                    disabled={isZoomInDisabled}\n                    onClick={onZoomIn}\n                    title={c('Action').t`Zoom in`}\n                >\n                    <Icon name=\"plus\" size={12} alt={c('Action').t`Zoom in`} />\n                </Button>\n            </div>\n        </div>\n    );\n};\n\nexport default ZoomControl;\n","import { RefObject, useLayoutEffect, useState } from 'react';\nimport { debounce } from '@proton/shared/lib/helpers/function';\nimport useInstance from './useInstance';\n\n// Can't loop over DOMRect keys with getOwnPropertyNames.\nconst keys = ['bottom', 'height', 'left', 'right', 'top', 'width', 'x', 'y'];\nconst isEquivalent = (aRect?: DOMRect, bRect?: DOMRect) => {\n    if (!aRect && bRect) {\n        return false;\n    }\n    if (aRect && !bRect) {\n        return false;\n    }\n    for (const key of keys) {\n        if (aRect?.[key as keyof DOMRect] !== bRect?.[key as keyof DOMRect]) {\n            return false;\n        }\n    }\n    return true;\n};\n\nconst getElementRect = (target?: HTMLElement | null) => {\n    if (!target) {\n        return;\n    }\n    return target.getBoundingClientRect();\n};\n\ntype RateLimiter = <A extends any[]>(func: (...args: A) => void, wait: number) => (...args: A) => void;\n\nconst equivalentReducer = (oldRect?: DOMRect, newRect?: DOMRect) => {\n    return isEquivalent(oldRect, newRect) ? oldRect : newRect;\n};\nconst defaultReducer = (\n    oldRect: DOMRect | undefined,\n    newRect: DOMRect | undefined,\n    sizeCache: (DOMRect | undefined)[]\n) => {\n    const [prevOld, prevNew] = sizeCache;\n    // If it's flipping back and forth, settle on the previous value to prevent jiggling effects\n    if (isEquivalent(prevOld, newRect) && isEquivalent(prevNew, oldRect)) {\n        return oldRect;\n    }\n    sizeCache[0] = oldRect;\n    sizeCache[1] = newRect;\n    return equivalentReducer(oldRect, newRect);\n};\ntype Reducer = typeof defaultReducer;\n\nconst useElementRect = <E extends HTMLElement>(\n    ref: RefObject<E>,\n    rateLimiter: RateLimiter = debounce,\n    reducer: Reducer = defaultReducer\n) => {\n    const sizeCache = useInstance((): (DOMRect | undefined)[] => []);\n    const [elementRect, setElementRect] = useState(() => getElementRect(ref.current));\n\n    useLayoutEffect(() => {\n        const target = ref.current;\n        if (!target) {\n            return;\n        }\n\n        if (typeof ResizeObserver === 'function') {\n            const resizeObserver = new ResizeObserver(\n                rateLimiter(() => {\n                    setElementRect((old) => reducer(old, getElementRect(target), sizeCache));\n                }, 100)\n            );\n            resizeObserver.observe(target, { box: 'border-box' });\n            setElementRect((old) => reducer(old, getElementRect(target), sizeCache));\n            return () => {\n                resizeObserver.disconnect();\n            };\n        }\n\n        const onResize = rateLimiter(() => {\n            setElementRect((old) => reducer(old, getElementRect(target), sizeCache));\n        }, 100);\n        window.addEventListener('resize', onResize);\n        setElementRect((old) => reducer(old, getElementRect(target), sizeCache));\n        return () => {\n            window.removeEventListener('resize', onResize);\n        };\n    }, [ref.current]);\n\n    return elementRect;\n};\n\nexport default useElementRect;\n","import { c } from 'ttag';\nimport unsupportedPreviewSvg from '@proton/styles/assets/img/errors/preview-unavailable.svg';\nimport corruptedPreviewSvg from '@proton/styles/assets/img/errors/broken-image.svg';\nimport { PrimaryButton } from '../../components';\nimport { useActiveBreakpoint } from '../../hooks';\nimport { classnames } from '../../helpers';\n\ninterface Props {\n    type?: 'file' | 'image' | 'video';\n    onSave?: () => void;\n}\n\nconst UnsupportedPreview = ({ onSave, type = 'file' }: Props) => {\n    const { isNarrow } = useActiveBreakpoint();\n\n    return (\n        <div className=\"absolute-center text-center w100 pl1 pr1\">\n            <img\n                className={classnames(['mb1', isNarrow ? 'w150p' : 'w200p'])}\n                src={type === 'file' ? unsupportedPreviewSvg : corruptedPreviewSvg}\n                alt={c('Info').t`Unsupported file`}\n            />\n\n            <h2 className={classnames(['p0-25 text-bold', isNarrow && 'h3'])}>{c('Info').t`No preview available`}</h2>\n\n            {onSave && (\n                <PrimaryButton size={!isNarrow ? 'large' : undefined} className=\"text-bold\" onClick={onSave}>{c(\n                    'Action'\n                ).t`Download`}</PrimaryButton>\n            )}\n        </div>\n    );\n};\n\nexport default UnsupportedPreview;\n","import DOMPurify from 'dompurify';\nimport { useState, useRef, useEffect } from 'react';\nimport { c } from 'ttag';\n\nimport { uint8ArrayToString, stringToUint8Array } from '@proton/shared/lib/helpers/encoding';\nimport { isSVG } from '@proton/shared/lib/helpers/mimetype';\n\nimport ZoomControl from './ZoomControl';\nimport useElementRect from '../../hooks/useElementRect';\nimport UnsupportedPreview from './UnsupportedPreview';\n\ninterface Props {\n    mimeType: string;\n    onSave?: () => void;\n    contents?: Uint8Array[];\n}\n\nconst FALLBACK_IMAGE_DIMENSION_VALUE = window.innerHeight / 2;\n\n/*\n * Svg image dimension are 0 in Firefox. For these cases fallback values\n * will be used, so the image preview is visible.\n * https://bugzilla.mozilla.org/show_bug.cgi?id=1328124\n */\nfunction getImageNaturalDimensions(imageElement: HTMLImageElement | null) {\n    return {\n        height: imageElement?.naturalHeight || FALLBACK_IMAGE_DIMENSION_VALUE,\n        width: imageElement?.naturalWidth || FALLBACK_IMAGE_DIMENSION_VALUE,\n    };\n}\n\n/**\n * SVG can contain nasty scripts. We do have security headers set but attacker\n * can overcome it by asking user to open the previewed image in the new tab,\n * where browsers don't check headers and allow scripts from the SVG.\n * One option would be to render it as PNG, but zooming or rescaling the window\n * would mean to redraw. Better to keep SVG then. Sanitizing small SVGs takes\n * miliseconds, bigger ones (MBs) under second. Only super huge ones takes even\n * 10 seconds on slow computer as is mine, but we talk about huge SVGs as 30 MB.\n * Because such SVG is more edge case, we can live with that.\n */\nfunction sanitizeSVG(contents: Uint8Array[]): Uint8Array[] {\n    const contentsString = contents.map(uint8ArrayToString).join('');\n    const sanitzedSVG = DOMPurify.sanitize(contentsString);\n    return [stringToUint8Array(sanitzedSVG)];\n}\n\nconst ImagePreview = ({ mimeType, contents, onSave }: Props) => {\n    const imageRef = useRef<HTMLImageElement>(null);\n    const containerRef = useRef<HTMLDivElement>(null);\n    const containerBounds = useElementRect(containerRef);\n    const [error, setError] = useState(false);\n    const [scale, setScale] = useState(0);\n    const [imageData, setImageData] = useState({\n        src: '',\n    });\n\n    useEffect(() => {\n        let src: string;\n\n        if (error) {\n            setError(false);\n        }\n\n        if (!contents) {\n            setImageData({ src: '' });\n            return;\n        }\n\n        const data = isSVG(mimeType) ? sanitizeSVG(contents) : contents;\n        const blob = new Blob(data, { type: mimeType });\n        setImageData({\n            src: URL.createObjectURL(blob),\n        });\n\n        return () => {\n            if (src) {\n                URL.revokeObjectURL(src);\n            }\n        };\n    }, [contents, mimeType]);\n\n    const handleZoomOut = () => setScale((zoom) => (zoom ? zoom * 0.9 : 1));\n    const handleZoomIn = () => setScale((zoom) => (zoom ? zoom * 1.1 : 1));\n    const fitToContainer = () => {\n        if (!imageRef.current || !containerBounds) {\n            return;\n        }\n\n        const dimensions = getImageNaturalDimensions(imageRef.current);\n        const heightRatio = containerBounds.height / dimensions.height;\n        const widthRatio = containerBounds.width / dimensions.width;\n\n        const scale = Math.min(1, heightRatio, widthRatio);\n\n        setScale(scale);\n    };\n\n    const handleBrokenImage = () => {\n        if (!error) {\n            setError(true);\n        }\n    };\n\n    const dimensions = getImageNaturalDimensions(imageRef.current);\n    const scaledDimensions = {\n        height: dimensions.height * scale,\n        width: dimensions.width * scale,\n    };\n\n    return (\n        <>\n            <div ref={containerRef} className=\"file-preview-container\">\n                {error ? (\n                    <UnsupportedPreview onSave={onSave} type=\"image\" />\n                ) : (\n                    imageData.src && (\n                        <div className=\"flex-no-min-children mauto relative\" style={scaledDimensions}>\n                            <img\n                                ref={imageRef}\n                                onLoad={() => fitToContainer()}\n                                onError={handleBrokenImage}\n                                className=\"file-preview-image\"\n                                style={scaledDimensions}\n                                src={imageData.src}\n                                alt={c('Info').t`Preview`}\n                            />\n                        </div>\n                    )\n                )}\n            </div>\n            {!error && (\n                <ZoomControl onReset={fitToContainer} scale={scale} onZoomIn={handleZoomIn} onZoomOut={handleZoomOut} />\n            )}\n        </>\n    );\n};\n\nexport default ImagePreview;\n","import { c } from 'ttag';\nimport { TextLoader, CircleLoader } from '../../components';\n\nconst PreviewLoader = () => {\n    return (\n        <div className=\"file-preview-container\">\n            <div className=\"absolute-center text-center w100\">\n                <CircleLoader size=\"large\" />\n                <TextLoader>{c('Info').t`Loading preview`}</TextLoader>\n            </div>\n        </div>\n    );\n};\n\nexport default PreviewLoader;\n","import { mergeUint8Arrays } from '@proton/shared/lib/helpers/array';\n\ninterface Props {\n    contents?: Uint8Array[];\n}\n\nconst TextPreview = ({ contents = [] }: Props) => {\n    const string = new TextDecoder().decode(mergeUint8Arrays(contents));\n\n    return (\n        <div className=\"file-preview-container\">\n            <div className=\"file-preview-text\">{string}</div>\n        </div>\n    );\n};\n\nexport default TextPreview;\n","import { useState, useEffect, useRef } from 'react';\n\nimport useElementRect from '../../hooks/useElementRect';\nimport UnsupportedPreview from './UnsupportedPreview';\n\ninterface Props {\n    mimeType: string;\n    contents?: Uint8Array[];\n    onSave?: () => void;\n}\n\nconst VideoPreview = ({ contents, mimeType, onSave }: Props) => {\n    const videoRef = useRef<HTMLVideoElement>(null);\n    const containerRef = useRef<HTMLDivElement>(null);\n    const containerBounds = useElementRect(containerRef);\n    const [url, setUrl] = useState<string>();\n    const [scale, setScale] = useState(1);\n    const [error, setError] = useState(false);\n\n    useEffect(() => {\n        const newUrl = URL.createObjectURL(new Blob(contents, { type: mimeType }));\n        setUrl(newUrl);\n        return () => {\n            if (newUrl) {\n                URL.revokeObjectURL(newUrl);\n            }\n        };\n    }, [contents]);\n\n    const fitToContainer = () => {\n        if (!videoRef.current || !containerBounds) {\n            return;\n        }\n\n        const heightRatio = containerBounds.height / videoRef.current.videoHeight;\n        const widthRatio = containerBounds.width / videoRef.current.videoWidth;\n        const scale = Math.min(1, heightRatio, widthRatio);\n        setScale(scale);\n    };\n\n    const handleBrokenVideo = () => {\n        setError(true);\n    };\n\n    const scaledDimensions = !videoRef.current?.videoHeight\n        ? {}\n        : {\n              height: videoRef.current.videoHeight * scale,\n              width: videoRef.current.videoWidth * scale,\n          };\n\n    if (error) {\n        return (\n            <div className=\"flex flex-item-fluid-auto relative\">\n                <UnsupportedPreview onSave={onSave} type=\"video\" />\n            </div>\n        );\n    }\n    return (\n        <div ref={containerRef} className=\"flex w100 h100\">\n            <div className=\"mauto\">\n                {/* eslint-disable-next-line */}\n                <video\n                    ref={videoRef}\n                    onLoadedMetadata={fitToContainer}\n                    onError={handleBrokenVideo}\n                    src={url}\n                    style={scaledDimensions}\n                    controls\n                />\n            </div>\n        </div>\n    );\n};\n\nexport default VideoPreview;\n","import { useState, useEffect } from 'react';\nimport { c } from 'ttag';\n\ninterface Props {\n    filename?: string;\n    contents?: Uint8Array[];\n}\nconst PDFPreview = ({ filename = 'preview.pdf', contents }: Props) => {\n    const [url, setUrl] = useState<string>();\n\n    useEffect(() => {\n        const newUrl = URL.createObjectURL(new Blob(contents, { type: 'application/pdf' }));\n        setUrl(newUrl);\n        return () => {\n            if (newUrl) {\n                URL.revokeObjectURL(newUrl);\n            }\n        };\n    }, [contents]);\n\n    return (\n        <>\n            {url && (\n                <object\n                    data={url}\n                    className=\"w100 flex-no-min-children flex-item-fluid-auto flex-column-reverse\"\n                    type=\"application/pdf\"\n                    title={filename}\n                >\n                    <embed src={url} className=\"flex\" type=\"application/pdf\" />\n                    <p className=\"mauto\">{c('Info')\n                        .t`This browser does not support previewing PDF documents. Please download the file.`}</p>\n                </object>\n            )}\n        </>\n    );\n};\n\nexport default PDFPreview;\n","import { ReactNode } from 'react';\nimport { c } from 'ttag';\n\nimport { classnames } from '../../helpers';\nimport { useActiveBreakpoint } from '../../hooks';\nimport { PrimaryButton, Icon } from '../../components';\n\nconst SignatureIssue = ({\n    signatureConfirmation,\n    onClick,\n}: {\n    signatureConfirmation: ReactNode;\n    onClick: () => void;\n}) => {\n    const { isNarrow } = useActiveBreakpoint();\n\n    return (\n        <div className=\"file-preview-container\">\n            <div className=\"absolute-center w100\">\n                <div className={classnames(['mlauto mrauto', isNarrow ? 'w300p' : 'w500p'])}>\n                    <div className=\"text-center\">\n                        <Icon name=\"lock-exclamation-filled\" size={60} className=\"color-danger\" />\n                    </div>\n                    <div className=\"mt1 mb2\">{signatureConfirmation}</div>\n                </div>\n                <div className=\"text-center\">\n                    <PrimaryButton size={!isNarrow ? 'large' : undefined} className=\"text-bold\" onClick={onClick}>\n                        {c('Action').t`Show preview`}\n                    </PrimaryButton>\n                </div>\n            </div>\n        </div>\n    );\n};\n\nexport default SignatureIssue;\n","import { isPreviewAvailable } from '@proton/shared/lib/helpers/preview';\nimport { forwardRef, ReactNode, Ref, useRef, useState } from 'react';\nimport { isSupportedImage, isSupportedVideo, isSupportedText, isPDF } from '@proton/shared/lib/helpers/mimetype';\nimport Header, { SharedStatus } from './Header';\nimport ImagePreview from './ImagePreview';\nimport PreviewLoader from './PreviewLoader';\nimport TextPreview from './TextPreview';\nimport VideoPreview from './VideoPreview';\nimport UnsupportedPreview from './UnsupportedPreview';\nimport PDFPreview from './PDFPreview';\nimport SignatureIssue from './SignatureIssue';\nimport { useCombinedRefs, useHotkeys } from '../../hooks';\nimport { useFocusTrap } from '../../components';\n\ninterface Props {\n    loading: boolean;\n    fileName?: string;\n    mimeType?: string;\n    fileSize?: number;\n    navigationControls?: ReactNode;\n    contents?: Uint8Array[];\n    sharedStatus?: SharedStatus;\n    signatureStatus?: ReactNode;\n    signatureConfirmation?: ReactNode;\n    onClose?: () => void;\n    onSave?: () => void;\n    onDetail?: () => void;\n    onShare?: () => void;\n}\n\nconst FilePreview = (\n    {\n        contents,\n        fileName,\n        mimeType,\n        fileSize,\n        loading,\n        navigationControls,\n        sharedStatus,\n        signatureStatus,\n        signatureConfirmation,\n        onClose,\n        onSave,\n        onDetail,\n        onShare,\n    }: Props,\n    ref: Ref<HTMLDivElement>\n) => {\n    const rootRef = useRef<HTMLDivElement>(null);\n    const combinedRefs = useCombinedRefs<HTMLDivElement>(ref, rootRef);\n    const focusTrapProps = useFocusTrap({\n        rootRef,\n    });\n    const [forcePreview, setForcePreview] = useState(false);\n\n    useHotkeys(rootRef, [\n        [\n            'Escape',\n            (e) => {\n                e.stopPropagation();\n                onClose?.();\n            },\n        ],\n    ]);\n\n    const renderPreview = () => {\n        if (signatureConfirmation && !forcePreview) {\n            return (\n                <SignatureIssue signatureConfirmation={signatureConfirmation} onClick={() => setForcePreview(true)} />\n            );\n        }\n\n        if (!contents || !mimeType || !isPreviewAvailable(mimeType, fileSize)) {\n            return (\n                <div className=\"file-preview-container\">\n                    <UnsupportedPreview onSave={onSave} />\n                </div>\n            );\n        }\n\n        if (isSupportedImage(mimeType)) {\n            return <ImagePreview contents={contents} mimeType={mimeType} onSave={onSave} />;\n        }\n        if (isSupportedVideo(mimeType, fileSize)) {\n            return <VideoPreview contents={contents} mimeType={mimeType} onSave={onSave} />;\n        }\n        if (isSupportedText(mimeType)) {\n            return <TextPreview contents={contents} />;\n        }\n        if (isPDF(mimeType)) {\n            return <PDFPreview contents={contents} filename={fileName} />;\n        }\n    };\n\n    return (\n        <div className=\"file-preview ui-prominent\" ref={combinedRefs} {...focusTrapProps}>\n            <Header\n                mimeType={mimeType}\n                name={fileName}\n                sharedStatus={sharedStatus}\n                signatureStatus={signatureStatus}\n                onClose={onClose}\n                onSave={onSave}\n                onDetail={onDetail}\n                onShare={onShare}\n            >\n                {navigationControls}\n            </Header>\n            {loading ? <PreviewLoader /> : renderPreview()}\n        </div>\n    );\n};\n\nexport default forwardRef(FilePreview);\n","// Will include more rules in the future\nimport { hasPDFSupport } from './browser';\nimport { isPDF, isSupportedImage, isSupportedText, isSupportedVideo } from './mimetype';\n\nexport const isPreviewAvailable = (mimeType: string, fileSize?: number) =>\n    isSupportedImage(mimeType) ||\n    isSupportedVideo(mimeType, fileSize) ||\n    isSupportedText(mimeType) ||\n    (hasPDFSupport() && isPDF(mimeType));\n","import { RefObject } from 'react';\nimport { c } from 'ttag';\nimport Icon from '../../components/icon/Icon';\nimport { Button } from '../../components';\nimport { useHotkeys } from '../../hooks';\n\ninterface Props {\n    current: number;\n    total: number;\n    rootRef: RefObject<HTMLDivElement>;\n    onNext: () => void;\n    onPrev: () => void;\n}\n\nconst NavigationControl = ({ current, total, rootRef, onNext, onPrev }: Props) => {\n    const isPrevDisabled = current === 1;\n    const isNextDisabled = current === total;\n\n    useHotkeys(rootRef, [\n        [\n            'ArrowLeft',\n            (e) => {\n                e.stopPropagation();\n                if (!isPrevDisabled) {\n                    onPrev();\n                }\n            },\n        ],\n        [\n            'ArrowRight',\n            (e) => {\n                e.stopPropagation();\n                if (!isNextDisabled) {\n                    onNext();\n                }\n            },\n        ],\n    ]);\n\n    return (\n        <div className=\"flex flex-align-items-center absolute-center\">\n            <Button\n                icon\n                shape=\"ghost\"\n                className=\"on-rtl-mirror\"\n                disabled={isPrevDisabled}\n                onClick={onPrev}\n                title={c('Action').t`Previous`}\n            >\n                <Icon name=\"chevron-left\" size={16} alt={c('Action').t`Previous`} />\n            </Button>\n            <span className=\"ml0-5 mr0-5\">\n                <span>{current}</span>\n                <span className=\"ml0-25 mr0-25 color-weak text-sm\">{c('Info').t`of`}</span>\n                <span>{total}</span>\n            </span>\n            <Button\n                icon\n                shape=\"ghost\"\n                className=\"on-rtl-mirror\"\n                disabled={isNextDisabled}\n                onClick={onNext}\n                title={c('Action').t`Next`}\n            >\n                <Icon name=\"chevron-right\" size={16} alt={c('Action').t`Next`} />\n            </Button>\n        </div>\n    );\n};\n\nexport default NavigationControl;\n","import { useImperativeHandle, forwardRef, Ref, useState, useRef } from 'react';\n\nimport { getInvoice } from '@proton/shared/lib/api/payments';\n\nimport { useApi } from '../../hooks';\nimport { FilePreview, NavigationControl } from '../filePreview';\nimport { Invoice } from './interface';\n\ninterface InvoicesPreviewControls {\n    preview: (invoice: Invoice) => void;\n}\n\ninterface Preview {\n    invoice: Invoice;\n    contents?: Uint8Array[];\n}\n\ninterface Props {\n    invoices: Invoice[];\n    onDownload: (invoice: Invoice) => void;\n    getFilename: (invoice: Invoice) => string;\n}\n\nconst InvoicesPreview = (\n    { invoices, onDownload, getFilename }: Props,\n    ref: Ref<InvoicesPreviewControls | undefined>\n) => {\n    const api = useApi();\n    const [previewing, setPreviewing] = useState<Preview>();\n\n    const rootRef = useRef<HTMLDivElement>(null);\n\n    const handlePreview = async (invoice: Invoice) => {\n        setPreviewing({ invoice });\n        const buffer = await api<Uint8Array>(getInvoice(invoice.ID));\n        setPreviewing((previewing) => {\n            // Preview can be closed or changed during download;\n            if (previewing === undefined || previewing.invoice !== invoice) {\n                return previewing;\n            }\n\n            return {\n                ...previewing,\n                contents: [buffer],\n            };\n        });\n    };\n\n    useImperativeHandle(ref, () => ({\n        preview: handlePreview,\n    }));\n\n    if (!previewing) {\n        return null;\n    }\n\n    const current = invoices.findIndex((invoice) => invoice === previewing.invoice) + 1;\n    const total = invoices.length;\n\n    const handleNext = () => handlePreview(invoices[current]);\n    const handlePrevious = () => handlePreview(invoices[current - 2]);\n    const handleClose = () => setPreviewing(undefined);\n\n    const handleDownload = () => {\n        if (!previewing.invoice) {\n            return;\n        }\n        onDownload(previewing.invoice);\n    };\n\n    const filename = () => {\n        if (!previewing.invoice) {\n            return;\n        }\n        return getFilename(previewing.invoice);\n    };\n\n    return (\n        <FilePreview\n            loading={!previewing.contents}\n            contents={previewing.contents}\n            fileName={filename()}\n            fileSize={previewing.contents?.length}\n            mimeType=\"application/pdf\"\n            onClose={handleClose}\n            onSave={handleDownload}\n            ref={rootRef}\n            navigationControls={\n                <NavigationControl\n                    current={current}\n                    total={total}\n                    rootRef={rootRef}\n                    onNext={handleNext}\n                    onPrev={handlePrevious}\n                />\n            }\n        />\n    );\n};\n\nexport default forwardRef(InvoicesPreview);\n","import { useState, useRef } from 'react';\nimport { c } from 'ttag';\n\nimport { queryInvoices, getInvoice } from '@proton/shared/lib/api/payments';\nimport { ELEMENTS_PER_PAGE, INVOICE_OWNER, INVOICE_STATE, MAIL_APP_NAME } from '@proton/shared/lib/constants';\nimport downloadFile from '@proton/shared/lib/helpers/downloadFile';\n\nimport {\n    Alert,\n    ButtonGroup,\n    Block,\n    Button,\n    Table,\n    TableCell,\n    TableBody,\n    Pagination,\n    usePaginationAsync,\n    TableRow,\n    Time,\n    TableHeader,\n} from '../../components';\nimport { useModals, useSubscription, useUser, useApi } from '../../hooks';\n\nimport MozillaInfoPanel from '../account/MozillaInfoPanel';\nimport useApiResult from '../../hooks/useApiResult';\n\nimport InvoiceAmount from './InvoiceAmount';\nimport InvoiceType from './InvoiceType';\nimport InvoiceState from './InvoiceState';\nimport InvoiceActions from './InvoiceActions';\nimport InvoiceTextModal from './InvoiceTextModal';\nimport InvoicesPreview from './InvoicesPreview';\n\nimport { SettingsParagraph, SettingsSectionWide } from '../account';\n\nconst InvoicesSection = () => {\n    const previewRef = useRef();\n    const api = useApi();\n    const [user] = useUser();\n    const { ORGANIZATION, USER } = INVOICE_OWNER;\n    const [owner, setOwner] = useState(USER);\n    const [{ isManagedByMozilla } = {}] = useSubscription();\n    const { createModal } = useModals();\n    const { page, onNext, onPrevious, onSelect } = usePaginationAsync(1);\n\n    const handleOwner =\n        (own = USER) =>\n        () => {\n            setOwner(own);\n            onSelect(1);\n        };\n\n    const query = () =>\n        queryInvoices({\n            Page: page - 1,\n            PageSize: ELEMENTS_PER_PAGE,\n            Owner: owner,\n        });\n\n    const { result = {}, loading, request } = useApiResult(query, [page, owner]);\n    const { Invoices: invoices = [], Total: total = 0 } = result;\n    const hasUnpaid = invoices.find(({ State }) => State === INVOICE_STATE.UNPAID);\n\n    if (isManagedByMozilla) {\n        return <MozillaInfoPanel />;\n    }\n\n    const handleOpenModal = () => {\n        createModal(<InvoiceTextModal />);\n    };\n\n    const getFilename = (invoice) => `${c('Title for PDF file').t`${MAIL_APP_NAME} invoice`} ${invoice.ID}.pdf`;\n\n    const handleDownload = async (invoice) => {\n        const buffer = await api(getInvoice(invoice.ID));\n        const blob = new Blob([buffer], { type: 'application/pdf' });\n        downloadFile(blob, getFilename(invoice));\n    };\n\n    const isEmpty = page === 1 && !loading && invoices.length === 0;\n\n    return (\n        <>\n            <SettingsSectionWide>\n                <SettingsParagraph>{c('Info')\n                    .t`You can customize and download your invoices for accounting purposes.`}</SettingsParagraph>\n                {hasUnpaid ? (\n                    <Alert className=\"mb1\" type=\"error\">\n                        {c('Error')\n                            .t`Your account or organization has an overdue invoice. Please pay all unpaid invoices.`}\n                    </Alert>\n                ) : null}\n                <Block className=\"flex flex-justify-space-between\">\n                    <div className=\"flex flex-align-items-center\">\n                        {user.isPaid ? (\n                            <ButtonGroup className=\"mr1\">\n                                <Button className={owner === USER ? 'is-selected' : ''} onClick={handleOwner(USER)}>\n                                    {c('Action').t`User`}\n                                </Button>\n                                <Button\n                                    className={owner === ORGANIZATION ? 'is-selected' : ''}\n                                    onClick={handleOwner(ORGANIZATION)}\n                                >\n                                    {c('Action').t`Organization`}\n                                </Button>\n                            </ButtonGroup>\n                        ) : null}\n                        <Button onClick={handleOpenModal}>{c('Action').t`Customize`}</Button>\n                    </div>\n                    <Pagination\n                        page={page}\n                        total={total}\n                        limit={ELEMENTS_PER_PAGE}\n                        onNext={onNext}\n                        onPrevious={onPrevious}\n                        onSelect={onSelect}\n                    />\n                </Block>\n                {isEmpty ? (\n                    c('Error').t`You have no invoices.`\n                ) : (\n                    <div style={{ overflow: 'auto' }}>\n                        <Table className=\"simple-table--has-actions\">\n                            <TableHeader>\n                                <TableRow>\n                                    <TableCell type=\"header\">ID</TableCell>\n                                    <TableCell type=\"header\">{c('Title').t`Amount`}</TableCell>\n                                    <TableCell type=\"header\">{c('Title').t`Type`}</TableCell>\n                                    <TableCell type=\"header\">{c('Title').t`Status`}</TableCell>\n                                    <TableCell type=\"header\">{c('Title').t`Date`}</TableCell>\n                                    <TableCell type=\"header\">{c('Title').t`Action`}</TableCell>\n                                </TableRow>\n                            </TableHeader>\n                            <TableBody loading={loading} colSpan={6}>\n                                {invoices.map((invoice, index) => {\n                                    const key = index.toString();\n                                    return (\n                                        <TableRow\n                                            key={key}\n                                            cells={[\n                                                invoice.ID,\n                                                <InvoiceAmount key={key} invoice={invoice} />,\n                                                <InvoiceType key={key} invoice={invoice} />,\n                                                <InvoiceState key={key} invoice={invoice} />,\n                                                <Time key={key}>{invoice.CreateTime}</Time>,\n                                                <InvoiceActions\n                                                    key={key}\n                                                    invoice={invoice}\n                                                    fetchInvoices={request}\n                                                    onPreview={previewRef.current.preview}\n                                                    onDownload={handleDownload}\n                                                />,\n                                            ]}\n                                        />\n                                    );\n                                })}\n                            </TableBody>\n                        </Table>\n                    </div>\n                )}\n            </SettingsSectionWide>\n            <InvoicesPreview\n                ref={previewRef}\n                invoices={invoices}\n                onDownload={handleDownload}\n                getFilename={getFilename}\n            />\n        </>\n    );\n};\n\nexport default InvoicesSection;\n","import React, { useEffect, useState, useRef, MutableRefObject, useImperativeHandle } from 'react';\nimport { c } from 'ttag';\nimport { getApiSubdomainUrl } from '@proton/shared/lib/helpers/url';\nimport * as localStorageWrapper from '@proton/shared/lib/helpers/storage';\nimport * as sessionStorageWrapper from '@proton/shared/lib/helpers/sessionStorage';\nimport { addHours } from 'date-fns';\nimport { UserModel } from '@proton/shared/lib/interfaces';\n\nimport { useNotifications } from '../../hooks';\n\n// The sizes for these are hardcoded since the widget calculates it based on the viewport, and since it's in\n// an iframe it needs to have something reasonable.\n// The main chat widget.\nconst OPENED_SIZE = {\n    height: `${572 / 16}rem`,\n    width: `${374 / 16}rem`,\n};\n// The small button to toggle the chat.\nconst CLOSED_SIZE = {\n    height: `${70 / 16}rem`,\n    width: `${140 / 16}rem`,\n};\n\nconst SINGLE_CHAT_KEY = 'zk_state';\nconst SINGLE_CHAT_TIMEOUT = 10000;\n\nconst getIframeUrl = (zendeskKey: string) => {\n    const url = getApiSubdomainUrl('/core/v4/resources/zendesk');\n    url.searchParams.set('Key', zendeskKey);\n    return url;\n};\n\nexport const getIsSelfChat = () => {\n    return sessionStorageWrapper.getItem(SINGLE_CHAT_KEY);\n};\nconst removeSelfActiveMarker = () => {\n    return sessionStorageWrapper.removeItem(SINGLE_CHAT_KEY);\n};\nconst getIsActiveInAnotherWindow = () => {\n    return !getIsSelfChat() && +(localStorageWrapper.getItem(SINGLE_CHAT_KEY) || 0) > Date.now();\n};\nconst setActiveMarker = () => {\n    localStorageWrapper.setItem(SINGLE_CHAT_KEY, `${+Date.now() + SINGLE_CHAT_TIMEOUT}`);\n    sessionStorageWrapper.setItem(SINGLE_CHAT_KEY, '1');\n};\n\nconst clearPaidMarkers = () => {\n    if (!localStorageWrapper.hasStorage()) {\n        return;\n    }\n    for (let i = 0; i < localStorage.length; i++) {\n        const key = localStorage.key(i);\n        if (key?.startsWith('LiveChat')) {\n            if (+(localStorage.getItem(key) || 0) < Date.now()) {\n                localStorage.removeItem(key);\n            }\n        }\n    }\n};\nconst setPaidMarker = (userID: string) => {\n    return localStorageWrapper.setItem(`LiveChat-${userID}`, addHours(new Date(), 24).getTime().toString());\n};\nconst getPaidMarker = (userID: string) => {\n    return +(localStorageWrapper.getItem(`LiveChat-${userID}`) || 0);\n};\n\nexport const useCanEnableChat = (user: UserModel) => {\n    const hasCachedChat = getPaidMarker(user.ID) > Date.now();\n    const canEnableChat = user.hasPaidVpn || hasCachedChat;\n\n    useEffect(() => {\n        clearPaidMarkers();\n        if (!user.hasPaidVpn) {\n            return;\n        }\n        const setMarker = () => {\n            // Clear old items\n            clearPaidMarkers();\n            // Enable the user to access chat 24 hours after in case she unsubscribes\n            setPaidMarker(user.ID);\n        };\n        setMarker();\n        const handle = window.setInterval(setMarker, 60000);\n        return () => window.clearInterval(handle);\n    }, [user.hasPaidVpn]);\n\n    return canEnableChat;\n};\n\nexport interface ZendeskRef {\n    run: (data: object) => void;\n    toggle: () => void;\n}\n\ninterface Props {\n    zendeskKey: string;\n    zendeskRef?: MutableRefObject<ZendeskRef | undefined>;\n    name?: string;\n    email?: string;\n    onLoaded: () => void;\n    onUnavailable: () => void;\n    locale: string;\n    tags: string[];\n}\n\nconst LiveChatZendesk = ({ zendeskKey, zendeskRef, name, email, onLoaded, onUnavailable, locale, tags }: Props) => {\n    const [style, setStyle] = useState({\n        position: 'absolute',\n        bottom: 0,\n        right: 0,\n        maxHeight: '100%',\n        maxWidth: '100%',\n        zIndex: '999999',\n        ...CLOSED_SIZE,\n    });\n    const [state, setState] = useState({ loaded: false, connected: false });\n    const stateRef = useRef({ loaded: false, connected: false });\n    const iframeRef = useRef<HTMLIFrameElement>(null);\n    const pendingLoadingRef = useRef<{ toggle?: boolean; locale?: string }>({});\n\n    const iframeUrl = getIframeUrl(zendeskKey);\n\n    const src = iframeUrl.toString();\n    const targetOrigin = iframeUrl.origin;\n\n    const handleRun = (args: any) => {\n        const contentWindow = iframeRef.current?.contentWindow;\n        if (!contentWindow || !stateRef.current.loaded) {\n            return;\n        }\n        contentWindow.postMessage({ args }, targetOrigin);\n    };\n\n    const handleToggle = () => {\n        // Using the ref instead of state to not have to wait for re-render\n        if (!stateRef.current.connected) {\n            onUnavailable();\n            return;\n        }\n        pendingLoadingRef.current.toggle = true;\n        handleRun(['webWidget', 'toggle']);\n    };\n\n    useImperativeHandle(zendeskRef, () => ({\n        run: handleRun,\n        toggle: handleToggle,\n    }));\n\n    useEffect(() => {\n        if (!state.loaded) {\n            return;\n        }\n        handleRun([\n            'webWidget',\n            'prefill',\n            {\n                name: { value: name, readOnly: true },\n                email: { value: email, readOnly: Boolean(email) },\n            },\n        ]);\n    }, [state.loaded, name, email]);\n\n    useEffect(() => {\n        if (!state.loaded) {\n            return;\n        }\n        handleRun(['webWidget', 'setLocale', locale]);\n    }, [state.loaded, locale]);\n\n    useEffect(() => {\n        if (!state.loaded || !tags.length) {\n            return;\n        }\n        handleRun(['webWidget', 'chat:addTags', tags]);\n        return () => {\n            handleRun(['webWidget', 'chat:removeTags', tags]);\n        };\n    }, [state.loaded, tags]);\n\n    useEffect(() => {\n        if (!state.loaded || !pendingLoadingRef.current) {\n            return;\n        }\n        const oldPending = pendingLoadingRef.current;\n        pendingLoadingRef.current = {};\n        if (oldPending.toggle) {\n            handleToggle();\n        }\n    }, [state.loaded]);\n\n    useEffect(() => {\n        let globalId = 1;\n        const handlers: { [key: string]: [(value: any) => void, (reason?: any) => void, number] } = {};\n\n        const sendMessage = (contentWindow: Window, args: any) => {\n            contentWindow.postMessage({ args }, targetOrigin);\n        };\n\n        const sendMessageWithReply = <T,>(contentWindow: Window, args: any): Promise<T> => {\n            const id = globalId++;\n            contentWindow.postMessage({ id, args }, targetOrigin);\n            return new Promise((resolve, reject) => {\n                const intervalId = window.setTimeout(() => {\n                    delete handlers[id];\n                }, 30000);\n                handlers[id] = [resolve, reject, intervalId];\n            });\n        };\n\n        const handleMessage = (event: MessageEvent) => {\n            const contentWindow = iframeRef.current?.contentWindow;\n            const { origin, data, source } = event;\n            if (!contentWindow || origin !== targetOrigin || !data || source !== contentWindow) {\n                return;\n            }\n\n            const departmentName = 'Support';\n\n            if (data.type === 'on') {\n                if (data.payload?.event === 'open') {\n                    setStyle((oldStyle) => ({ ...oldStyle, ...OPENED_SIZE }));\n                }\n\n                if (data.payload?.event === 'close') {\n                    setStyle((oldStyle) => ({ ...oldStyle, ...CLOSED_SIZE }));\n                }\n\n                if (data.payload?.event === 'chat:connected') {\n                    sendMessage(contentWindow, [\n                        'webWidget',\n                        'updateSettings',\n                        {\n                            webWidget: {\n                                chat: {\n                                    departments: {\n                                        enabled: [departmentName],\n                                        select: departmentName,\n                                    },\n                                },\n                            },\n                        },\n                    ]);\n\n                    sendMessageWithReply<any>(contentWindow, ['webWidget:get', 'chat:department', departmentName])\n                        .then((result) => {\n                            const connected = result?.status === 'online';\n                            stateRef.current = { loaded: true, connected };\n                            setState({ loaded: true, connected });\n                            onLoaded();\n                        })\n                        .catch(() => {\n                            stateRef.current = { loaded: true, connected: false };\n                            setState({ loaded: true, connected: false });\n                            onLoaded();\n                        });\n                }\n\n                if (data.payload?.event === 'chat:departmentStatus') {\n                    const { chatDepartment } = data.payload;\n                    if (!chatDepartment) {\n                        return;\n                    }\n                    const connected = chatDepartment?.status === 'online';\n                    stateRef.current = { loaded: true, connected };\n                    setState({ loaded: true, connected });\n                }\n            }\n\n            if (data.type === 'response') {\n                if (data.payload.id !== undefined) {\n                    const handler = handlers[data.payload.id];\n                    if (handler) {\n                        delete handlers[data.payload.id];\n                        handler[0](data.payload.result);\n                    }\n                }\n            }\n\n            if (data.type === 'loaded') {\n                sendMessage(contentWindow, [\n                    'webWidget',\n                    'updateSettings',\n                    { webWidget: { color: { theme: '#02811A' } } },\n                ]);\n            }\n        };\n\n        window.addEventListener('message', handleMessage, false);\n\n        return () => {\n            window.removeEventListener('message', handleMessage, false);\n\n            for (const handlerKey of Object.keys(handlers)) {\n                const handler = handlers[handlerKey];\n                handler[1](new Error('Unmount'));\n                window.clearTimeout(handler[2]);\n                delete handlers[handlerKey];\n            }\n        };\n    }, []);\n\n    return (\n        <div className={!state.connected ? 'hidden' : ''}>\n            <iframe\n                title=\"Zendesk\"\n                src={src}\n                style={style}\n                ref={iframeRef}\n                sandbox=\"allow-scripts allow-same-origin allow-popups allow-forms\"\n            />\n        </div>\n    );\n};\n\nconst LiveChatZendeskSingleton = ({ zendeskRef, ...rest }: Props) => {\n    const { createNotification } = useNotifications();\n    const [isActive, setIsActive] = useState(() => !getIsActiveInAnotherWindow());\n    const actualZendeskRef = useRef<ZendeskRef>();\n\n    useEffect(() => {\n        const interval = window.setInterval(() => {\n            if (getIsActiveInAnotherWindow()) {\n                return;\n            }\n            setIsActive(true);\n            setActiveMarker();\n        }, SINGLE_CHAT_TIMEOUT / 2);\n\n        return () => {\n            clearInterval(interval);\n            removeSelfActiveMarker();\n        };\n    }, []);\n\n    useImperativeHandle(zendeskRef, () => ({\n        run: (...args) => actualZendeskRef.current?.run(...args),\n        toggle: (...args) => {\n            if (getIsActiveInAnotherWindow()) {\n                createNotification({\n                    text: c('Info')\n                        .t`You can only have one chat instance open at a time. Please close previous conversations before starting a new one.`,\n                    type: 'error',\n                });\n                return;\n            }\n            actualZendeskRef.current?.toggle(...args);\n        },\n    }));\n\n    useEffect(() => {\n        if (!isActive) {\n            rest.onLoaded();\n        }\n    }, []);\n\n    if (!isActive) {\n        return null;\n    }\n\n    return <LiveChatZendesk zendeskRef={actualZendeskRef} {...rest} />;\n};\n\nexport default LiveChatZendeskSingleton;\n","import { useState } from 'react';\nimport { c } from 'ttag';\nimport markdownit from 'markdown-it';\n\nimport { getAppVersion } from '../../helpers';\nimport {\n    ModalProps,\n    ModalTwo as Modal,\n    ModalTwoHeader as ModalHeader,\n    ModalTwoContent as ModalContent,\n    ModalTwoFooter as ModalFooter,\n} from '../modalTwo';\nimport { Button } from '../button';\n\nimport './ChangeLogModal.scss';\n\nconst md = markdownit('default', {\n    breaks: true,\n    linkify: true,\n});\n\nconst defaultRender =\n    md.renderer.rules.link_open ||\n    function render(tokens, idx, options, env, self) {\n        return self.renderToken(tokens, idx, options);\n    };\n\nmd.renderer.rules.link_open = (tokens, idx, options, env, self) => {\n    tokens[idx].attrPush(['target', '_blank']);\n    return defaultRender(tokens, idx, options, env, self);\n};\n\ninterface Props extends ModalProps {\n    changelog?: string;\n}\n\nconst ChangelogModal = ({ changelog = '', ...rest }: Props) => {\n    const [html] = useState(() => {\n        const modifiedChangelog = changelog.replace(/\\[(\\d+\\.\\d+\\.\\d+[^\\]]*)]/g, (match, capture) => {\n            return `[${getAppVersion(capture)}]`;\n        });\n        return {\n            __html: md.render(modifiedChangelog),\n        };\n    });\n\n    return (\n        <Modal size=\"large\" {...rest}>\n            <ModalHeader title={c('Title').t`What's new`} />\n            <ModalContent>\n                <div className=\"modal-content-inner-changelog\" dangerouslySetInnerHTML={html} dir=\"ltr\" lang=\"en\" />\n            </ModalContent>\n            <ModalFooter>\n                <Button onClick={rest.onClose}>{c('Action').t`Close`}</Button>\n            </ModalFooter>\n        </Modal>\n    );\n};\n\nexport default ChangelogModal;\n","import { c } from 'ttag';\n\nimport { APPS_CONFIGURATION } from '@proton/shared/lib/constants';\n\nimport { useConfig, useEarlyAccess } from '../../hooks';\nimport ChangelogModal from './ChangelogModal';\nimport { getAppVersion } from '../../helpers';\nimport { Tooltip } from '../tooltip';\nimport { useModalState } from '../modalTwo';\n\ninterface Props {\n    appName?: string;\n    appVersion?: string;\n    changelog?: string;\n}\n\nconst envMap = {\n    alpha: 'α',\n    beta: 'β',\n    relaunch: 'δ',\n};\n\nconst AppVersion = ({ appVersion: maybeAppVersion, appName: maybeAppName, changelog }: Props) => {\n    const { APP_NAME, APP_VERSION, DATE_VERSION } = useConfig();\n    const { currentEnvironment } = useEarlyAccess();\n    const [changelogModal, setChangelogModalOpen, render] = useModalState();\n\n    const appName = maybeAppName || APPS_CONFIGURATION[APP_NAME]?.name;\n    const appVersion = getAppVersion(maybeAppVersion || APP_VERSION);\n    const className = 'app-infos-version text-xs m0';\n    const title = DATE_VERSION;\n    const children = (\n        <>\n            <span className=\"app-infos-name mr0-25\">{appName}</span>\n            <span className=\"app-infos-number\">\n                {appVersion}\n                {currentEnvironment && envMap[currentEnvironment] && ` ${envMap[currentEnvironment]}`}\n            </span>\n        </>\n    );\n\n    if (!changelog) {\n        return (\n            <span title={title} className={className}>\n                {children}\n            </span>\n        );\n    }\n\n    return (\n        <>\n            {render && <ChangelogModal {...changelogModal} changelog={changelog} />}\n            <Tooltip title={c('Storage').t`Release notes`}>\n                <button type=\"button\" onClick={() => setChangelogModalOpen(true)} title={title} className={className}>\n                    {children}\n                </button>\n            </Tooltip>\n        </>\n    );\n};\n\nexport default AppVersion;\n","import { AppVersion } from '@proton/components';\n\nconst VpnSidebarVersion = () => {\n    return <AppVersion />;\n};\n\nexport default VpnSidebarVersion;\n","import { useEffect, useState, useRef } from 'react';\nimport * as React from 'react';\nimport { Input } from '@proton/components';\nimport './TVCodeInputs.scss';\n\ninterface Props {\n    value: string;\n    setValue: (value: string) => void;\n}\n\nconst TVCodeInputs = ({ value, setValue }: Props) => {\n    const [first, setFirst] = useState(() => value.substring(0, 4));\n    const [second, setSecond] = useState(() => value.substring(4, 4));\n    const refFirstInput = useRef<HTMLInputElement>(null);\n    const refSecondInput = useRef<HTMLInputElement>(null);\n\n    const handleKeyUpFirst = (event: React.KeyboardEvent<HTMLElement>) => {\n        const eventKey = event.key;\n        if (first.length === 4 && eventKey !== 'Backspace' && eventKey !== 'Delete') {\n            event.preventDefault();\n            refSecondInput?.current?.focus();\n        }\n    };\n\n    const handleKeyUpSecond = (event: React.KeyboardEvent<HTMLElement>) => {\n        const eventKey = event.key;\n        if (second.length === 0 && (eventKey === 'Backspace' || eventKey === 'Delete')) {\n            refFirstInput?.current?.focus();\n            setSecond('');\n        }\n    };\n\n    const handleOnChangeFirst = (event: React.ChangeEvent<HTMLInputElement>) => {\n        if (event.target.value.length > 4) {\n            event.preventDefault();\n            return false;\n        }\n        setFirst(event.target.value.toUpperCase());\n    };\n\n    const handleOnChangeSecond = (event: React.ChangeEvent<HTMLInputElement>) => {\n        if (event.target.value.length > 4) {\n            event.preventDefault();\n            return false;\n        }\n        setSecond(event.target.value.toUpperCase());\n    };\n\n    useEffect(() => {\n        setValue([first, second].join(''));\n    }, [first, second]);\n\n    return (\n        <>\n            <div className=\"code-input-container flex flex-justify-center auto-mobile\">\n                <div className=\"code-input-div flex-item-fluid flex flex-column text-center on-mobile-pb1 on-mobile-pt0-5\">\n                    <Input\n                        ref={refFirstInput}\n                        minLength={4}\n                        maxLength={4}\n                        value={first}\n                        onChange={handleOnChangeFirst}\n                        onKeyUp={handleKeyUpFirst}\n                        placeholder=\"1234\"\n                        className=\"text-bold max-w15e flex-align-self-end mauto\"\n                        required\n                        autoFocus\n                    />\n                </div>\n                <hr className=\"w5 tv-hr ml1 mr1 mt1-5 mbauto no-mobile\" />\n                <div className=\"code-input-div flex-item-fluid flex flex-column text-center on-mobile-pb1 on-mobile-pt0-5\">\n                    <Input\n                        ref={refSecondInput}\n                        minLength={4}\n                        maxLength={4}\n                        value={second}\n                        onChange={handleOnChangeSecond}\n                        onKeyUp={handleKeyUpSecond}\n                        placeholder=\"ABCD\"\n                        className=\"text-bold max-w15e mauto\"\n                        required\n                    />\n                </div>\n            </div>\n        </>\n    );\n};\n\nexport default TVCodeInputs;\n","import { useState } from 'react';\nimport * as React from 'react';\nimport { c } from 'ttag';\nimport { VpnLogo, PrimaryButton, Icon, Href, useApi, useLoading } from '@proton/components';\nimport { pushForkSession } from '@proton/shared/lib/api/auth';\nimport TVCodeInputs from './TVCodeInputs';\n\nenum STEP {\n    ENTER_CODE,\n    DEVICE_CONNECTED,\n}\n\nconst TVContainer = () => {\n    const [code, setCode] = useState('');\n    const [step, setStep] = useState(STEP.ENTER_CODE);\n    const api = useApi();\n    const [loading, withLoading] = useLoading();\n    const [error, setError] = useState('');\n\n    const handleSubmit = async (event: React.FormEvent<HTMLFormElement>) => {\n        event.preventDefault();\n\n        if (loading || !code) {\n            return;\n        }\n\n        try {\n            setError('');\n            await api(\n                pushForkSession({\n                    ChildClientID: 'android_tv-vpn',\n                    Independent: 1,\n                    UserCode: code,\n                })\n            );\n            setStep(STEP.DEVICE_CONNECTED);\n        } catch (error: any) {\n            const { data: { Error = '' } = {} } = error;\n            setError(Error);\n            throw error;\n        }\n    };\n\n    const render = () => {\n        if (step === STEP.ENTER_CODE) {\n            return (\n                <form onSubmit={(event) => withLoading(handleSubmit(event))}>\n                    <label className=\"h3 text-center\" htmlFor=\"code-input\">{c('Label')\n                        .t`Enter the code displayed on your TV`}</label>\n                    <TVCodeInputs value={code} setValue={setCode} />\n                    {error ? (\n                        <>\n                            <p className=\"mt2 mb0 pl1 text-center color-danger\">{c('Error')\n                                .t`Code wrong or not valid anymore`}</p>\n                            <p className=\"m0 text-center border-none\">{c('Error')\n                                .t`If the time on your TV has expired, click on Refresh on your TV and enter your code again.`}</p>\n                        </>\n                    ) : null}\n                    <div className=\"flex\">\n                        <PrimaryButton\n                            loading={loading}\n                            type=\"submit\"\n                            pill\n                            className=\"text-uppercase text-bold mt2 mb1-5 center\"\n                        >\n                            <span className=\"p0-5 inline-flex\">\n                                {error ? c('Action').t`Verify code again` : c('Action').t`Verify code`}\n                            </span>\n                        </PrimaryButton>\n                    </div>\n                </form>\n            );\n        }\n\n        if (step === STEP.DEVICE_CONNECTED) {\n            return (\n                <>\n                    <h2>{c('Title').t`Device connected!`}</h2>\n                    <div className=\"flex flex-justify-center mt2 mb2\">\n                        <span className=\"inline-flex bg-success rounded-50 p2\">\n                            <Icon name=\"checkmark\" size={60} />\n                        </span>\n                    </div>\n                </>\n            );\n        }\n\n        return null;\n    };\n\n    return (\n        <div className=\"ui-prominent background-container h100 flex-no-min-children flex-column flex-nowrap flex-align-items-center scroll-if-needed\">\n            <div className=\"flex flex-justify-center flex-align-items-center pt2\">\n                <div className=\"w150p\">\n                    <Href url=\"https://protonvpn.com\" target=\"_self\">\n                        <VpnLogo />\n                    </Href>\n                </div>\n                <h3 className=\"mb0 pl0-25 text-uppercase text-bold\">{c('Title').t`TV log in`}</h3>\n            </div>\n            <div className=\"flex flex-column flex-item-fluid flex-nowrap flex-item-noshrink\">\n                <div className=\"mauto p2 flex-item-noshrink max-w30e\">{render()}</div>\n            </div>\n        </div>\n    );\n};\n\nexport default TVContainer;\n","import { useEffect, useRef, useState } from 'react';\nimport { Route } from 'react-router';\nimport { useLocation, Redirect, Switch, useHistory } from 'react-router-dom';\nimport { localeCode } from '@proton/shared/lib/i18n';\nimport {\n    TopBanners,\n    Sidebar,\n    useToggle,\n    useUser,\n    PrivateAppContainer,\n    PrivateHeader,\n    useActiveBreakpoint,\n    SidebarList,\n    SidebarNav,\n    SidebarListItemsWithSubsections,\n    MainLogo,\n    ErrorBoundary,\n    StandardErrorPage,\n    AuthenticatedBugModal,\n    useUserSettings,\n    useSubscription,\n    PlansSection,\n    YourPlanSection,\n    BillingSection,\n    CreditsSection,\n    GiftCodeSection,\n    CancelSubscriptionSection,\n    PrivateMainSettingsArea,\n    LanguageSection,\n    PaymentMethodsSection,\n    InvoicesSection,\n    ProtonVPNClientsSection,\n    OpenVPNConfigurationSection,\n    UsernameSection,\n    PasswordsSection,\n    OpenVPNCredentialsSection,\n    AccountRecoverySection,\n    EmailSubscriptionSection,\n    DeleteSection,\n    AutomaticSubscriptionModal,\n    SubscriptionModalProvider,\n    WireGuardConfigurationSection,\n    useModalState,\n    UserDropdown,\n    Unauthenticated,\n} from '@proton/components';\nimport LiveChatZendesk, {\n    ZendeskRef,\n    getIsSelfChat,\n    useCanEnableChat,\n} from '@proton/components/containers/zendesk/LiveChatZendesk';\nimport { c } from 'ttag';\nimport { getIsSectionAvailable } from '@proton/components/containers/layout/helper';\nimport { locales } from '@proton/shared/lib/i18n/locales';\nimport { BugModalMode } from '@proton/components/containers/support/BugModal';\nimport { getRoutes } from './routes';\nimport VpnSidebarVersion from './containers/VpnSidebarVersion';\nimport TVContainer from './containers/TVContainer';\n\nconst vpnZendeskKey = '52184d31-aa98-430f-a86c-b5a93235027a';\n\nconst MainContainer = () => {\n    const [user] = useUser();\n    const [subscription, loadingSubscription] = useSubscription();\n    const [tagsArray, setTagsArray] = useState<string[]>([]);\n    const [userSettings] = useUserSettings();\n    const history = useHistory();\n    const { state: expanded, toggle: onToggleExpand, set: setExpand } = useToggle();\n    const { isNarrow } = useActiveBreakpoint();\n    const location = useLocation();\n    const [activeSection, setActiveSection] = useState('');\n    const zendeskRef = useRef<ZendeskRef>();\n    const [showChat, setShowChat] = useState({ autoToggle: false, render: false });\n    const routes = getRoutes(user);\n    const canEnableChat = useCanEnableChat(user);\n    const [authenticatedBugReportMode, setAuthenticatedBugReportMode] = useState<BugModalMode>();\n    const [authenticatedBugReportModal, setAuthenticatedBugReportModal, render] = useModalState();\n\n    const openAuthenticatedBugReportModal = (mode: BugModalMode) => {\n        setAuthenticatedBugReportMode(mode);\n        setAuthenticatedBugReportModal(true);\n    };\n\n    useEffect(() => {\n        if (loadingSubscription || !canEnableChat) {\n            return;\n        }\n        const subscriptionUserPaid: string[] = subscription?.Plans?.map((plan) => plan.Name) || [];\n        setTagsArray(subscriptionUserPaid);\n    }, [subscription]);\n\n    useEffect(() => {\n        const searchParams = new URLSearchParams(location.search);\n        const hasChatRequest = !!searchParams.get('chat');\n        const isSelfChat = getIsSelfChat();\n\n        searchParams.delete('chat');\n        history.replace({\n            search: searchParams.toString(),\n        });\n        if (hasChatRequest || isSelfChat) {\n            if (canEnableChat) {\n                setShowChat({ autoToggle: hasChatRequest, render: true });\n            } else {\n                openAuthenticatedBugReportModal('chat-unavailable');\n            }\n        }\n    }, []);\n\n    useEffect(() => {\n        setExpand(false);\n    }, [location.pathname, location.hash]);\n\n    const logo = <MainLogo to=\"/\" />;\n\n    const top = <TopBanners />;\n\n    const header = (\n        <PrivateHeader\n            userDropdown={\n                <UserDropdown\n                    onOpenChat={\n                        canEnableChat\n                            ? () => {\n                                  setShowChat({ autoToggle: true, render: true });\n                                  zendeskRef.current?.toggle();\n                              }\n                            : undefined\n                    }\n                />\n            }\n            logo={logo}\n            title={c('Title').t`Settings`}\n            expanded={expanded}\n            onToggleExpand={onToggleExpand}\n            isNarrow={isNarrow}\n            appsDropdown={null}\n        />\n    );\n\n    const sidebar = (\n        <Sidebar\n            logo={logo}\n            expanded={expanded}\n            onToggleExpand={onToggleExpand}\n            version={<VpnSidebarVersion />}\n            hasAppLinks={false}\n        >\n            <SidebarNav>\n                <SidebarList>\n                    <SidebarListItemsWithSubsections\n                        list={Object.values(routes)}\n                        pathname={location.pathname}\n                        activeSection={activeSection}\n                    />\n                </SidebarList>\n            </SidebarNav>\n        </Sidebar>\n    );\n    return (\n        <>\n            {render && <AuthenticatedBugModal mode={authenticatedBugReportMode} {...authenticatedBugReportModal} />}\n            <Switch>\n                <Route path=\"/tv\">\n                    <Unauthenticated>\n                        <TVContainer />\n                    </Unauthenticated>\n                </Route>\n                <Route path=\"*\">\n                    <PrivateAppContainer top={top} header={header} sidebar={sidebar}>\n                        <Switch>\n                            {getIsSectionAvailable(routes.dashboard) && (\n                                <Route path={routes.dashboard.to}>\n                                    <SubscriptionModalProvider>\n                                        <AutomaticSubscriptionModal />\n                                        <PrivateMainSettingsArea\n                                            setActiveSection={setActiveSection}\n                                            location={location}\n                                            config={routes.dashboard}\n                                        >\n                                            <PlansSection />\n                                            <YourPlanSection />\n                                            <BillingSection />\n                                            <CreditsSection />\n                                            <GiftCodeSection />\n                                            <CancelSubscriptionSection />\n                                        </PrivateMainSettingsArea>\n                                    </SubscriptionModalProvider>\n                                </Route>\n                            )}\n                            <Route path={routes.general.to}>\n                                <PrivateMainSettingsArea\n                                    setActiveSection={setActiveSection}\n                                    location={location}\n                                    config={routes.general}\n                                >\n                                    <LanguageSection locales={locales} />\n                                </PrivateMainSettingsArea>\n                            </Route>\n                            <Route path={routes.account.to}>\n                                <PrivateMainSettingsArea\n                                    setActiveSection={setActiveSection}\n                                    location={location}\n                                    config={routes.account}\n                                >\n                                    <UsernameSection />\n                                    <PasswordsSection />\n                                    <OpenVPNCredentialsSection />\n                                    <AccountRecoverySection />\n                                    <EmailSubscriptionSection />\n                                    <DeleteSection />\n                                </PrivateMainSettingsArea>\n                            </Route>\n                            <Route path={routes.downloads.to}>\n                                <PrivateMainSettingsArea\n                                    setActiveSection={setActiveSection}\n                                    location={location}\n                                    config={routes.downloads}\n                                >\n                                    <ProtonVPNClientsSection />\n                                    <OpenVPNConfigurationSection />\n                                    <WireGuardConfigurationSection />\n                                </PrivateMainSettingsArea>\n                            </Route>\n                            {getIsSectionAvailable(routes.payments) && (\n                                <Route path={routes.payments.to}>\n                                    <PrivateMainSettingsArea\n                                        setActiveSection={setActiveSection}\n                                        location={location}\n                                        config={routes.payments}\n                                    >\n                                        <PaymentMethodsSection />\n                                        <InvoicesSection />\n                                    </PrivateMainSettingsArea>\n                                </Route>\n                            )}\n                            <Redirect\n                                to={getIsSectionAvailable(routes.dashboard) ? routes.dashboard.to : routes.downloads.to}\n                            />\n                        </Switch>\n                        {showChat.render && canEnableChat ? (\n                            <LiveChatZendesk\n                                tags={tagsArray}\n                                zendeskRef={zendeskRef}\n                                zendeskKey={vpnZendeskKey}\n                                name={user.DisplayName || user.Name}\n                                email={user.Email || userSettings?.Email?.Value || ''}\n                                onLoaded={() => {\n                                    if (showChat.autoToggle) {\n                                        zendeskRef.current?.toggle();\n                                    }\n                                }}\n                                onUnavailable={() => {\n                                    openAuthenticatedBugReportModal('chat-no-agents');\n                                }}\n                            